import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";

/**
 * Validate proper error handling when deleting a non-existent post like/dislike record.
 *
 * This test attempts to delete a post like/dislike entry using a random UUID that does not
 * correspond to any existing record in the system. The expectation is that the API will respond
 * with a not found error. This ensures that the system properly handles deletion requests
 * for resources that do not exist and does not falsely report success or perform any unwanted side-effects.
 *
 * Steps:
 * 1. Generate a random UUID representing a non-existent like/dislike record.
 * 2. Attempt to delete the post like/dislike with this UUID.
 * 3. Assert that a not-found error occurs and no resource is deleted.
 */
export async function test_api_my_discussion_board_postLikes_test_delete_nonexistent_post_like(
  connection: api.IConnection,
) {
  // 1. Generate a random UUID for a non-existent post like/dislike record
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();

  // 2. Attempt deletion, expecting a not-found error
  await TestValidator.error("Should throw not found error when deleting non-existent post like/dislike")(
    async () => {
      await api.functional.my.discussion_board.postLikes.erase(
        connection,
        { id: nonExistentId }
      );
    },
  );
}

