import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardRoleChange } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardRoleChange";

/**
 * Validate fetching a discussion board role change event by id as admin.
 *
 * Preconditions: Admin privileges are required to create and fetch role change events.
 *
 * Workflow:
 * 1. Create a new role change event as admin using POST /admin/discussion_board/roleChanges
 * 2. Use the returned event id to retrieve the event by GET /admin/discussion_board/roleChanges/{id}
 * 3. Validate the returned object fields match the created data
 * 4. Attempt to fetch the same event as non-admin and assert access is denied
 */
export async function test_api_admin_discussion_board_roleChanges_test_retrieve_role_change_event_by_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a new role change event as admin
  const eventCreateInput: IDiscussionBoardRoleChange.ICreate = {
    target_user_profile_id: typia.random<string & tags.Format<"uuid">>(),
    performed_by_user_profile_id: typia.random<string & tags.Format<"uuid">>(),
    role_type: RandomGenerator.pick([
      "admin", "moderator", "member", "guest"
    ]),
    action_type: RandomGenerator.pick(["assigned", "revoked"]),
    timestamp: new Date().toISOString(),
  };
  const createdEvent: IDiscussionBoardRoleChange = await api.functional.admin.discussion_board.roleChanges.create(
    connection,
    {
      body: eventCreateInput,
    },
  );
  typia.assert(createdEvent);

  // 2. Fetch the event by id as admin
  const fetchedEvent: IDiscussionBoardRoleChange = await api.functional.admin.discussion_board.roleChanges.at(
    connection,
    {
      id: createdEvent.id,
    },
  );
  typia.assert(fetchedEvent);

  // 3. Validate fields match (excluding the generated id, compare input fields)
  TestValidator.equals("target_user_profile_id matches")(fetchedEvent.target_user_profile_id)(eventCreateInput.target_user_profile_id);
  TestValidator.equals("performed_by_user_profile_id matches")(fetchedEvent.performed_by_user_profile_id)(eventCreateInput.performed_by_user_profile_id);
  TestValidator.equals("role_type matches")(fetchedEvent.role_type)(eventCreateInput.role_type);
  TestValidator.equals("action_type matches")(fetchedEvent.action_type)(eventCreateInput.action_type);
  TestValidator.equals("timestamp matches")(fetchedEvent.timestamp)(eventCreateInput.timestamp);

  // 4. Attempt to retrieve as non-admin (simulate non-admin connection), expect error
  const nonAdminConnection = { ...connection, headers: {} };
  await TestValidator.error("Should deny access for non-admin")(
    async () => {
      await api.functional.admin.discussion_board.roleChanges.at(
        nonAdminConnection as api.IConnection,
        { id: createdEvent.id },
      );
    },
  );
}

