import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * 테스트 목적: 이미 중재자(moderator)로 지정된 사용자에게 다시 중재자 역할을 할당하려고 시도할 때, API가 사용자 단위 고유 제약조건 위반 오류를 올바르게 반환하는지 검증합니다.
 * 
 * 비즈니스 컨텍스트: 중재자 역할은 각 사용자마다 유일해야 하며, 이미 중재자로 지정된 사용자에게 또다시 같은 역할을 부여할 경우, 데이터베이스의 고유성 제약 조건 상 오류가 발생해야 합니다. 이로써 한 사용자가 중복 중재자 역할을 가질 수 없음을 보장합니다.
 *
 * 테스트 진행 단계:
 * 1. 관리자가 새로운 사용자 프로필을 생성합니다.
 * 2. 방금 생성한 사용자에게 중재자 역할을 부여합니다.
 * 3. 동일한 사용자에게 다시 한 번 중재자 역할을 부여하려 시도합니다. 이때 API가 적절한 고유 제약조건(Unique Constraint Violation) 오류를 반환하는지 확인합니다.
 */
export async function test_api_admin_discussion_board_moderators_test_create_moderator_with_duplicate_assignment(
  connection: api.IConnection,
) {
  // 1. 새로운 사용자 프로필 생성
  const userProfile = await api.functional.admin.discussion_board.userProfiles.create(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      is_active: true,
      // registered_at은 생략 시 시스템 현재 시각
    } satisfies IDiscussionBoardUserProfile.ICreate,
  });
  typia.assert(userProfile);

  // 2. 중재자 역할 부여 (처음 할당: 성공해야 함)
  const moderator = await api.functional.admin.discussion_board.moderators.create(connection, {
    body: {
      discussion_board_user_profile_id: userProfile.id,
      assigned_at: new Date().toISOString(),
      assigned_by_user_profile_id: userProfile.id, // 테스트 편의상 자신이 할당
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderator);

  // 3. 동일 사용자에 대해 중복 할당 시도 -> 반드시 에러 발생해야 함
  await TestValidator.error("중복 중재자 지정시 Unique Constraint Violation 오류")(async () => {
    await api.functional.admin.discussion_board.moderators.create(connection, {
      body: {
        discussion_board_user_profile_id: userProfile.id,
        assigned_at: new Date().toISOString(),
        assigned_by_user_profile_id: userProfile.id,
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  });
}

