  const firstPage = await api.functional.discussion_board.configurations.index(connection, {
    body: {
      page: 1,
      limit: 2,
      sort_field: "key",
      sort_order: "asc",
      search: null,
    },
  });
  typia.assert(firstPage);
  TestValidator.predicate("firstPage.data not oversized")(firstPage.data.length <= 2);
  if (firstPage.data.length > 0) {
