  const byCreatedAtAsc = await api.functional.discussion_board.configurations.index(connection, {
    body: {
      page: 1,
      limit: 1,
      sort_field: "created_at",
      sort_order: "asc",
    },
  });
  typia.assert(byCreatedAtAsc);
  const byCreatedAtDesc = await api.functional.discussion_board.configurations.index(connection, {
    body: {
      page: 1,
      limit: 1,
      sort_field: "created_at",
      sort_order: "desc",
