import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardCategoryPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategoryPermission";

/**
 * Test updating an existing category permission (by ID) by changing one or more of the boolean permission fields
 * (e.g., can_reply to false, can_like to true). Validate that the updated entry reflects these changes and no
 * unauthorized fields are modified. Confirm auditability and role enforcement.
 *
 * 1. Create a discussion board category (as admin)
 * 2. Create a category permission entry for this category with all booleans preset
 * 3. Update the permission by toggling can_reply and can_like values
 * 4. Check that only these fields changed, and all other fields (category_id, role_name, other permissions) remain the same
 * 5. Validate that the updated object is returned and matches the changes
 * 6. Confirm timestamps and audit fields as appropriate (created_at should stay immutable)
 */
export async function test_api_admin_discussion_board_categoryPermissions_test_update_category_permission_with_valid_fields(
  connection: api.IConnection,
) {
  // 1. Create a discussion board category (admin)
  const categoryInput: IDiscussionBoardCategory.ICreate = {
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph()(2),
    description: RandomGenerator.paragraph()(1),
    sort_order: typia.random<number & tags.Type<"int32">>(),
    is_active: true,
  };
  const category = await api.functional.admin.discussion_board.categories.create(connection, { body: categoryInput });
  typia.assert(category);

  // 2. Create a permission entry for this category so we have a valid permission row
  const permInput: IDiscussionBoardCategoryPermission.ICreate = {
    category_id: category.id,
    role_name: "member",
    can_view: true,
    can_create_topic: true,
    can_reply: true,
    can_like: false,
    can_report: false,
  };
  const permission = await api.functional.admin.discussion_board.categoryPermissions.create(
    connection,
    { body: permInput },
  );
  typia.assert(permission);

  // 3. Update some boolean permission values (toggle only can_reply/can_like)
  const updateInput: IDiscussionBoardCategoryPermission.IUpdate = {
    can_reply: false,
    can_like: true,
  };
  const updated = await api.functional.admin.discussion_board.categoryPermissions.update(
    connection,
    { id: permission.id, body: updateInput },
  );
  typia.assert(updated);

  // 4. Check that _only_ the updated fields changed and others remained same
  TestValidator.equals("id should not change")(updated.id)(permission.id);
  TestValidator.equals("category_id should not change")(updated.category_id)(permission.category_id);
  TestValidator.equals("role_name should not change")(updated.role_name)(permission.role_name);
  TestValidator.equals("can_view should not change")(updated.can_view)(permission.can_view);
  TestValidator.equals("can_create_topic should not change")(updated.can_create_topic)(permission.can_create_topic);
  TestValidator.notEquals("can_reply should have changed")(updated.can_reply)(permission.can_reply);
  TestValidator.notEquals("can_like should have changed")(updated.can_like)(permission.can_like);
  TestValidator.equals("can_report should not change")(updated.can_report)(permission.can_report);
  // 5. Validate that the updated object reflects the requested updates
  TestValidator.equals("can_reply updated")(updated.can_reply)(updateInput.can_reply);
