    connection,
    {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        display_name: RandomGenerator.name(),
        is_active: true
      } satisfies IDiscussionBoardUserProfile.ICreate
    }
  );
  typia.assert(userProfile);

  // 2. Assign this profile as a member
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userProfile.id,
        joined_at: new Date().toISOString(),
      } satisfies IDiscussionBoardMember.ICreate
    }
  );
  typia.assert(member);

  // 3. Query for topic subscriptions for this member (should have no subscriptions)
  const queryResult = await api.functional.discussion_board.topicSubscriptions.index(
    connection,
    {
      body: {
        member_id: member.id
      } satisfies IDiscussionBoardTopicSubscription.IRequest
    }
  );
  typia.assert(queryResult);

  // 4. Validate that data array is empty
  TestValidator.equals("no topic subscriptions for member")(queryResult.data.length)(0);
  TestValidator.equals("data is []")(queryResult.data)([]);
}

