 * 5. Fetch the like/dislike by its ID.
 * 6. Assert that all fields (id, post ID, author member ID, is_like, created_at) match the record that was created.
 *
 * This tests correct PK retrieval and field integrity for post likes/dislikes.
 */
export async function test_api_discussion_board_test_fetch_post_like_by_id_success(
  connection: api.IConnection,
) {
  // 1. Admin: Create user profile for member
  const profile = await api.functional.admin.discussion_board.userProfiles.create(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      is_active: true,
    },
  });
  typia.assert(profile);

  // 2. Admin: Assign member
  const member = await api.functional.admin.discussion_board.members.create(connection, {
    body: {
      discussion_board_user_profile_id: profile.id,
      joined_at: new Date().toISOString(),
    },
  });
  typia.assert(member);

  // 3. Member: Create a post
  // As authorization and topic management are not in scope, use random topic ID
  const discussion_board_topic_id = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.my.discussion_board.posts.create(connection, {
    body: {
      discussion_board_topic_id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 4. Member: Like/dislike the post
  const is_like = true;
  const postLike = await api.functional.my.discussion_board.postLikes.create(connection, {
    body: {
      discussion_board_post_id: post.id,
      is_like,
    },
  });
  typia.assert(postLike);

  // 5. Fetch the like/dislike by its ID
  const fetched = await api.functional.discussion_board.postLikes.at(connection, {
    id: postLike.id,
  });
  typia.assert(fetched);

  // 6. Validate all fields match the created record
  TestValidator.equals("postLike.id")(fetched.id)(postLike.id);
  TestValidator.equals("discussion_board_post_id")(fetched.discussion_board_post_id)(postLike.discussion_board_post_id);
  TestValidator.equals("author_member_id")(fetched.author_member_id)(postLike.author_member_id);
  TestValidator.equals("is_like")(fetched.is_like)(postLike.is_like);
  TestValidator.equals("created_at")(fetched.created_at)(postLike.created_at);
}

