  connection: api.IConnection,
) {
  // 1. Admin creates a user profile
  const registered_at = new Date().toISOString();
  const userProfile = await api.functional.admin.discussion_board.userProfiles.create(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      registered_at,
      is_active: true,
    },
  });
  typia.assert(userProfile);

  // 2. Admin assigns as board member
  const member = await api.functional.admin.discussion_board.members.create(connection, {
    body: {
      discussion_board_user_profile_id: userProfile.id,
      joined_at: registered_at,
    },
  });
  typia.assert(member);

  // 3. Admin creates a category
  const category = await api.functional.admin.discussion_board.categories.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(1),
      description: null,
      sort_order: 1,
      is_active: true,
    },
  });
  typia.assert(category);

  // 4. Member creates a topic in the category
  // Assumes connection now has member's authentication if necessary
  const topic = await api.functional.my.discussion_board.topics.create(connection, {
    body: {
      discussion_board_category_id: category.id,
      title: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()()(),
      status: "open",
      pinned_at: null,
      closed_at: null,
    },
  });
  typia.assert(topic);

  // 5. Member creates a post in the topic
  const post = await api.functional.my.discussion_board.posts.create(connection, {
    body: {
      discussion_board_topic_id: topic.id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);
  TestValidator.equals("is_deleted initial")(post.is_deleted)(false);

  // 6. Member soft-deletes their post
  const erased = await api.functional.my.discussion_board.posts.erase(connection, {
    id: post.id,
  });
  typia.assert(erased);
  TestValidator.equals("is_deleted after erase")(erased.is_deleted)(true);

  // 7. (Not directly testable here) Exclusion from standard queries would be validated by separate read/list tests.
}

