import type { IDiscussionBoardTopicSubscription } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopicSubscription";

/**
 * 검증: 토픽 구독 ID로 토픽 구독 상세 조회
 *
 * 이 테스트는 토론 게시판 회원이 실제로 토픽을 구독한 뒤, 해당 구독 ID를 사용해 토픽 구독 상세 정보를 조회할 수 있음을 검증합니다. 구독이 실제로 존재하는 상황을 설정하기 위해, 모든 선행 조건을 실제 흐름대로 진행합니다.
 *
 * 1. 어드민 권한으로 유저 프로필을 생성한다. (id, email 등)
 * 2. 해당 유저 프로필을 토론 게시판 회원으로 등록한다. (joined_at 시간 지정)
 * 3. 카테고리를 하나 생성한다. (code, name 등 필수)
 * 4. (회원 인증 컨텍스트로 전환이 필요하다면 전환) 새로 생성된 카테고리로 토픽을 생성한다. (title, description, status)
 * 5. 생성된 토픽에 회원이 구독을 건다. (POST /my/discussion_board/topicSubscriptions)
 * 6. 구독 생성 결과의 id로 구독 상세를 조회한다. (GET /discussion_board/topicSubscriptions/{id})
 * 7. 모든 주요 필드 값의 일관성과 스키마 준수 여부를 확인한다.
 */
export async function test_api_discussion_board_test_get_topic_subscription_by_id_when_subscription_exists(
  connection: api.IConnection,
) {
  // 1. 어드민 권한으로 유저 프로필 생성
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userProfile = await api.functional.admin.discussion_board.userProfiles.create(connection, {
    body: {
      email: userEmail,
      display_name: RandomGenerator.name(),
      registered_at: new Date().toISOString(),
      is_active: true,
    }
  });
  typia.assert(userProfile);

  // 2. 위 프로필을 멤버로 등록
  const member = await api.functional.admin.discussion_board.members.create(connection, {
    body: {
      discussion_board_user_profile_id: userProfile.id,
      joined_at: new Date().toISOString(),
    }
  });
  typia.assert(member);

  // 3. 카테고리 생성
  const categoryCode = RandomGenerator.alphaNumeric(8);
  const category = await api.functional.admin.discussion_board.categories.create(connection, {
    body: {
      code: categoryCode,
      name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()(1)(),
      sort_order: 1,
      is_active: true
    }
  });
  typia.assert(category);

  // 4. 토픽 생성 (회원 인증 컨텍스트 필요시 connection 교체; 현재는 단일 connection 활용)
  const topic = await api.functional.my.discussion_board.topics.create(connection, {
    body: {
      discussion_board_category_id: category.id,
      title: RandomGenerator.paragraph()(1),
      description: RandomGenerator.content()(1)(),
      status: "open"
    }
  });
  typia.assert(topic);

  // 5. 회원이 방금 만든 토픽을 구독
  const subscription = await api.functional.my.discussion_board.topicSubscriptions.create(connection, {
    body: {
      discussion_board_topic_id: topic.id
    }
  });
  typia.assert(subscription);

  // 6. 구독 id로 상세 조회
  const found = await api.functional.discussion_board.topicSubscriptions.at(connection, {
    id: subscription.id
  });
  typia.assert(found);

  // 7. 주요 필드 검증 (구독 토픽/멤버 일치 등)
  TestValidator.equals("subscription.id")(found.id)(subscription.id);
  TestValidator.equals("topic id")(found.discussion_board_topic_id)(topic.id);
  TestValidator.equals("member id")(found.member_id)(subscription.member_id);
  TestValidator.predicate("subscribed_at timestamp exists")(typeof found.subscribed_at === "string" && found.subscribed_at.length > 0);
  TestValidator.equals("unsubscribed_at is null or string")(found.unsubscribed_at === null || typeof found.unsubscribed_at === "string")(true);
}

