import type { IDiscussionBoardFlaggedContent } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardFlaggedContent";

/**
 * Validate admin creation of flagged content (discussion_board_flagged_content).
 *
 * This test verifies that an admin can successfully create a flagged content entry by providing all schema-required fields: flagged_by_admin_id, flagged_entity_id, flagged_entity_type, flag_type, reason, cleared, created_at (with proper UUIDs and content type strings).
 * It also validates the basic entity workflow integration by first creating a moderation log (as a dependency), confirming linkage, and ensuring that unique context constraints are enforced—such as only allowing one flag per content/admin/context combination.
 *
 * 1. Create a required moderation log (records the moderation event, generates a valid admin_id/reference).
 * 2. Use its admin_id and the generated timestamps to submit a flagged content create request, with all properties completed.
 * 3. Confirm that the response is a full flagged content object, schemas and properties are present, and linkages make business sense.
 * 4. Try creating a duplicate flagged content entry with the same context and expect a validation or logic error (cannot flag the same entity/type/flag_type again).
 * 5. Validate error returns on missing or malformed properties (e.g., omit flagged_entity_id, send invalid UUID, etc). Only check error occurrence, do not check error message.
 */
export async function test_api_admin_discussion_board_flaggedContent_test_create_flagged_content_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create a moderation log entry as dependency
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();
  const moderationLog = await api.functional.admin.discussion_board.moderationLogs.create(
    connection,
    {
      body: {
        log_type: "remove_content",
        admin_id: adminId,
        moderator_id: null,
        report_id: null,
        details: "Flagged by admin prior to full investigation.",
        created_at: now,
      },
    },
  );
  typia.assert(moderationLog);

  // 2. Create flagged content using values referencing moderation log
  const flaggedEntityId = typia.random<string & tags.Format<"uuid">>();
  const flaggedEntityType = "post";
  const flagType = "manual";
  const reason = "Suspected spam/abuse";

  const flaggedContent = await api.functional.admin.discussion_board.flaggedContent.create(
    connection,
    {
      body: {
        flagged_by_admin_id: adminId,
        flagged_by_moderator_id: null,
        flagged_entity_id: flaggedEntityId,
        flagged_entity_type: flaggedEntityType,
        flag_type: flagType,
        reason: reason,
        cleared: false,
        created_at: now,
      },
    },
  );
  typia.assert(flaggedContent);
  TestValidator.equals("admin_id matches moderation log")
    (flaggedContent.flagged_by_admin_id)
    (adminId);
  TestValidator.equals("entity id matches input")
    (flaggedContent.flagged_entity_id)
    (flaggedEntityId);
  TestValidator.equals("flag type matches input")
    (flaggedContent.flag_type)
    (flagType);
  TestValidator.equals("not cleared")
    (flaggedContent.cleared)
    (false);

  // 3. Try to flag the same entity/type/context again (should fail)
  await TestValidator.error("duplicate flag should fail")(
    () => api.functional.admin.discussion_board.flaggedContent.create(
      connection,
      {
        body: {
          flagged_by_admin_id: adminId,
          flagged_by_moderator_id: null,
          flagged_entity_id: flaggedEntityId,
          flagged_entity_type: flaggedEntityType,
          flag_type: flagType,
          reason: reason,
          cleared: false,
          created_at: now,
        },
      },
    ),
  );

  // 4. Validation: missing required field (flagged_entity_id)
  await TestValidator.error("missing flagged_entity_id fails")(
    () => api.functional.admin.discussion_board.flaggedContent.create(
      connection,
      {
        body: {
          flagged_by_admin_id: adminId,
          flagged_by_moderator_id: null,
          // flagged_entity_id missing
          flagged_entity_type: flaggedEntityType,
          flag_type: flagType,
          reason: reason,
          cleared: false,
          created_at: now,
        } as any,
      },
    ),
  );

  // 5. Validation: malformed UUID for flagged_by_admin_id
  await TestValidator.error("malformed flagged_by_admin_id fails")(
    () => api.functional.admin.discussion_board.flaggedContent.create(
      connection,
      {
        body: {
          flagged_by_admin_id: "bad-uuid-value",
          flagged_by_moderator_id: null,
          flagged_entity_id: flaggedEntityId,
          flagged_entity_type: flaggedEntityType,
          flag_type: flagType,
          reason: reason,
          cleared: false,
          created_at: now,
        } as any,
      },
    ),
  );
}

