import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";

/**
 * 테스트 목적: 관리자(admin)가 이미 존재하는 토론 게시판 멤버 할당의 가입/탈퇴(시작/종료) 시각을 업데이트하고, 연관된 비즈니스 비정상/에러 상황도 검증한다.
 *
 * 1. 관리자가 새로운 사용자 프로필을 생성한다.
 * 2. 해당 프로필을 토론 게시판 멤버로 할당한다(멤버 생성).
 * 3. 멤버 레코드의 joined_at(가입 시각)과 left_at(탈퇴 시각)을 다른 값으로 변경한다.
 *    - joined_at을 최근값으로 변경, left_at은 null 또는 미래/과거/현재 일시 등 다르게 시도하여 정상반영됨을 확인.
 * 4. 업데이트한 뒤 결과가 올바르게 반영되는지 확인한다.
 * 5. 비즈니스 규칙: left_at이 joined_at 이전이 될 수 없도록 되어 있다면, left_at < joined_at의 경우 오류발생(실패)이 되는지 확인한다.
 * 6. 존재하지 않는 member id로 업데이트 시도시 404 error 반환도 확인한다.
 */
export async function test_api_admin_discussion_board_members_test_admin_update_member_join_and_leave_times(
  connection: api.IConnection,
) {
  // 1. 사용자 프로필 생성
  const userProfile = await api.functional.admin.discussion_board.userProfiles.create(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      is_active: true,
      // registered_at optional (생략하면 자동)
    } satisfies IDiscussionBoardUserProfile.ICreate,
  });
  typia.assert(userProfile);

  // 2. 멤버 할당 생성
  const member = await api.functional.admin.discussion_board.members.create(connection, {
    body: {
      discussion_board_user_profile_id: userProfile.id,
      joined_at: typia.random<string & tags.Format<"date-time">>(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 3. joined_at, left_at 업데이트 (정상 케이스)
  const newJoinedAt = typia.random<string & tags.Format<"date-time">>();
  const newLeftAt = typia.random<string & tags.Format<"date-time">>();
  const updated = await api.functional.admin.discussion_board.members.update(connection, {
    id: member.id,
    body: {
      joined_at: newJoinedAt,
      left_at: newLeftAt,
    } satisfies IDiscussionBoardMember.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("joined_at 업데이트 반영")(updated.joined_at)(newJoinedAt);
  TestValidator.equals("left_at 업데이트 반영")(updated.left_at)(newLeftAt);

  // 4. left_at=null 처리 (현직 멤버 유지)
  const updated2 = await api.functional.admin.discussion_board.members.update(connection, {
    id: member.id,
    body: {
      joined_at: newJoinedAt,
      left_at: null,
    } satisfies IDiscussionBoardMember.IUpdate,
  });
  typia.assert(updated2);
  TestValidator.equals("left_at null 반영")(updated2.left_at)(null);

  // 5. 비즈니스 룰 위반: left_at < joined_at이면 오류
  const impossibleJoinedAt = "2025-07-28T09:40:08.659+09:00";
  const impossibleLeftAt = "2023-01-01T00:00:00.000+09:00";
  await TestValidator.error("left_at이 joined_at보다 이전이면 에러")(async () => {
    await api.functional.admin.discussion_board.members.update(connection, {
      id: member.id,
      body: {
        joined_at: impossibleJoinedAt,
        left_at: impossibleLeftAt,
      } satisfies IDiscussionBoardMember.IUpdate,
    });
  });

  // 6. 존재하지 않는 id로 업데이트 → 404 에러 발생확인
  await TestValidator.error("존재하지 않는 member id 업데이트 시도 시 404")(async () => {
    await api.functional.admin.discussion_board.members.update(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        joined_at: typia.random<string & tags.Format<"date-time">>(),
        left_at: null,
      } satisfies IDiscussionBoardMember.IUpdate,
    });
  });
}

