import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";

/**
 * Test updating the body text of an already existing comment as its author.
 *
 * This test ensures that an authenticated user (the comment's author) is able to
 * successfully update the body of their own comment on a discussion board post.
 * It covers the following business requirements:
 *   - Comments can be edited by their author (ownership enforced by authentication context)
 *   - Only schema-allowed fields can be updated (body, and possibly parent_id, is_deleted)
 *   - Updated comment content is persisted and reflects properly in the response
 *   - Non-updatable fields (id, author_member_id, etc.) remain immutable
 *
 * **Test Steps:**
 * 1. Create a discussion board post for commenting.
 * 2. Create a comment as the authenticated user on that post.
 * 3. Update the comment's body text as the comment's author.
 * 4. Validate that the returned comment object contains the new body text,
 *    unchanged id/author/ownership fields, and valid timestamps.
 * 5. Assert type and schema integrity of the response.
 */
export async function test_api_my_discussion_board_comments_test_update_own_comment_body_success(
  connection: api.IConnection,
) {
  // 1. Create a discussion board post
  const topicId = typia.random<string & tags.Format<"uuid">>();
  const postBody = {
    discussion_board_topic_id: topicId,
    title: "Original Post Title",
    body: "This is the body of the post.",
  } satisfies IDiscussionBoardPost.ICreate;
  const post = await api.functional.my.discussion_board.posts.create(connection, { body: postBody });
  typia.assert(post);

  // 2. Create a comment on the post
  const commentBody = {
    discussion_board_post_id: post.id,
    body: "Original comment content.",
  } satisfies IDiscussionBoardComment.ICreate;
  const comment = await api.functional.my.discussion_board.comments.create(connection, { body: commentBody });
  typia.assert(comment);

  // 3. Update the comment's body as its author
  const updatedBody = "Updated comment text!";
  const updatedComment = await api.functional.my.discussion_board.comments.update(connection, {
    id: comment.id,
    body: { body: updatedBody } satisfies IDiscussionBoardComment.IUpdate,
  });
  typia.assert(updatedComment);

  // 4. Validate that the comment is updated and schema fields are consistent
  TestValidator.equals("id should not change")(updatedComment.id)(comment.id);
  TestValidator.equals("post relation remains")(updatedComment.discussion_board_post_id)(comment.discussion_board_post_id);
  TestValidator.equals("author does not change")(updatedComment.author_member_id)(comment.author_member_id);
  TestValidator.equals("body is updated")(updatedComment.body)(updatedBody);
  TestValidator.equals("soft deletion is false")(updatedComment.is_deleted)(false);
  // updated_at should be changed, created_at should stay the same
  TestValidator.equals("created_at remains")(updatedComment.created_at)(comment.created_at);
  TestValidator.notEquals("updated_at should change")(updatedComment.updated_at)(comment.updated_at);
}

