  TestValidator.equals("details matches")(found.details)(created.details);
  TestValidator.equals("created_at matches")(found.created_at)(created.created_at);
  // 4. Optional: create & fetch an older record
  const oldTimestamp = new Date(Date.now() - 365*24*3600*1000).toISOString() as string & tags.Format<"date-time">;
  const inputOld: IDiscussionBoardAuditTrail.ICreate = {
