    body: {
      discussion_board_topic_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 4. Member uploads an attachment to the post
  const attachment = await api.functional.my.discussion_board.postAttachments.create(connection, {
    body: {
