import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationLog";

/**
 * 테스트 목적: 존재하지 않는 admin_id 또는 moderator_id로 moderation log를 생성할 때 실패해야 함을 검증합니다.
 *
 * 비즈니스/기능적 맥락:
 * moderation log 엔트리 생성 시 admin_id 또는 moderator_id는 외부키(존재하는 관리자/모더레이터)와 연결되어야 합니다. 유효하지 않은(존재하지 않는) UUID를 사용하면 foreign key 오류 또는 유효성 검증 오류가 발생해야 하며, moderation_log 엔트리는 DB에 남지 않아야 합니다.
 *
 * 테스트 절차:
 * 1. 완전히 무작위 UUID 값(존재하지 않는 값)을 admin_id에 설정한 moderation log 생성 요청 실행
 * 2. 에러가 발생하는지(TestValidator.error로) 검증 (foreign key 또는 validation 오류)
 * 3. 완전히 무작위 UUID 값(존재하지 않는 값)을 moderator_id에 설정한 moderation log 생성 요청 실행
 * 4. 에러가 발생하는지(TestValidator.error로) 검증 (foreign key 또는 validation 오류)
 * 5. (존재하지 않는 id가 추가로 생성되지 않는다거나 moderation log가 생성되지 않는지 검증 하고싶으나, moderation log 조회 API가 주어지지 않은 관계로 해당 검증은 생략)
 */
export async function test_api_admin_discussion_board_moderationLogs_test_create_moderation_log_with_invalid_reference_id(
  connection: api.IConnection,
) {
  // 1. 무효한 admin_id로 시도
  await TestValidator.error("존재하지 않는 admin_id에 대해 moderation log 생성이 실패해야 함")(
    async () => {
      await api.functional.admin.discussion_board.moderationLogs.create(connection, {
        body: {
          log_type: "block_user",
          admin_id: typia.random<string & tags.Format<"uuid">>(), // 완전 무작위 uuid (존재하지 않음)
          moderator_id: null,
          report_id: null,
          details: "Foreign key test - invalid admin_id",
        } satisfies IDiscussionBoardModerationLog.ICreate,
      });
    },
  );

  // 2. 무효한 moderator_id로 시도
  await TestValidator.error("존재하지 않는 moderator_id에 대해 moderation log 생성이 실패해야 함")(
    async () => {
      await api.functional.admin.discussion_board.moderationLogs.create(connection, {
        body: {
          log_type: "remove_content",
          admin_id: null,
          moderator_id: typia.random<string & tags.Format<"uuid">>(), // 완전 무작위 uuid (존재하지 않음)
          report_id: null,
          details: "Foreign key test - invalid moderator_id",
        } satisfies IDiscussionBoardModerationLog.ICreate,
      });
    },
  );
}

