import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostLike";

/**
 * 검증: 다른 사용자가 생성한 게시글 좋아요/싫어요 레코드를 삭제할 수 없는지 확인하는 시나리오.
 *
 * - 두 명의 사용자(회원)를 생성하고 멤버십을 부여한다.
 * - 첫 번째 사용자가 게시글을 생성한다.
 * - 첫 번째 사용자가 그 게시글에 좋아요(혹은 싫어요)를 남긴다.
 * - 두 번째 사용자가 같은 게시글에 남겨진 첫 번째 사용자의 좋아요/싫어요 레코드를 삭제 시도한다.
 *
 * 이때 두 번째 사용자는 자신이 남기지 않은 타인의 피드백 레코드이므로 삭제에 실패해야 하며, 권한 오류(Forbidden 또는 적절한 에러)가 반환되어야 한다.
 */
export async function test_api_discussion_board_postLikes_test_delete_post_like_not_owned_by_user(
  connection: api.IConnection,
) {
  // 1. 두 명의 사용자 프로필을 생성 (관리자 권한 필요)
  const user1Profile = await api.functional.admin.discussion_board.userProfiles.create(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      is_active: true,
    } satisfies IDiscussionBoardUserProfile.ICreate,
  });
  typia.assert(user1Profile);

  const user2Profile = await api.functional.admin.discussion_board.userProfiles.create(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      is_active: true,
    } satisfies IDiscussionBoardUserProfile.ICreate,
  });
  typia.assert(user2Profile);

  // 2. 두 사용자 모두를 회원으로 지정 (관리자 권한 필요)
  const now = new Date().toISOString();
  const user1Member = await api.functional.admin.discussion_board.members.create(connection, {
    body: {
      discussion_board_user_profile_id: user1Profile.id,
      joined_at: now,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(user1Member);
  const user2Member = await api.functional.admin.discussion_board.members.create(connection, {
    body: {
      discussion_board_user_profile_id: user2Profile.id,
      joined_at: now,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(user2Member);

  // 3. user1(회원 1번)로 인증 컨텍스트를 전환한다고 가정, 게시글을 등록
  // (테스트 환경에서는 관리자가 인증 컨텍스트 스위칭 코드 필요)
  // 테스트 시나리오에서는 user1로 인증된 상태라고 간주하고 게시글 작성
  const topicId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.my.discussion_board.posts.create(connection, {
    body: {
      discussion_board_topic_id: topicId,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. user1이 해당 게시글에 좋아요(또는 싫어요)를 남김
  const like = await api.functional.my.discussion_board.postLikes.create(connection, {
    body: {
      discussion_board_post_id: post.id,
      is_like: true,
    } satisfies IDiscussionBoardPostLike.ICreate,
  });
  typia.assert(like);

  // 5. user2(회원 2번)로 인증 컨텍스트 전환(테스트 환경에서), user2가 user1의 좋아요를 삭제 시도
  // (사용자 인증 전환이 실제로 필요하며, 여기서는 인증 context가 user2로 된 상태로 삭제 시도)
  await TestValidator.error("타인이 남긴 좋아요/싫어요 삭제 차단됨")(
    async () => {
      await api.functional.my.discussion_board.postLikes.erase(connection, {
        id: like.id,
      });
    },
  );
}

