import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardUserNotificationSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserNotificationSettings";

/**
 * Validate error handling when updating notification settings using an invalid or unauthorized id.
 *
 * This test ensures that attempting to update a user notification settings record by a UUID that does not correspond to any settings owned by the currently authenticated member results in the correct error response (404 Not Found or Forbidden).
 *
 * Steps:
 * 1. Onboard a new discussion board user profile via admin endpoint.
 * 2. Assign the onboarded profile as a board member.
 * 3. Attempt to update notification settings using a random UUID that does not belong to the member (and no settings record exists yet for this member).
 * 4. Validate that the API returns a 404 Not Found or forbidden error when trying to update the non-existent/unauthorized notification settings record.
 */
export async function test_api_my_discussion_board_userNotificationSettings_test_update_notification_settings_invalid_id(connection: api.IConnection) {
  // 1. Onboard a user profile
  const profile = await api.functional.admin.discussion_board.userProfiles.create(
    connection,
    {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        display_name: RandomGenerator.name(),
        is_active: true,
        registered_at: new Date().toISOString() as string & tags.Format<"date-time">,
      } satisfies IDiscussionBoardUserProfile.ICreate
    }
  );
  typia.assert(profile);

  // 2. Assign as discussion board member
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: profile.id,
        joined_at: new Date().toISOString() as string & tags.Format<"date-time">,
      } satisfies IDiscussionBoardMember.ICreate
    }
  );
  typia.assert(member);

  // 3. Try update with an invalid (random) UUID that does not belong to this user (also, no notification settings exist for this member)
  const invalidId = typia.random<string & tags.Format<"uuid">>();
  // Prepare a valid update body (all true, for example, mutes cleared)
  const updateBody = {
    receive_email_notifications: true,
    receive_push_notifications: true,
    mute_types: null,
  } satisfies IDiscussionBoardUserNotificationSettings.IUpdate;

  // 4. Attempt update and expect error response (404 or forbidden)
  await TestValidator.error("Should fail on non-existent notification settings id")(
    () => api.functional.my.discussion_board.userNotificationSettings.update(
      connection,
      {
        id: invalidId,
        body: updateBody
      }
    )
  );
}

