export async function test_api_admin_discussion_board_moderationLogs_test_list_moderation_logs_with_pagination_and_filters(
  connection: api.IConnection,
) {
  // Step 1: Create discussion board moderation logs for test coverage
  // We'll generate:
  // - 2 logs (type 'block_user') for admin1
  // - 1 log (type 'remove_content') for admin2
  // - 1 log (type 'restore_content') for admin1 with report_id + details
  const admin1_id = typia.random<string & tags.Format<"uuid">>();
  const admin2_id = typia.random<string & tags.Format<"uuid">>();
