          admin_id: admin1_id,
          moderator_id: null,
          details: "IP block.",
          report_id: null,
        } satisfies IDiscussionBoardModerationLog.ICreate,
      }
    ),
    await api.functional.admin.discussion_board.moderationLogs.create(
      connection,
      {
        body: {
          log_type: "remove_content",
          admin_id: admin2_id,
          moderator_id: null,
          details: "Removed inappropriate post.",
