import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostLike";

/**
 * 테스트 목적: 멤버가 한 번도 좋아요/싫어요를 누르지 않은 게시글에 대해 dislike(싫어요, is_like=false) 기록을 생성할 수 있는지 검증합니다.
 *
 * 비즈니스 플로우:
 * 1. 관리자가 새로운 유저 프로필을 생성합니다.
 * 2. 해당 유저 프로필을 멤버로 등록합니다.
 * 3. 임의(별도의 멤버)로 다른 게시글을 생성합니다.
 * 4. 생성한 유저(멤버)로 로그인 컨텍스트를 맞추고 해당 게시글에 대해 dislike를 등록합니다(is_like=false).
 *
 * 검증 사항:
 * - 응답 엔터티가 정상적으로 반환되고 필드 값이 올바른지 확인합니다.
 * - 실제로 is_like=false로 기록되어 반환되는지 확인합니다.
 * - author_member_id 및 discussion_board_post_id가 실제로 입력값과 일치하는지 확인합니다.
 * - 중복 아닌 최초 등록임을 보장하기 위해 조합이 새로워야 하며, 정상적인 데이터 흐름임을 확인합니다.
 */
export async function test_api_my_discussion_board_postLikes_test_create_post_dislike_success(
  connection: api.IConnection,
) {
  // 1. 관리자가 user profile 생성
  const userProfile = await api.functional.admin.discussion_board.userProfiles.create(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      is_active: true,
    } satisfies IDiscussionBoardUserProfile.ICreate,
  });
  typia.assert(userProfile);

  // 2. 해당 유저를 멤버로 등록
  const member = await api.functional.admin.discussion_board.members.create(connection, {
    body: {
      discussion_board_user_profile_id: userProfile.id,
      joined_at: new Date().toISOString(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 3. 임의의 게시글 작성(테스트 멤버와 서로 관계 없는 fresh post)
  //    - 여기서는 일정한 topic_id와 신규 member(not the disliker)를 생성 후 게시글 생성
  const tempProfile = await api.functional.admin.discussion_board.userProfiles.create(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      is_active: true,
    } satisfies IDiscussionBoardUserProfile.ICreate,
  });
  typia.assert(tempProfile);
  const tempMember = await api.functional.admin.discussion_board.members.create(connection, {
    body: {
      discussion_board_user_profile_id: tempProfile.id,
      joined_at: new Date().toISOString(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(tempMember);
  const topicId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.my.discussion_board.posts.create(connection, {
    body: {
      discussion_board_topic_id: topicId,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. 테스트 대상 멤버(최초 생성 member)로 로그인 컨텍스트를 맞춘다는 과정 가정
  //     실제로 컨텍스트 전환은 api connection 객체 관리에 위임된다고 가정함(이 테스트 내에서는 해당 멤버가 호출 주체)

  // 5. 디스라이크 최초 생성
  const dislike = await api.functional.my.discussion_board.postLikes.create(connection, {
    body: {
      discussion_board_post_id: post.id,
      is_like: false,
    } satisfies IDiscussionBoardPostLike.ICreate,
  });
  typia.assert(dislike);

  // 6. 핵심 값 검증
  TestValidator.equals("post id matches")(dislike.discussion_board_post_id)(post.id);
  TestValidator.equals("author is the test member")(dislike.author_member_id)(member.id);
  TestValidator.equals("is_like is false")(dislike.is_like)(false);
}

