import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostLike";

/**
 * Verify that a member can create a dislike (is_like=false) for a post they
 * have not interacted with yet.
 *
 * This test ensures that a fresh member (user who is newly registered and
 * assigned as a member) can submit a `dislike` (is_like=false) entry for a post
 * for which they have not previously given a like/dislike. It simulates all
 * necessary preparations:
 *
 * 1. Create a new user profile using admin privileges.
 * 2. Assign this user profile as a new board member (capturing their member id).
 * 3. Create another separate user + member and use them to write a fresh post
 *    (which the main test member will interact with for the first time).
 * 4. (Assumed) Set connection context as if logged in as the test member. (In a
 *    real E2E, ensure proper member login context.)
 * 5. Have this test member submit a dislike (is_like=false) for the post.
 *
 * The test then:
 *
 * - Asserts a response entity is returned (type validation).
 * - Confirms that the returned like/dislike entry is associated with the correct
 *   post and author.
 * - Ensures is_like is stored as false (dislike), not true.
 * - Validates all returned PK/foreign keys match the expected ones.
 * - Guarantees this member/post combination was not previously used for
 *   like/dislike (first time interaction).
 */
export async function test_api_my_discussion_board_postLikes_test_create_post_dislike_success(
  connection: api.IConnection,
) {
  // 1. Create a new user profile (as the future author of the dislike)
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
