  // Assert returned record matches expectations
  TestValidator.equals("dislike: post id matches")(
    dislike.discussion_board_post_id,
  )(post.id);
  TestValidator.equals("dislike: author id matches")(dislike.author_member_id)(
    member.id,
  );
