import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IPageDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates the paginated, filtered search operation for discussion board
 * comments.
 *
 * This test ensures:
 *
 * 1. The ability to fetch comments with pagination and filtering by post ID and
 *    author ID.
 * 2. Only fields defined in the schema are returned.
 * 3. The results conform strictly to the applied filters and correct pagination
 *    metadata is present.
 *
 * Test Steps:
 *
 * 1. Create two posts as a prerequisite for associating comments.
 * 2. Add multiple comments (at least two per post, with possibly different
 *    authoring members, including a reply structure).
 * 3. Fetch comments filtered by a specific post ID, verifying all returned
 *    comments belong to that post.
 * 4. Fetch comments filtered by author_member_id, ensuring that all returned
 *    comments are authored by the target member.
 * 5. Test pagination by creating more comments than the default limit page size;
 *    then, request with a low limit and verify the result is paginated and
 *    matches the correct page and count properties.
 * 6. Ensure no unexpected or additional fields are returned on comment items in
 *    the results.
 *
 * Edge Cases:
 *
 * - Search for comments on a post with no comments (should yield empty
 *   result/data array).
 * - Search by nonexistent author_member_id.
 */
export async function test_api_discussion_board_test_search_comments_with_filter_and_pagination(
  connection: api.IConnection,
) {
  // Step 1: Create two posts
  const topicId = typia.random<string & tags.Format<"uuid">>();
  const post1 = await api.functional.my.discussion_board.posts.create(
    connection,
    {
      body: {
        discussion_board_topic_id: topicId,
        title: "First Post",
        body: "Post body 1",
      },
    },
  );
  typia.assert(post1);
  const post2 = await api.functional.my.discussion_board.posts.create(
    connection,
    {
      body: {
        discussion_board_topic_id: topicId,
        title: "Second Post",
        body: "Post body 2",
      },
    },
  );
  typia.assert(post2);

  // Step 2: Add comments
  const comment1 = await api.functional.my.discussion_board.comments.create(
    connection,
    {
      body: {
        discussion_board_post_id: post1.id,
        body: "First comment on post1",
      },
    },
  );
  typia.assert(comment1);
  const comment2 = await api.functional.my.discussion_board.comments.create(
    connection,
    {
      body: {
        discussion_board_post_id: post1.id,
        body: "Second comment on post1",
      },
    },
  );
  typia.assert(comment2);

  const comment3 = await api.functional.my.discussion_board.comments.create(
    connection,
    {
      body: {
        discussion_board_post_id: post2.id,
        body: "First comment on post2",
      },
    },
  );
  typia.assert(comment3);
  const comment4 = await api.functional.my.discussion_board.comments.create(
    connection,
    {
      body: {
        discussion_board_post_id: post2.id,
        body: "Second comment on post2",
      },
    },
  );
  typia.assert(comment4);

  // Add a reply to comment1 for nested comment test
  const reply1 = await api.functional.my.discussion_board.comments.create(
    connection,
    {
      body: {
        discussion_board_post_id: post1.id,
        parent_id: comment1.id,
        body: "Reply to comment1",
      },
    },
  );
  typia.assert(reply1);

  // Step 3: Filter by post ID (post1)
  const resultByPost = await api.functional.discussion_board.comments.index(
    connection,
    { body: { discussion_board_post_id: post1.id } },
  );
  typia.assert(resultByPost);
  for (const c of resultByPost.data) {
    TestValidator.equals("discussion_board_post_id matches filter")(
      c.discussion_board_post_id,
    )(post1.id);
  }

  // Step 4: Filter by author_member_id (use author_member_id from comment1)
  const authorId = comment1.author_member_id;
  const resultByAuthor = await api.functional.discussion_board.comments.index(
    connection,
    { body: { author_member_id: authorId } },
  );
  typia.assert(resultByAuthor);
  for (const c of resultByAuthor.data) {
    TestValidator.equals("author_member_id matches filter")(c.author_member_id)(
      authorId,
    );
  }

  // Step 5: Pagination check
  // Create additional comments on post2 to exceed typical page size (assuming default page size is 100, we test with limit=2)
  const commentsOnPost2 = [comment3, comment4];
  for (let i = 0; i < 5; ++i) {
    const newComment = await api.functional.my.discussion_board.comments.create(
      connection,
      {
        body: { discussion_board_post_id: post2.id, body: `Bulk comment ${i}` },
      },
    );
    typia.assert(newComment);
    commentsOnPost2.push(newComment);
  }
  // Request with limit=2 (should paginate)
  const pagedResult = await api.functional.discussion_board.comments.index(
    connection,
    { body: { discussion_board_post_id: post2.id, limit: 2, page: 1 } },
  );
  typia.assert(pagedResult);
  TestValidator.equals("page limit is 2")(pagedResult.pagination.limit)(2);
  TestValidator.equals("current page is 1")(pagedResult.pagination.current)(1);
  TestValidator.equals("paged result length")(pagedResult.data.length)(2);
  TestValidator.predicate("paged total is at least that many")(
    pagedResult.pagination.records >= commentsOnPost2.length,
  );

  // Step 6: Ensure only schema fields are present
  for (const c of pagedResult.data) {
    const keys = Object.keys(c);
    TestValidator.equals("schema keys only")(keys.sort())(
      [
        "id",
        "discussion_board_post_id",
        "author_member_id",
        "parent_id",
        "body",
        "is_deleted",
        "created_at",
        "updated_at",
      ].sort(),
    );
  }
  // Edge case: Search for post with no comments
  const postNoComment = await api.functional.my.discussion_board.posts.create(
    connection,
    {
      body: {
        discussion_board_topic_id: topicId,
        title: "No comment post",
        body: "body",
      },
    },
  );
  typia.assert(postNoComment);
  const emptyResult = await api.functional.discussion_board.comments.index(
    connection,
    { body: { discussion_board_post_id: postNoComment.id } },
  );
  typia.assert(emptyResult);
  TestValidator.equals("no comments")(emptyResult.data.length)(0);

  // Edge case: Nonexistent author_member_id
  const fakeAuthorId = typia.random<string & tags.Format<"uuid">>();
  const noneResult = await api.functional.discussion_board.comments.index(
    connection,
    { body: { author_member_id: fakeAuthorId } },
  );
  typia.assert(noneResult);
  TestValidator.equals("none for fake author")(noneResult.data.length)(0);
}

