 * 2. user1 logs in and creates a post in a given topic.
 * 3. user1 creates a comment on that post.
 * 4. user2 logs in and tries to delete user1's comment using its ID.
 * 5. The delete operation must fail with an appropriate authorization error (e.g., 403 forbidden or error thrown by API layer).
 */
export async function test_api_discussion_board_test_delete_comment_by_non_author_fails(
  connection: api.IConnection,
) {
  // 1. Create two user profiles (user1 and user2), then set both as board members
  const now: string = new Date().toISOString();
  // Create user1 profile
  const user1Profile = await api.functional.admin.discussion_board.userProfiles.create(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      registered_at: now,
      is_active: true,
    },
  });
  typia.assert(user1Profile);

  // Create user2 profile
  const user2Profile = await api.functional.admin.discussion_board.userProfiles.create(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      registered_at: now,
      is_active: true,
    },
  });
  typia.assert(user2Profile);

  // Assign user1 as member
  const user1Member = await api.functional.admin.discussion_board.members.create(connection, {
    body: {
      discussion_board_user_profile_id: user1Profile.id,
      joined_at: now,
    },
  });
  typia.assert(user1Member);

  // Assign user2 as member
  const user2Member = await api.functional.admin.discussion_board.members.create(connection, {
    body: {
      discussion_board_user_profile_id: user2Profile.id,
      joined_at: now,
    },
  });
  typia.assert(user2Member);

  // 2. Emulate user1 session: create a post, then a comment
  // NOTE: This assumes the connection context can be switched/emulated (see API infra)

  // Create a post as user1
  // Simulate session as user1 for all 'my' requests:
  connection.headers = { ...connection.headers, "x-autobe-user-profile-id": user1Profile.id };
  const post = await api.functional.my.discussion_board.posts.create(connection, {
    body: {
      discussion_board_topic_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // Create a comment as user1
  const comment = await api.functional.my.discussion_board.comments.create(connection, {
    body: {
      discussion_board_post_id: post.id,
      body: RandomGenerator.paragraph()(),
      // parent_id omitted for root comment
    },
  });
  typia.assert(comment);

  // 3. Emulate user2 session: try to delete user1's comment (should fail)
  connection.headers = { ...connection.headers, "x-autobe-user-profile-id": user2Profile.id };
  await TestValidator.error("Non-author cannot delete comment")(
