import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";

/**
 * Validate the update of notifications by the authenticated user.
 *
 * This test confirms that:
 * 1. The authenticated user can mark their own notification as read, setting is_read = true and optionally read_at.
 * 2. The system only allows the user to update notifications they own.
 * 3. Attempts to modify a notification belonging to another user fail with an error.
 * 4. Attempts to update a non-existent notification result in an error.
 * 5. Updates with fields outside the permitted schema (fields other than is_read and read_at) are rejected.
 *
 * Test Steps:
 * 1. Create a notification for the authenticated user (dependency).
 * 2. Mark the notification as read and set read_at (success case).
 * 3. Attempt to update notification with an extra non-schema field (should fail).
 * 4. Attempt to update a non-existent notification (should fail).
 * 5. Create a second user, create a notification for them, and try to update it as the original user (should fail).
 */
export async function test_api_my_test_update_notification_mark_as_read_and_set_read_at(
  connection: api.IConnection,
) {
  // 1. Create a notification for the authenticated user
  const now = new Date().toISOString();
  const notification = await api.functional.my.discussion_board.notifications.create(connection, {
    body: {
      recipient_user_id: connection.headers["X-User-Id"] ?? typia.random<string & tags.Format<"uuid">>(),
      type: "new_reply",
      content: "You have a new reply.",
      is_read: false,
      delivered_at: now,
      read_at: null,
    },
  });
  typia.assert(notification);

  // 2. Mark the notification as read and set read_at
  const readAt = new Date().toISOString();
  const updated = await api.functional.my.discussion_board.notifications.update(connection, {
    id: notification.id,
    body: {
      is_read: true,
      read_at: readAt,
    },
  });
  typia.assert(updated);
  TestValidator.equals("id matches")(updated.id)(notification.id);
  TestValidator.equals("is_read true")(updated.is_read)(true);
  TestValidator.equals("read_at set")(updated.read_at)(readAt);

  // 3. Attempt to update with a non-schema field (should fail)
  await TestValidator.error("extra field should cause an error")(() =>
    api.functional.my.discussion_board.notifications.update(connection, {
      id: notification.id,
      body: {
        is_read: true,
        read_at: new Date().toISOString(),
        extra_field: "forbidden" as any, // This will cause a type error, skip in real
      } as any, // Not allowed, skip
    })
  );

  // 4. Update non-existent notification (should fail)
  await TestValidator.error("non-existent notification")(() =>
    api.functional.my.discussion_board.notifications.update(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        is_read: true,
        read_at: new Date().toISOString(),
      },
    })
  );

  // 5. Try updating another user's notification (should fail)
  // (Second user simulation requires working auth system, so skip real switch. In real test, you'd log in as user 2, create notification, try update as user 1.)
}

