import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IPageDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 테스트 목적: 게시판 카테고리 목록 조회 API (pagination, 검색, 정렬, 활성/비활성 필터) 테스트
 *
 * 시나리오:
 * 1. 카테고리 엔티티가 존재하지 않을 때 조회 요청을 하여 빈 배열이 정상적으로 반환되는지 확인
 * 2. 기본 조회: page/limit이 기본값일 때 전체 카테고리가 올바르게 조회되는지 확인
 * 3. 검색 필터(search) - name/description 일부가 포함된 결과만 반환되는지 확인
 * 4. sort_field, sort_order 테스트: sort_field를 name/sort_order로, sort_order를 asc/desc로 각각 지정했을 때 정렬 결과를 검증
 * 5. is_active=false (비활성 카테고리만 존재할 때) 필터 파라미터가 없어도 is_active=false인 항목만 나오는 상황을 검증
 * 6. 반환 데이터 내 필드가 실제 스키마와 정확히 일치하고, 불필요한 정보가 포함되지 않음을 검증
 *
 * 각 검증은 typia.assert/result 객체 타입 및 TestValidator를 활용해 진행한다. 모든 파라미터 조합(몇가지 representative case)으로 최소 1회씩 검증할 것.
 */
export async function test_api_discussion_board_test_list_categories_with_pagination_and_search(connection: api.IConnection) {
  // 1. 카테고리가 없는 상태에서 조회 (빈 결과 검증)
  const emptyResult = await api.functional.discussion_board.categories.index(connection, {
    body: {},
  });
  typia.assert(emptyResult);
  TestValidator.equals("empty data array")(emptyResult.data.length)(0);

  // 2. 기본 페이징 조회 (파라미터 없이 전체)
  const baseResult = await api.functional.discussion_board.categories.index(connection, {
    body: {},
  });
  typia.assert(baseResult);
  TestValidator.predicate("valid pagination")(baseResult.pagination.current >= 1 && baseResult.pagination.pages >= 1);
  TestValidator.predicate("records matches data length")(baseResult.pagination.records >= baseResult.data.length);
  // 데이터의 실제 필드만 존재하는지 확인
  baseResult.data.forEach((cat) => {
    typia.assert(cat);
    // 필드의 유효성 추가 검증 등은 필요시 진행
  });

  // 3. 검색 필터 (name에 일부 문자열 포함)
  if (baseResult.data.length > 0) {
    const searchTerm = baseResult.data[0].name.substring(0, 2);
    const searchResult = await api.functional.discussion_board.categories.index(connection, {
      body: { search: searchTerm },
    });
    typia.assert(searchResult);
    searchResult.data.forEach((cat) => {
      TestValidator.predicate("검색 결과에 name이 포함됨")(cat.name.includes(searchTerm) || (cat.description && cat.description.includes(searchTerm)));
    });
  }

