import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopic";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E Test: Search and filter posts by keyword in body or title.
 *
 * Business context: Forums require the ability to search posts for moderation, discoverability, or audit. To validate post search, this test will:
 * - Create multiple diverse posts with distinctive keywords in their bodies and/or titles.
 * - Use the post-listing API with a search keyword filter (body_keyword).
 * - Assert that only posts containing the keyword (in body or title) are returned and others are excluded.
 *
 * Steps:
 * 1. Create several user profiles (with is_active true, different emails/names) for data diversity.
 * 2. Assign each user profile as a member (joined_at now).
 * 3. Create at least one active category (with a unique code);
 * 4. For each member, create a topic in the category with a unique title and description.
 * 5. For each member/topic, create multiple posts:
 *    - At least one post per member with a test keyword (e.g., 'e2e-keyword-search-XYZ') in the title or body
 *    - At least one post per member without the keyword
 * 6. Call the /discussion_board/posts index API with body_keyword set to the keyword to filter.
 * 7. Assert that only the posts containing the keyword are returned, and all posts without it are excluded.
 * 8. Validate that pagination and result counts align with the injected dataset.
 */
export async function test_api_discussion_board_test_list_posts_with_keyword_search_in_body(
  connection: api.IConnection,
) {
  // 1. Create user profiles
  const userProfiles: IDiscussionBoardUserProfile[] = await ArrayUtil.asyncRepeat(3)(async () => {
    const input = {
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      is_active: true
    } satisfies IDiscussionBoardUserProfile.ICreate;
    const result = await api.functional.admin.discussion_board.userProfiles.create(connection, { body: input });
    typia.assert(result);
    return result;
  });

  // 2. Assign user profiles as members
  const members: IDiscussionBoardMember[] = await ArrayUtil.asyncMap(userProfiles)(async (user) => {
    const input = {
      discussion_board_user_profile_id: user.id,
      joined_at: new Date().toISOString(),
    } satisfies IDiscussionBoardMember.ICreate;
    const result = await api.functional.admin.discussion_board.members.create(connection, { body: input });
    typia.assert(result);
    return result;
  });

  // 3. Create category
  const categoryInput = {
    code: `cat-${RandomGenerator.alphaNumeric(5)}`,
    name: RandomGenerator.name(),
    sort_order: 1,
    is_active: true
  } satisfies IDiscussionBoardCategory.ICreate;
  const category = await api.functional.admin.discussion_board.categories.create(connection, { body: categoryInput });
  typia.assert(category);

  // 4. Create topics (one per member)
  const topics: IDiscussionBoardTopic[] = await ArrayUtil.asyncMap(members)(async (member) => {
    const input = {
      discussion_board_category_id: category.id,
      title: RandomGenerator.paragraph()(),
      description: RandomGenerator.content()()(),
      status: "open"
    } satisfies IDiscussionBoardTopic.ICreate;
    const topic = await api.functional.my.discussion_board.topics.create(connection, { body: input });
    typia.assert(topic);
    return topic;
  });

  // 5. Create posts with and without keyword
  const searchKeyword = "e2e-keyword-search-7749";
  const postsWithKeyword: IDiscussionBoardPost[] = [];
  const postsWithoutKeyword: IDiscussionBoardPost[] = [];
  for (let i = 0; i < members.length; ++i) {
    // At least one post with the keyword (in title)
    {
      const input = {
        discussion_board_topic_id: topics[i].id,
        title: `${searchKeyword} Title Test`,
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate;
      const post = await api.functional.my.discussion_board.posts.create(connection, { body: input });
      typia.assert(post);
      postsWithKeyword.push(post);
    }
    // At least one post without the keyword
    {
      const input = {
        discussion_board_topic_id: topics[i].id,
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate;
      const post = await api.functional.my.discussion_board.posts.create(connection, { body: input });
      typia.assert(post);
      postsWithoutKeyword.push(post);
    }
    // At least one post with the keyword (in body)
    {
      const input = {
        discussion_board_topic_id: topics[i].id,
        title: RandomGenerator.paragraph()(),
        body: `${RandomGenerator.content()()()} ${searchKeyword}`,
      } satisfies IDiscussionBoardPost.ICreate;
      const post = await api.functional.my.discussion_board.posts.create(connection, { body: input });
      typia.assert(post);
      postsWithKeyword.push(post);
    }
  }

  // 6. Call API with keyword filter
  const result = await api.functional.discussion_board.posts.index(connection, {
    body: { body_keyword: searchKeyword, limit: 100 } satisfies IDiscussionBoardPost.IRequest,
  });
  typia.assert(result);

  // 7. Assert only keyword-containing posts are returned
  const resultIds = result.data.map((post) => post.id);
  for (const post of postsWithKeyword) {
    TestValidator.predicate(`post with keyword returned - ${post.id}`)(resultIds.includes(post.id));
  }
  for (const post of postsWithoutKeyword) {
    TestValidator.predicate(`post without keyword excluded - ${post.id}`)(!resultIds.includes(post.id));
  }

  // 8. Pagination/result count check
  TestValidator.equals("number of search results")(
    result.data.length
  )(
    postsWithKeyword.length
  );
}

