import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardGuest";
import type { IPageIDiscussionBoardGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardGuest";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate paginated and filtered retrieval of guest session records for the discussion board.
 *
 * This test covers default listing (no filters), session_id filtering, created_at date range queries, pagination with varying limits, boundary conditions such as empty result sets, and handling of large datasets. It also ensures that deleted sessions do not appear in the list.
 * No authentication is required unless system policy changes, in which case correct enforcement is validated.
 *
 * Steps:
 * 1. Create a set of diverse guest sessions (with distinct session_id and created_at values across a meaningful range of dates).
 * 2. Fetch all sessions with no filters and validate all created records are present.
 * 3. Apply session_id filter and verify only matching session(s) are returned.
 * 4. Apply created_at_start and created_at_end to filter by creation date; verify expected subset of sessions is returned.
 * 5. Test pagination by setting different page and limit values, confirm result slicing and pagination metadata correctness.
 * 6. Delete some guest sessions and verify they do not appear in future listings (simulate empty and near-empty result sets).
 * 7. Attempt queries with invalid filter values (e.g., non-existent session_id, page out of range), confirm response is empty and error-free.
 * 8. For large N, verify performance and accuracy, but keep generated N reasonable for test environment.
 */
export async function test_api_discussion_board_guests_index_with_pagination_and_filters(connection: api.IConnection) {
  // Step 1: Create multiple guest sessions
  const baseDate = new Date();
  const sessions: IDiscussionBoardGuest[] = [];
  for (let i = 0; i < 10; ++i) {
    const session: IDiscussionBoardGuest = await api.functional.my.discussion_board.guests.create(connection, {
      body: {
        session_id: `session_${i}_${RandomGenerator.alphaNumeric(6)}`,
        created_at: new Date(baseDate.getTime() - i * 86400000).toISOString(),
      } satisfies IDiscussionBoardGuest.ICreate,
    });
    typia.assert(session);
    sessions.push(session);
  }

  // Step 2: Default listing (no filters)
  const allResult = await api.functional.discussion_board.guests.index(connection, {
    body: {},
  });
  typia.assert(allResult);
  sessions.forEach(s => {
    TestValidator.predicate(`default listing includes session: ${s.session_id}`)(
      allResult.data.some(row => row.id === s.id),
    );
  });

  // Step 3: Filter by session_id
  for (const testSession of [sessions[3], sessions[6]]) {
    const filterBySid = await api.functional.discussion_board.guests.index(connection, {
      body: { session_id: testSession.session_id },
    });
    typia.assert(filterBySid);
    TestValidator.equals('single session_id filter result length')(filterBySid.data.length)(1);
    TestValidator.equals('returned session_id matches')(filterBySid.data[0].session_id)(testSession.session_id);
  }

  // Step 4: Filter by created_at range
  const createdAtStart = sessions[7].created_at;
  const createdAtEnd = sessions[4].created_at;
  const filterByDate = await api.functional.discussion_board.guests.index(connection, {
    body: {
      created_at_start: createdAtStart,
      created_at_end: createdAtEnd,
    },
  });
  typia.assert(filterByDate);
  // Should contain sessions[4] to sessions[7] (inclusive)
  const expectedIds = [4, 5, 6, 7].map(idx => sessions[idx].id);
  TestValidator.equals('created_at range result length')(filterByDate.data.length)(expectedIds.length);
  expectedIds.forEach(id => {
    TestValidator.predicate('created_at range contains expected session')(
      filterByDate.data.some(row => row.id === id),
    );
  });

  // Step 5: Pagination - page/limit
  const paginated = await api.functional.discussion_board.guests.index(connection, {
    body: { page: 2, limit: 3 },
  });
  typia.assert(paginated);
  TestValidator.equals('pagination page/limit')(paginated.pagination.current)(2);
  TestValidator.equals('pagination limit')(paginated.pagination.limit)(3);
  TestValidator.equals('pagination data length')(paginated.data.length)(3);

  // Step 6: Delete a session and ensure it does not appear in the list
  const removedSession = sessions[0];
  await api.functional.my.discussion_board.guests.erase(connection, {
    id: removedSession.id,
  });
  const afterDelete = await api.functional.discussion_board.guests.index(connection, { body: {} });
  typia.assert(afterDelete);
  TestValidator.predicate('deleted session not in results')(
    afterDelete.data.every(row => row.id !== removedSession.id),
  );

  // Step 7: Query with non-existent session_id
  const emptyBySessionId = await api.functional.discussion_board.guests.index(connection, {
    body: { session_id: 'non_existent_sid' },
  });
  typia.assert(emptyBySessionId);
  TestValidator.equals('empty result for non-existent session_id')(emptyBySessionId.data.length)(0);

  // Step 8: Query page out of range
  const outOfRangePage = await api.functional.discussion_board.guests.index(connection, {
    body: { page: 1000 },
  });
  typia.assert(outOfRangePage);
  TestValidator.equals('empty result for out-of-range page')(outOfRangePage.data.length)(0);
}

