import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopic";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostSnapshot";
import type { IPageIDiscussionBoardPostSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 테스트 목적: 게시글의 편집 이력(스냅샷) 목록을 게시글 ID로 필터링하여 페이징 단위로 올바르게 조회할 수 있는지 검증합니다.
 *
 * 시나리오
 * 1. (관리자) 게시글을 편집하고 이력을 기록할 사용자를 생성합니다.
 * 2. (관리자) 해당 유저를 멤버로 할당합니다.
 * 3. (관리자) 게시글이 속할 카테고리를 생성합니다.
 * 4. (멤버) 위 카테고리 내 토픽을 생성합니다.
 * 5. (멤버) 해당 토픽에 원본 게시글을 작성합니다.
 * 6. (멤버) 게시글을 여러 번 수정(콘텐츠, 제목)하여 복수 개의 스냅샷이 쌓이게 만듭니다.
 * 7. (멤버) 게시글을 소프트 삭제(is_deleted=true)하여 추가 스냅샷이 기록되도록 합니다.
 * 8. (어느 사용자든 가능) /discussion_board/postSnapshots 엔드포인트로 post_id별 페이징 목록을 조회합니다.
 * 9. (검증) 반환된 스냅샷 목록이 최신순 역순(chronological ordering)이며 각 스냅샷이 실제 편집 및 삭제된 내역과 일치함을 검증합니다.
 * 10. (검증) 페이지네이션 정보(페이지 수/레코드 수/limit 등)가 정상 동작함을 확인합니다.
 */
export async function test_api_discussion_board_test_list_post_snapshots_by_post_id_paginated(connection: api.IConnection) {
  // 1. (관리자) 테스트 유저 프로필 생성
  const profile = await api.functional.admin.discussion_board.userProfiles.create(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      is_active: true,
      registered_at: new Date().toISOString(),
    },
  });
  typia.assert(profile);

  // 2. (관리자) 해당 프로필을 멤버로 등록
  const member = await api.functional.admin.discussion_board.members.create(connection, {
    body: {
      discussion_board_user_profile_id: profile.id,
      joined_at: new Date().toISOString(),
    },
  });
  typia.assert(member);

  // 3. (관리자) 카테고리 생성
  const category = await api.functional.admin.discussion_board.categories.create(connection, {
    body: {
      code: RandomGenerator.alphabets(8),
      name: RandomGenerator.name(),
      description: RandomGenerator.paragraph()(),
      sort_order: 1,
      is_active: true,
    },
  });
  typia.assert(category);

  // 4. (멤버) 토픽 생성 (본 구현 환경에서는 권한 문제없이 API로 바로 가능하다고 가정)
  const topic = await api.functional.my.discussion_board.topics.create(connection, {
    body: {
      discussion_board_category_id: category.id,
      title: RandomGenerator.paragraph()(),
      description: RandomGenerator.content()()(),
      status: "open",
    },
  });
  typia.assert(topic);

  // 5. (멤버) 게시글 생성
  const originalTitle = RandomGenerator.paragraph()();
  const originalBody = RandomGenerator.content()()();
  const post = await api.functional.my.discussion_board.posts.create(connection, {
    body: {
      discussion_board_topic_id: topic.id,
      title: originalTitle,
      body: originalBody,
    },
  });
  typia.assert(post);

  // 6. (멤버) 게시글 편집 여러 번
  const update1 = await api.functional.my.discussion_board.posts.update(connection, {
    id: post.id,
    body: { title: originalTitle + " - 1차수정", body: originalBody + "\n수정1" },
  });
  typia.assert(update1);
  const update2 = await api.functional.my.discussion_board.posts.update(connection, {
    id: post.id,
    body: { title: originalTitle + " - 2차수정", body: originalBody + "\n수정1\n수정2" },
  });
  typia.assert(update2);

  // 7. (멤버) 소프트 삭제 (is_deleted=true)
  const erased = await api.functional.my.discussion_board.posts.erase(connection, {
    id: post.id,
  });
  typia.assert(erased);

  // 8. (어느 유저든) post_id별 스냅샷 페이징 조회 (최대 2개씩 페이징)
  const pageSize = 2;
  const page1 = await api.functional.discussion_board.postSnapshots.index(connection, {
    body: {
      discussion_board_post_id: post.id,
      page: 1,
      limit: pageSize,
    },
  });
  typia.assert(page1);

  // 9. (검증) 정렬, 갯수, 실제 스냅샷 내용 확인
  TestValidator.equals("page 1 count")(page1.data.length)(pageSize);
  TestValidator.equals("ordering - 최신순")(true)(
    page1.data[0].created_at > page1.data[1].created_at
  );
  TestValidator.equals("pagination meta")(page1.pagination.limit)(pageSize);
  TestValidator.equals("pagination meta current")(page1.pagination.current)(1);

  // 10. (검증) page 2도 조회 (잔여 스냅샷)
  const page2 = await api.functional.discussion_board.postSnapshots.index(connection, {
    body: {
      discussion_board_post_id: post.id,
      page: 2,
      limit: pageSize,
    },
  });
  typia.assert(page2);
  TestValidator.equals("page 2 current")(page2.pagination.current)(2);
  // 데이터가 혹시 남아있을 경우 갯수 체크 (총 4개 생성되어 page 2는 길이 2 또는 잔여)
  TestValidator.equals("page2 count/잔여")(page2.data.length)(Math.max(0, 4 - pageSize));
}

