import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 게시글 편집 이력(스냅샷) 조회 및 페이징 검증 시나리오
 *
 * 본 테스트는 다음을 모두 검증합니다:
 *
 * - 게시글 ID별로 edit 스냅샷 목록이 정상 생성/조회되는가
 * - 여러 차례 수정, soft-delete를 거친 이력 전체가 페이징에 맞게 올바르게 조회되는가
 * - 반환 데이터는 타입 안정성이 보장되고, 정렬 순서(최신순)의 일관성이 유지되는가
 * - 페이지네이션 meta(현재 페이지/limit/전체 수)가 기대대로 동작하는가
 *
 * 절차:
 *
 * 1. 관리자가 유저 프로필을 생성
 * 2. 해당 유저를 게시판 멤버로 등록
 * 3. 카테고리를 생성
 * 4. 멤버가 토픽 생성
 * 5. 멤버가 게시글 작성
 * 6. 멤버가 동일 게시글 2회 연속 수정
 * 7. 멤버가 게시글을 soft delete (is_deleted)
 * 8. Post_id로 스냅샷 목록을 페이지 단위로 2페이지 이상 조회
 * 9. 각 페이지 결과의 갯수, 정렬, pagination 메타, 데이터 적합성 일괄 검증
 */
export async function test_api_discussion_board_test_list_post_snapshots_by_post_id_paginated(
  connection: api.IConnection,
) {
  // 1. 관리자 - 테스트 유저 생성
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
          registered_at: new Date().toISOString(),
        },
      },
    );
  typia.assert(userProfile);

  // 2. 관리자 - 멤버로 등록
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userProfile.id,
        joined_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(member);

  // 3. 관리자 - 카테고리 등록
  const category =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: RandomGenerator.alphabets(8),
        name: RandomGenerator.name(),
        description: RandomGenerator.paragraph()(),
        sort_order: 1,
        is_active: true,
      },
    });
  typia.assert(category);

  // 4. 멤버 - 토픽 신규 생성
  const topic = await api.functional.my.discussion_board.topics.create(
    connection,
    {
      body: {
        discussion_board_category_id: category.id,
        title: RandomGenerator.paragraph()(),
        description: RandomGenerator.content()()(),
        status: "open",
      },
    },
  );
  typia.assert(topic);

  // 5. 멤버 - 게시글 등록
  const originTitle = RandomGenerator.paragraph()();
  const originBody = RandomGenerator.content()()();
  const post = await api.functional.my.discussion_board.posts.create(
    connection,
    {
      body: {
        discussion_board_topic_id: topic.id,
        title: originTitle,
        body: originBody,
      },
    },
  );
  typia.assert(post);

  // 6. 멤버 - 게시글 수정 2회(스냅샷 증가)
  const update1 = await api.functional.my.discussion_board.posts.update(
    connection,
    {
      id: post.id,
      body: { title: originTitle + "-1차수정", body: originBody + "\n수정1" },
    },
  );
  typia.assert(update1);

  const update2 = await api.functional.my.discussion_board.posts.update(
    connection,
    {
      id: post.id,
      body: {
        title: originTitle + "-2차수정",
        body: originBody + "\n수정1\n수정2",
      },
    },
  );
  typia.assert(update2);

  // 7. 멤버 - soft-delete (is_deleted)
  const erased = await api.functional.my.discussion_board.posts.erase(
    connection,
    {
      id: post.id,
    },
  );
  typia.assert(erased);

  // 8. post_id별 스냅샷 2개씩 페이징 목록 조회
  const pageSize = 2;
  const page1 = await api.functional.discussion_board.postSnapshots.index(
    connection,
    {
      body: {
        discussion_board_post_id: post.id,
        page: 1,
        limit: pageSize,
      },
    },
  );
  typia.assert(page1);
  TestValidator.equals("page1 데이터 갯수")(page1.data.length)(pageSize);
  TestValidator.equals("page1 최신순 정렬")(true)(
    page1.data[0].created_at > page1.data[1].created_at,
  );
  TestValidator.equals("pagination.limit")(page1.pagination.limit)(pageSize);
  TestValidator.equals("pagination.current")(page1.pagination.current)(1);

  // 9. page2(잔여 또는 빈 값)도 조회 및 meta 검증
  const page2 = await api.functional.discussion_board.postSnapshots.index(
    connection,
    {
      body: {
        discussion_board_post_id: post.id,
        page: 2,
        limit: pageSize,
      },
    },
  );
  typia.assert(page2);
  TestValidator.equals("page2.current")(page2.pagination.current)(2);
  TestValidator.equals("page2 데이터 갯수")(page2.data.length)(
    Math.max(0, 4 - pageSize),
  );
}

