import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopic";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for listing discussion board posts using topic and author filters.
 *
 * This test sets up the following data dependencies and workflow:
 * 1. Several user profiles are created (admin endpoint),
 * 2. Each profile is promoted to member status (admin endpoint),
 * 3. Several categories are created (admin endpoint),
 * 4. Each member creates a topic (member endpoint) in a chosen category,
 * 5. Several posts are created under various topics & by various authors,
 * 6. Test: For a given topic and author, list posts using the PATCH /discussion_board/posts endpoint with the appropriate filters.
 *    Validate that only posts matching the topic_id and author_member_id are included.
 *
 * Business context: This ensures that post listing/filters work for both topic-based and user-based queries (e.g., for author pages or topic detail views)
 *
 * Steps:
 * 1. Create 3 user profiles.
 * 2. Make all users members.
 * 3. Create 2 categories (to ensure multi-category).
 * 4. Have each member create a topic (total 3 topics).
 * 5. Each member creates posts under all topics (to guarantee coverage of author/topic pairs).
 * 6. Pick one topic/member pair for targeted filtering, call the list API, and verify all returned posts have both the selected topic and author.
 */
export async function test_api_discussion_board_test_list_posts_with_filters_on_topic_id_and_author(
  connection: api.IConnection
) {
  // 1. Create 3 user profiles
  const profiles = await Promise.all([
    api.functional.admin.discussion_board.userProfiles.create(connection, { body: {
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      is_active: true,
    }}),
    api.functional.admin.discussion_board.userProfiles.create(connection, { body: {
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      is_active: true,
    }}),
    api.functional.admin.discussion_board.userProfiles.create(connection, { body: {
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      is_active: true,
    }})
  ]);
  profiles.forEach(typia.assert);

  // 2. Make all users members
  const now = new Date().toISOString();
  const members = await Promise.all(
    profiles.map(profile => api.functional.admin.discussion_board.members.create(connection, {
      body: {
        discussion_board_user_profile_id: profile.id,
        joined_at: now,
      }
    }))
  );
  members.forEach(typia.assert);

  // 3. Create 2 categories
  const categories = await Promise.all([
    api.functional.admin.discussion_board.categories.create(connection, { body: {
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(2),
      description: RandomGenerator.paragraph()(),
      sort_order: 1,
      is_active: true,
    }}),
    api.functional.admin.discussion_board.categories.create(connection, { body: {
      code: RandomGenerator.alphaNumeric(8),
      name: RandomGenerator.paragraph()(2),
      description: RandomGenerator.paragraph()(),
      sort_order: 2,
      is_active: true,
    }})
  ]);
  categories.forEach(typia.assert);

  // 4. Each member creates a topic in a category
  const topics = await Promise.all(
    members.map((member, idx) =>
      api.functional.my.discussion_board.topics.create(connection, {
        body: {
          discussion_board_category_id: categories[idx % categories.length].id,
          title: RandomGenerator.paragraph()(),
          description: RandomGenerator.content()()(),
          status: "open",
        }
      })
    )
  );
  topics.forEach(typia.assert);

  // 5. Each member creates posts in all topics (total 3 members x 3 topics)
  const posts: IDiscussionBoardPost[] = [];
  for (const member of members) {
    for (const topic of topics) {
      // Switch to the member if required - omitted for simplicity (auth context simulated)
      const post = await api.functional.my.discussion_board.posts.create(connection, {
        body: {
          discussion_board_topic_id: topic.id,
          title: RandomGenerator.paragraph()(),
          body: RandomGenerator.content()()(),
        }
      });
      typia.assert(post);
      posts.push(post);
    }
  }

  // 6. Pick one topic and author for filter test
  const targetTopic = topics[0];
  const targetAuthor = members[1];

  // Create extra posts with the target topic/author for robust filtering
  const extraPosts: IDiscussionBoardPost[] = [];
  for (let i = 0; i < 2; ++i) {
    // Should be under the correct topic and by target author
    const post = await api.functional.my.discussion_board.posts.create(connection, {
      body: {
        discussion_board_topic_id: targetTopic.id,
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      }
    });
    typia.assert(post);
    extraPosts.push(post);
  }
  // All posts created by targetAuthor under targetTopic:
  const expectedPostIDs = posts.filter(p => p.discussion_board_topic_id === targetTopic.id && p.author_member_id === targetAuthor.id).map(p => p.id).concat(extraPosts.map(p => p.id));

  // 7. Filter posts by target topic and author
  const result = await api.functional.discussion_board.posts.index(connection, {
    body: {
      discussion_board_topic_id: targetTopic.id,
      author_member_id: targetAuthor.id,
      page: 1,
      limit: 100,
    }
  });
  typia.assert(result);

  // 8. Confirm only matching posts are returned
  for(const post of result.data) {
    TestValidator.equals("topic filtered")(post.discussion_board_topic_id)(targetTopic.id);
    TestValidator.equals("author filtered")(post.author_member_id)(targetAuthor.id);
    // Must be among expected post IDs
    TestValidator.predicate("id in expected posts")(expectedPostIDs.includes(post.id));
  }
}

