 */
export async function test_api_discussion_board_test_get_topic_snapshot_by_valid_id(
  connection: api.IConnection,
) {
  // 1. Admin creates a user profile (member/editor).
  const userProfile = await api.functional.admin.discussion_board.userProfiles.create(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      is_active: true,
      registered_at: new Date().toISOString(),
    },
  });
  typia.assert(userProfile);

  // 2. Admin assigns the user profile as a board member.
  const member = await api.functional.admin.discussion_board.members.create(connection, {
    body: {
      discussion_board_user_profile_id: userProfile.id,
      joined_at: new Date().toISOString(),
    },
  });
  typia.assert(member);

  // 3. Member creates a topic.
  // For this test, use a dummy category UUID as required by the API contract. In live tests, this would be looked up.
  const discussion_board_category_id = typia.random<string & tags.Format<"uuid">>();
  const initialTitle = `Initial Title ${RandomGenerator.alphabets(6)}`;
  const initialDescription = `Initial Description ${RandomGenerator.paragraph()()}`;
  const status = "open";

  const topic = await api.functional.my.discussion_board.topics.create(connection, {
    body: {
      discussion_board_category_id,
      title: initialTitle,
      description: initialDescription,
      status,
      pinned_at: null,
      closed_at: null,
    },
  });
  typia.assert(topic);

  // 4. Member makes multiple edits to the topic (at least two edits for snapshot depth).
  const edit1Title = `Edit1 Title ${RandomGenerator.alphabets(6)}`;
  const edit1Description = `Edit1 Desc ${RandomGenerator.paragraph()()}`;
  const updated1 = await api.functional.my.discussion_board.topics.update(connection, {
    id: topic.id,
    body: {
      title: edit1Title,
      description: edit1Description,
      status,
    },
  });
  typia.assert(updated1);

  const edit2Title = `Edit2 Title ${RandomGenerator.alphabets(6)}`;
  const edit2Description = `Edit2 Desc ${RandomGenerator.paragraph()()}`;
  const updated2 = await api.functional.my.discussion_board.topics.update(connection, {
    id: topic.id,
    body: {
      title: edit2Title,
      description: edit2Description,
      status,
    },
  });
  typia.assert(updated2);

  // 5. Retrieve the snapshot list for the topic
  const snapshotListPage = await api.functional.discussion_board.topicSnapshots.index(connection, {
    body: {
      discussion_board_topic_id: topic.id,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(snapshotListPage);
  if (snapshotListPage.data.length === 0)
    throw new Error("No snapshots found for created topic");
  const pickedSnapshot = RandomGenerator.pick(snapshotListPage.data);

  // 6. Retrieve the selected snapshot by id
  const snapshot = await api.functional.discussion_board.topicSnapshots.at(connection, {
    id: pickedSnapshot.id,
  });
  typia.assert(snapshot);

  // 7. Assert snapshot details are coherent and match the topic and member info
  TestValidator.equals("snapshot discussion_board_topic_id matches topic")(
    snapshot.discussion_board_topic_id
  )(topic.id);
  TestValidator.equals("snapshot edited_by_member_id matches editor/member")(
    snapshot.edited_by_member_id
  )(member.id);
  TestValidator.predicate("snapshot title/description exist")(
    typeof snapshot.title === "string" && !!snapshot.title &&
    typeof snapshot.description === "string" && !!snapshot.description
  );
}

