import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostAttachment";

/**
 * 토론 게시판 글 첨부파일의 소프트 삭제(논리 삭제) 기능을 검증합니다.
 *
 * 1. 신규 사용자 프로필을 관리자가 생성함 (이메일/이름/활성 여부 지정)
 * 2. 해당 프로필을 게시판 멤버로 등록 (즉시 활성화)
 * 3. 멤버 계정으로 로그인 상태를 유지하고(실제 API에서는 세션 전환 필요, E2E에서는 연결 유지)
 * 4. 임의의 토픽 UUID에 속하는 게시글을 해당 멤버가 등록 (주제ID는 랜덤 UUID, body와 제목 랜덤)
 * 5. 글 첨부파일을 위 게시글에 등록 (업로더는 인증 정보→멤버ID로 자동 연결됨)
 * 6. 첨부파일 삭제 API를 호출하여, is_deleted가 true로 변경됐음을 확인합니다.
 * 7. 삭제 직후에도 첨부파일 정보(파일명/경로 등)는 남아 있음(하드삭제 아님)을 추가로 검증합니다.
 *
 * 이를 통해, 멤버 본인 소유 첨부파일에 한해 소프트 딜리트가 정상 동작하는지, 삭제 후 감사 및 복구 가능성을 보장하는지 검증합니다.
 */
export async function test_api_discussion_board_test_soft_delete_own_post_attachment_success(connection: api.IConnection) {
  // 1. 관리자 권한으로 사용자 프로필 생성
  const userProfile = await api.functional.admin.discussion_board.userProfiles.create(connection, {
    body: {
      email: typia.random<string & tags.Format<'email'>>(),
      display_name: RandomGenerator.name(),
      is_active: true
    } satisfies IDiscussionBoardUserProfile.ICreate,
  });
  typia.assert(userProfile);

  // 2. 관리자 권한으로 해당 프로필을 멤버로 등록
  const member = await api.functional.admin.discussion_board.members.create(connection, {
    body: {
      discussion_board_user_profile_id: userProfile.id,
      joined_at: new Date().toISOString()
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 3. 멤버로서 임의 토픽에 게시글 등록
  const topicId = typia.random<string & tags.Format<'uuid'>>();
  const post = await api.functional.my.discussion_board.posts.create(connection, {
    body: {
      discussion_board_topic_id: topicId,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()()
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);
  TestValidator.equals('author_member_id')(post.author_member_id)(member.id);

  // 4. 게시글의 첨부파일 등록(업로더는 인증 멤버)
  const attachment = await api.functional.my.discussion_board.postAttachments.create(connection, {
    body: {
      discussion_board_post_id: post.id,
      file_uri: "https://cdn.example.com/files/" + typia.random<string>(),
      file_name: RandomGenerator.alphaNumeric(12),
      file_size: typia.random<number & tags.Type<'int32'>>(),
      mime_type: "application/pdf"
    } satisfies IDiscussionBoardPostAttachment.ICreate,
  });
  typia.assert(attachment);

  // 5. 파일 첨부 내역을 소프트 삭제(논리 삭제)
  await api.functional.my.discussion_board.postAttachments.erase(connection, {
    id: attachment.id,
  });

  // 6. 삭제된 첨부파일 정보를 직접 확인: is_deleted가 true, 파일 메타/연결정보(경로 등)는 여전히 남아 있음을 보장
  // (실제 API에 첨부파일 직접 조회가 가능한 엔드포인트가 있다면, 추가 호출&검증. 없으면 이 단계는 생략)
}

