/**
 * E2E test for listing/searching discussion board members with filters and pagination.
 *
 * 1. Create several user profiles as admin, some with different registration and is_active statuses.
 * 2. Assign some as active board members (without left_at), and others as inactive (with left_at set).
 * 3. Call `discussion_board.members.index` (PATCH /discussion_board/members) in several ways:
 *    a. No filter (should retrieve all, paginated)
 *    b. Filter is_active: true (only members with no left_at)
 *    c. Filter joined_at_start/ended for time window
 *    d. Filter using specific user_profile_id
 *    e. Pagination (limit, page usage)
 *    f. Negative search (joined after a future date, expect no results)
 * 4. For each search, check:
 *   - Response type and schema matches (using typia.assert and TestValidator.predicate)
 *   - All members in response fit query criteria
 *   - Pagination metadata is correct for given params/total records
*/
export async function test_api_discussion_board_test_list_members_with_filters_and_pagination(connection: api.IConnection) {
  // 1. Create user profiles (admin)
  const profiles = await ArrayUtil.asyncRepeat(6)(async (_, i) => {
    const now = new Date();
    const joinedAt = new Date(now.getTime() - (1000 * 3600 * 24 * (i + 1)));
    const registered_at = joinedAt.toISOString();
    const p = await api.functional.admin.discussion_board.userProfiles.create(connection, {
      body: {
        email: `member${i + 1}_${typia.random<string & tags.Format<"email">>()}`,
        display_name: RandomGenerator.name(),
        registered_at,
        is_active: true,
      } satisfies IDiscussionBoardUserProfile.ICreate,
    });
    typia.assert(p);
    return { ...p, _joined_at: registered_at };
  });

  // 2. Assign as board members: 4 active, 2 inactive
  const memberObjs = await ArrayUtil.asyncMap(profiles)((p, idx) =>
    api.functional.admin.discussion_board.members.create(connection, {
      body: {
        discussion_board_user_profile_id: p.id,
        joined_at: p._joined_at,
      } satisfies IDiscussionBoardMember.ICreate,
    })
  );
  // Mark left_at for last 2
  const now = new Date();
  const leftAtTime = new Date(now.getTime() - 1000 * 3600 * 2).toISOString();
  const members = await ArrayUtil.asyncMap(memberObjs)(async (m, i) => {
    if (i >= 4) {
      // simulate inactivation: set left_at using a DB-side method or direct manipulation if possible (not exposed, so just note field)
      // (LEFT_UNDER_IMPLEMENT if no API exists)
      // For later, treat as "inactive" for test result validation
      return { ...m, left_at: leftAtTime };
    }
    return m;
  });

  // Test cases for PATCH /discussion_board/members.index

  // 3a. No filter (all members)
  const outAll = await api.functional.discussion_board.members.index(connection, { body: {} });
  typia.assert(outAll);
  TestValidator.equals("should match all members")(outAll.data.length)(members.length);

  // 3b. Filter active only
  const outActive = await api.functional.discussion_board.members.index(connection, {
    body: { is_active: true },
  });
  typia.assert(outActive);
  TestValidator.equals("only entries with left_at null")(
    outActive.data.every(member => member.left_at == null)
  )(true);
  TestValidator.equals("count active members")(outActive.data.length)(4);

  // 3c. Filter by joined_at window (join >= specific date)
  const windowStart = members[2].joined_at;
  const outWindow = await api.functional.discussion_board.members.index(connection, {
    body: { joined_at_start: windowStart },
  });
  typia.assert(outWindow);
  TestValidator.predicate("every joined_at >= windowStart")(
    outWindow.data.every(m => new Date(m.joined_at) >= new Date(windowStart))
  );

  // 3d. Filter by specific profile id
  const targetProfileId = members[0].discussion_board_user_profile_id;
  const outProfile = await api.functional.discussion_board.members.index(connection, {
    body: { discussion_board_user_profile_id: targetProfileId },
  });
  typia.assert(outProfile);
  TestValidator.equals("member for profile id")(outProfile.data.length)(1);
  TestValidator.equals("profile id matches")(outProfile.data[0].discussion_board_user_profile_id)(targetProfileId);

  // 3e. Pagination filter
  const limit = 2;
  const outPaginate1 = await api.functional.discussion_board.members.index(connection, {
    body: { limit, page: 1 },
  });
  typia.assert(outPaginate1);
  TestValidator.equals("page 1 count")(outPaginate1.data.length)(2);
  TestValidator.equals("pagination current")(outPaginate1.pagination.current)(1);

  const outPaginate2 = await api.functional.discussion_board.members.index(connection, {
    body: { limit, page: 2 },
  });
  typia.assert(outPaginate2);
  TestValidator.equals("page 2 count")(outPaginate2.data.length)(2);
  TestValidator.equals("pagination current")(outPaginate2.pagination.current)(2);

  // 3f. Negative search: join after a future date, expect empty
  const futureDate = new Date(Date.now() + 1000 * 3600 * 24).toISOString();
  const outEmpty = await api.functional.discussion_board.members.index(connection, {
    body: { joined_at_start: futureDate },
  });
  typia.assert(outEmpty);
  TestValidator.equals("no match means empty array")(outEmpty.data.length)(0);
}

