import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostAttachment";
import type { IPageDiscussionBoardPostAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardPostAttachment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test paginated listing of post attachments.
 *
 * This test verifies that the /discussion_board/postAttachments endpoint correctly returns a paginated list of attachments for a given post, including accurate file metadata. The test simulates a real workflow involving user/membership creation and file uploads, checking pagination integrity and record accuracy.
 *
 * Steps:
 * 1. Admin creates a user profile (uploader)
 * 2. Admin assigns the user as a board member
 * 3. Member creates a new post in a topic
 * 4. Member uploads several attachments to the post (exceeding one page, e.g., 12 files)
 * 5. Query the /discussion_board/postAttachments endpoint with a specific page/limit and filter for the post
 * 6. Validate returned data:
 *    a) Page metadata is correct for the total number of attachments
 *    b) The attachments correspond to the correct files and post (metadata matches upload info)
 *    c) Pagination (count, offset, limited results per page) works correctly
 */
export async function test_api_discussion_board_test_list_post_attachments_with_pagination(
  connection: api.IConnection,
) {
  // 1. Admin creates a user profile
  const userProfileInput: IDiscussionBoardUserProfile.ICreate = {
    email: typia.random<string & tags.Format<'email'>>(),
    display_name: RandomGenerator.name(),
    is_active: true,
    registered_at: new Date().toISOString(),
  };
  const userProfile = await api.functional.admin.discussion_board.userProfiles.create(connection, { body: userProfileInput });
  typia.assert(userProfile);

  // 2. Admin assigns user as board member
  const memberInput: IDiscussionBoardMember.ICreate = {
    discussion_board_user_profile_id: userProfile.id,
    joined_at: new Date().toISOString(),
  };
  const member = await api.functional.admin.discussion_board.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 3. Member creates a new post
  // Simulate member context (assume connection context switches to implement RBAC)
  const postInput: IDiscussionBoardPost.ICreate = {
    discussion_board_topic_id: typia.random<string & tags.Format<'uuid'>>(), // topic must exist in DB
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
  };
  const post = await api.functional.my.discussion_board.posts.create(connection, { body: postInput });
  typia.assert(post);

  // 4. Member uploads 12 attachments to the post
  const NUM_ATTACHMENTS = 12;
  const attachmentInputs: IDiscussionBoardPostAttachment.ICreate[] = ArrayUtil.repeat(NUM_ATTACHMENTS)(() => ({
    discussion_board_post_id: post.id,
    file_uri: `https://fileserver/${RandomGenerator.alphaNumeric(16)}`,
    file_name: RandomGenerator.alphaNumeric(10),
    file_size: typia.random<number & tags.Type<'int32'>>(),
    mime_type: RandomGenerator.pick([
