import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopic";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";

/**
 * Test repeated soft deletion of a discussion board post.
 *
 * This test ensures that attempting to soft-delete a post that is already in the deleted (is_deleted=true) state is safely and correctly handled.
 * Expected behavior: The system should either return an appropriate error, or be idempotent—i.e., leave the post in the deleted state without adverse side effects.
 *
 * Steps:
 * 1. Create a user profile as admin.
 * 2. Assign the user profile as a board member (admin action).
 * 3. Create a discussion board category (admin action).
 * 4. Create a topic as the new member (requires authentication context, member must be creator).
 * 5. Create a post under this topic as the member.
 * 6. Soft-delete the post (first attempt).
 * 7. Attempt to soft-delete the post again (second attempt on an already deleted post).
 * 8. Validate system response—must either:
 *    a. Return an error indicating the post is already deleted, or
 *    b. Silently succeed without modifying data further (idempotency check).
 * 9. If returned without error, confirm is_deleted on the post remains true and no unexpected changes occurred.
 */
export async function test_api_discussion_board_posts_test_soft_delete_already_deleted_post(
  connection: api.IConnection,
) {
  // 1. Create a user profile as admin
  const userEmail: string = typia.random<string & tags.Format<"email">>();
  const userProfile = await api.functional.admin.discussion_board.userProfiles.create(
    connection,
    {
      body: {
        email: userEmail,
        display_name: RandomGenerator.name(),
        is_active: true,
      } satisfies IDiscussionBoardUserProfile.ICreate,
    },
  );
  typia.assert(userProfile);

  // 2. Assign the user profile as a board member (admin action)
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userProfile.id,
        joined_at: new Date().toISOString(),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 3. Create a discussion board category
  const categoryCode: string = RandomGenerator.alphaNumeric(10);
  const category = await api.functional.admin.discussion_board.categories.create(
    connection,
    {
      body: {
        code: categoryCode,
        name: RandomGenerator.name(),
        sort_order: 1,
        is_active: true,
      } satisfies IDiscussionBoardCategory.ICreate,
    },
  );
  typia.assert(category);

  // 4. Create a topic as the new member
  // (ASSUME: authentication as member context is automatically switched)
  const topic = await api.functional.my.discussion_board.topics.create(
    connection,
    {
      body: {
        discussion_board_category_id: category.id,
        title: RandomGenerator.paragraph()(),
        description: RandomGenerator.alphabets(20),
        status: "open",
      } satisfies IDiscussionBoardTopic.ICreate,
    },
  );
  typia.assert(topic);

  // 5. Create a post under this topic
  const post = await api.functional.my.discussion_board.posts.create(
    connection,
    {
      body: {
        discussion_board_topic_id: topic.id,
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 6. Soft-delete the post (first attempt)
  const deletedPost = await api.functional.my.discussion_board.posts.erase(
    connection,
    { id: post.id },
  );
  typia.assert(deletedPost);
  TestValidator.equals("is_deleted should be true after first deletion")(deletedPost.is_deleted)(true);

  // 7. Try to soft-delete the already deleted post again
  let repeatDeleteResult: IDiscussionBoardPost | null = null;
  let errorOnRepeatDelete: Error | null = null;
  try {
    repeatDeleteResult = await api.functional.my.discussion_board.posts.erase(
      connection,
      { id: post.id },
    );
    typia.assert(repeatDeleteResult);
  } catch (err) {
    errorOnRepeatDelete = err as Error;
  }

  // 8. Validate: Either error is thrown or idempotent success
  if (errorOnRepeatDelete) {
    TestValidator.error("System returns an error when deleting already deleted post")(
      async () => { throw errorOnRepeatDelete; }
    );
  } else if (repeatDeleteResult) {
    TestValidator.equals("is_deleted remains true after repeated soft-delete")(repeatDeleteResult.is_deleted)(true);
    TestValidator.equals("id of deleted post remains unchanged")(repeatDeleteResult.id)(post.id);
  } else {
    throw new Error("Unexpected result: neither error nor post object returned");
  }
}

