import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopic";
import type { IPageIDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardTopic";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing and searching/filtering topics with pagination in the discussion board.
 *
 * 1. Create two categories.
 * 2. Create two user profiles, make them members.
 * 3. As each member, create multiple topics in different categories, with varied attributes:
 *    - titles/descriptions (ensure some common keyword overlap for search)
 *    - statuses ('open', 'closed', custom value)
 *    - some with pinned_at/closed_at, some without
 * 4. Run various search/list (PATCH /discussion_board/topics) requests:
 *    - No filters (full list, default pagination)
 *    - By keywords (finds only matching titles/descriptions)
 *    - By category (returns only topics in that category)
 *    - By status (only topics with that status)
 *    - By pinned/closed (boolean filters)
 *    - Pagination (e.g., limit=2, page=2, etc)
 *    - Combination of filters (e.g., status + keyword)
 * 5. For each query, check:
 *    - Only topics meeting the filter are returned
 *    - Pagination objects are correct
 *    - Data objects match the schema, and have no extra properties
 *    - If no match, data array is empty
 * 6. Test error handling: pass invalid filters (e.g., non-number page/limit, nonsense status, or non-existent category UUID) - ensure controlled error or empty result.
 */
export async function test_api_discussion_board_test_list_topics_with_pagination_and_search_filters(connection: api.IConnection) {
  // 1. Create two categories
  const category1 = await api.functional.admin.discussion_board.categories.create(connection, { body: {
    code: `cat${RandomGenerator.alphaNumeric(4)}`,
    name: `CategoryOne`,
    description: "First category for testing",
    sort_order: 1,
    is_active: true
  }});
  typia.assert(category1);
  const category2 = await api.functional.admin.discussion_board.categories.create(connection, { body: {
    code: `cat${RandomGenerator.alphaNumeric(4)}`,
    name: `CategoryTwo`,
    description: "Second category for testing",
    sort_order: 2,
    is_active: true
  }});
  typia.assert(category2);
  // 2. Create two user profiles (admin)
  const profile1 = await api.functional.admin.discussion_board.userProfiles.create(connection, { body: {
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    is_active: true
  }});
  typia.assert(profile1);
  const profile2 = await api.functional.admin.discussion_board.userProfiles.create(connection, { body: {
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    is_active: true
  }});
  typia.assert(profile2);
  // 3. Make them members (admin)
  const now = new Date().toISOString();
  const member1 = await api.functional.admin.discussion_board.members.create(connection, { body: {
    discussion_board_user_profile_id: profile1.id, joined_at: now
  }});
  typia.assert(member1);
  const member2 = await api.functional.admin.discussion_board.members.create(connection, { body: {
    discussion_board_user_profile_id: profile2.id, joined_at: now
  }});
  typia.assert(member2);
  // 4. As each member, create topics with various attributes
  // Assume connection automatically assigns authenticated member for /my/discussion_board/topics
  const topicInputs = [
    { category: category1, member: profile1, title: "Cat1 Open Alpha", desc: "Alpha open topic", status: "open", pinned_at: null, closed_at: null },
    { category: category1, member: profile2, title: "Cat1 Closed Beta", desc: "Beta closed topic", status: "closed", pinned_at: null, closed_at: now },
    { category: category2, member: profile1, title: "Cat2 Searchable", desc: "Something unique for search", status: "pinned", pinned_at: now, closed_at: null },
    { category: category2, member: profile2, title: "Cat2 Misc", desc: "Misc open topic", status: "open", pinned_at: null, closed_at: null },
  ];
  const topics: IDiscussionBoardTopic[] = [];
  for (const input of topicInputs) {
    // --- simulate member login if needed ---
    // post as that member
    // Normally, need to switch session/connection token per-member; here we assume sequential testing with proper authentication
    const topic = await api.functional.my.discussion_board.topics.create(connection, { body: {
      discussion_board_category_id: input.category.id,
      title: input.title,
      description: input.desc,
      status: input.status,
      pinned_at: input.pinned_at,
      closed_at: input.closed_at
    } });
    typia.assert(topic);
    topics.push(topic);
  }
  // 5. Query/search cases
  // A. No filter (everything)
  let res = await api.functional.discussion_board.topics.index(connection, { body: {} });
  typia.assert(res);
  TestValidator.predicate("All topics present")(res.data.length >= 4);
  // B. Keyword filter - should match at least one topic
  res = await api.functional.discussion_board.topics.index(connection, { body: { keywords: "Searchable" } });
  typia.assert(res);
  TestValidator.equals("Keyword filter - Searchable title")(res.data.length)(1);
  // C. Category filter
  res = await api.functional.discussion_board.topics.index(connection, { body: { discussion_board_category_id: category1.id } });
