/**
 * Validate listing of topic snapshot history after topic creation and several updates.
 *
 * Scenario:
 * 1. Create a new user profile (as admin)
 * 2. Assign the profile as a discussion board member (as admin)
 * 3. As that member, create a new topic
 * 4. Update the topic multiple times to ensure several snapshots exist
 * 5. Fetch a paginated list of snapshots for the topic using the topic id (and also filter by editor id)
 * 6. Validate that:
 *    - All topic edit versions are present as snapshots
 *    - Snapshots reflect the correct editor/member for each update
 *    - Pagination fields are populated correctly in the response
 *    - Audit/history retention logic is working (history is not lost across updates)
 *
 * This tests the complete version/audit history retention for a topic, and ensures
 * that the snapshot listing endpoint returns all relevant information filtered correctly.
 */
export async function test_api_discussion_board_test_list_topic_snapshots_for_existing_topic(
  connection: api.IConnection,
) {
  // 1. Create a user profile (admin API)
  const profileInput: IDiscussionBoardUserProfile.ICreate = {
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    is_active: true,
  };
  const userProfile = await api.functional.admin.discussion_board.userProfiles.create(connection, {
    body: profileInput,
  });
  typia.assert(userProfile);

  // 2. Assign member role to the profile (admin API)
  const memberInput: IDiscussionBoardMember.ICreate = {
    discussion_board_user_profile_id: userProfile.id,
    joined_at: new Date().toISOString(),
  };
  const member = await api.functional.admin.discussion_board.members.create(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 3. As this member, create a new topic (simulate login/impersonation if needed)
