  const topicInput: IDiscussionBoardTopic.ICreate = {
    discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(8),
    description: RandomGenerator.content()()(16),
    status: "open",
  };
  const topic = await api.functional.my.discussion_board.topics.create(connection, {
    body: topicInput,
  });
  typia.assert(topic);

  // 4. Update the topic multiple times to generate edit snapshots
  const update1: IDiscussionBoardTopic.IUpdate = {
    title: RandomGenerator.paragraph()(8),
  };
  const updatedTopic1 = await api.functional.my.discussion_board.topics.update(connection, {
    id: topic.id,
    body: update1,
  });
  typia.assert(updatedTopic1);

