    description: RandomGenerator.content()()(24),
    status: "closed",
  };
  const updatedTopic2 = await api.functional.my.discussion_board.topics.update(connection, {
    id: topic.id,
    body: update2,
  });
  typia.assert(updatedTopic2);

  // 5. List topic snapshots by topic id (all snapshots for this topic)
  const pageLimit = 5;
  const snapshotsPage = await api.functional.discussion_board.topicSnapshots.index(connection, {
    body: {
      discussion_board_topic_id: topic.id,
      page: 1,
      limit: pageLimit,
    },
  });
  typia.assert(snapshotsPage);

  // 6. Validation:
  // - There should be at least three snapshots (initial + 2 updates)
  TestValidator.predicate("at least 3 snapshots exist for this topic")(snapshotsPage.data.length >= 3);
  // - Snapshots should be for the given topic
  snapshotsPage.data.forEach((snap) => {
    TestValidator.equals("correct topic id in snapshot")(snap.discussion_board_topic_id)(topic.id);
  });

  // - (Edge) Filter by editor/member id: Should match editor
  const editorSnapshots = await api.functional.discussion_board.topicSnapshots.index(connection, {
    body: {
      discussion_board_topic_id: topic.id,
      edited_by_member_id: member.id,
      limit: pageLimit,
    },
  });
  typia.assert(editorSnapshots);
  editorSnapshots.data.forEach((snap) => {
    TestValidator.equals("edited by member matches fetch filter")(snap.edited_by_member_id)(member.id);
    TestValidator.equals("snapshot topic matches fetch filter")(snap.discussion_board_topic_id)(topic.id);
  });

  // - Pagination metadata should be populated
  TestValidator.equals("page number is 1")(snapshotsPage.pagination.current)(1);
  TestValidator.equals("limit matches")(snapshotsPage.pagination.limit)(pageLimit);
}

