import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardFlaggedContent } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardFlaggedContent";
import type { IPageIDiscussionBoardFlaggedContent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardFlaggedContent";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate admin retrieval of paginated and filterable flagged content moderation records.
 *
 * Business context: Flagged content records are used for moderation workflows in the discussion board, allowing administrators to monitor problematic content. The admin must be able to fetch a paginated list of these records, filter them using various criteria (flag type, cleared status, involved actors, entity types/IDs), and depend on proper result structure for workflows (including evidence of empty result sets for non-matching queries).
 *
 * Steps:
 * 1. Preparation: Create several flagged content records (with diverse combinations for flagged_entity_type, cleared, flagged_by_admin_id/flagged_by_moderator_id, entity_id, flag_type, created_at).
 * 2. Query: Fetch records with each of the supported filters one-by-one (flagged_entity_type, cleared, flagged_by_admin_id, flagged_by_moderator_id, flagged_entity_id, flag_type, created_at), and combinations (multi-filter), validating output strictly matches expectations.
 * 3. Pagination: Use limit/page type queries to test result slicing (e.g., get page 2 with a lower limit, check order and total counts).
 * 4. Sorting: If sorting is supported, validate correct order. (Skip if not exposed in this API; schema doesn't show sort fields.)
 * 5. Negative/empty case: Use an illogical filter (e.g. non-existent flagged_entity_type, id, or actor) and check "data" is an empty list, total records is 0, etc.
 * 6. Field check: All response records must expose only documented fields, and values must match what was inserted.
 */
export async function test_api_admin_discussion_board_flaggedContent_test_list_flagged_content_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Preparation: Bulk create flagged content records with variations
  const flaggedRecords: IDiscussionBoardFlaggedContent[] = await ArrayUtil.asyncRepeat(10)(async (idx) => {
    const createBody: IDiscussionBoardFlaggedContent.ICreate = {
      flagged_by_admin_id: idx % 2 === 0 ? typia.random<string & tags.Format<"uuid">>() : null,
      flagged_by_moderator_id: idx % 2 === 1 ? typia.random<string & tags.Format<"uuid">>() : null,
      flagged_entity_id: typia.random<string & tags.Format<"uuid">>(),
      flagged_entity_type: idx % 3 === 0 ? "post" : idx % 3 === 1 ? "comment" : "user",
      flag_type: idx % 2 === 0 ? "manual" : "auto",
      reason: idx % 4 === 0 ? "Rule violation" : undefined,
      cleared: idx % 2 === 0,
      created_at: new Date(Date.now() - idx * 1000 * 60 * 60).toISOString(),
    };
    const rec = await api.functional.admin.discussion_board.flaggedContent.create(connection, { body: createBody });
    typia.assert(rec);
    // Ensure what was returned matches what we put in (except id and created_at, which may be generated)
    TestValidator.equals(`flagged_entity_type matches`)(rec.flagged_entity_type)(createBody.flagged_entity_type);
    TestValidator.equals(`flag_type matches`)(rec.flag_type)(createBody.flag_type);
    TestValidator.equals(`cleared matches`)(rec.cleared)(createBody.cleared);
    TestValidator.equals(`flagged_by_admin_id matches`)(rec.flagged_by_admin_id ?? null)(createBody.flagged_by_admin_id ?? null);
    TestValidator.equals(`flagged_by_moderator_id matches`)(rec.flagged_by_moderator_id ?? null)(createBody.flagged_by_moderator_id ?? null);
    return rec;
  });

  // Helper: build minimal query body for filter
  const query = async (body: Partial<IDiscussionBoardFlaggedContent.IRequest>): Promise<IPageIDiscussionBoardFlaggedContent> => {
    const result = await api.functional.admin.discussion_board.flaggedContent.index(connection, { body: { ...body } });
    typia.assert(result);
    return result;
  };

  // 2. Filter queries - test each filter field in isolation (flagged_entity_type, cleared, actors, flag_type, entity_id, created_at)
  const testFilters = [
    { key: "flagged_entity_type", value: "post" },
    { key: "flagged_entity_type", value: "comment" },
    { key: "flagged_entity_type", value: "user" },
    { key: "cleared", value: true },
    { key: "cleared", value: false },
    { key: "flagged_by_admin_id", value: flaggedRecords[0].flagged_by_admin_id },
    { key: "flagged_by_moderator_id", value: flaggedRecords[1].flagged_by_moderator_id },
    { key: "flag_type", value: "manual" },
    { key: "flag_type", value: "auto" },
    { key: "flagged_entity_id", value: flaggedRecords[2].flagged_entity_id },
    { key: "created_at", value: flaggedRecords[3].created_at },
  ];
  for (const { key, value } of testFilters) {
    if (value === undefined || value === null) continue;
    const body = { [key]: value };
    const res = await query(body);
    for (const rec of res.data)
      TestValidator.equals(`${key} filter matches for ${value}`)(rec[key])(value);
  }

  // 3. Multi-filter query
  const multiFilter = {
    flagged_entity_type: "post",
    cleared: true,
    flag_type: "manual",
  };
  const multiRes = await query(multiFilter);
  for (const rec of multiRes.data) {
    TestValidator.equals("multi filter: entity_type")
      (rec.flagged_entity_type)(multiFilter.flagged_entity_type);
    TestValidator.equals("multi filter: cleared")
      (rec.cleared)(multiFilter.cleared);
    TestValidator.equals("multi filter: flag_type")
      (rec.flag_type)(multiFilter.flag_type);
  }

  // 4. Pagination (limit current/total/pages logic)
  const limit = 3;
  const page1 = await query({ flagged_entity_type: "post", cleared: true, flag_type: "manual" });
  const page2 = await query({ flagged_entity_type: "post", cleared: true, flag_type: "manual" });
  // Should always return <= limit; (since endpoint lacks explicit limit param, we can only check default pagination)
  TestValidator.predicate("page1 data length <= limit")(page1.data.length <= limit);
  TestValidator.equals("pagination consistency")(page1.pagination.records)(multiRes.pagination.records);

  // 5. Empty result (no match)
  const empty = await query({ flagged_entity_type: "nonexistent_type_value" });
  TestValidator.equals("empty result for nonsense filter")(empty.data.length)(0);
  TestValidator.equals("empty records count")(empty.pagination.records)(0);

  // 6. Field check
  for (const rec of page1.data) {
    typia.assert(rec); // Schema assertion covers fields
    // Additionally, ensure no extra fields
    const keys = Object.keys(rec).sort();
    const allowed = [
      "id",
      "flagged_by_admin_id",
      "flagged_by_moderator_id",
      "flagged_entity_id",
      "flagged_entity_type",
      "flag_type",
      "reason",
      "cleared",
      "created_at",
    ].sort();
    TestValidator.equals("only allowed fields exposed")(keys)(allowed);
  }
}

