  // 4. Validation: malformed UUID for flagged_by_admin_id
  await TestValidator.error("malformed flagged_by_admin_id fails")(() =>
    api.functional.admin.discussion_board.flaggedContent.create(connection, {
      body: {
        flagged_by_admin_id: "bad-uuid-value",
        flagged_by_moderator_id: null,
        flagged_entity_id: flaggedEntityId,
        flagged_entity_type: flaggedEntityType,
        flag_type: flagType,
        reason: reason,
        cleared: false,
        created_at: now,
      } as any,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardFlaggedContent } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardFlaggedContent";
import type { IPageIDiscussionBoardFlaggedContent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardFlaggedContent";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate admin retrieval of paginated and filterable flagged content
 * moderation records.
 *
 * Business context: Flagged content records are used for moderation workflows
 * in the discussion board, allowing administrators to monitor problematic
 * content. The admin must be able to fetch a paginated list of these records,
 * filter them using various criteria (flag type, cleared status, involved
 * actors, entity types/IDs), and depend on proper result structure for
 * workflows (including evidence of empty result sets for non-matching
 * queries).
 *
 * Steps:
 *
 * 1. Preparation: Create several flagged content records (with diverse
 *    combinations for flagged_entity_type, cleared,
 *    flagged_by_admin_id/flagged_by_moderator_id, entity_id, flag_type,
 *    created_at).
 * 2. Query: Fetch records with each of the supported filters one-by-one
 *    (flagged_entity_type, cleared, flagged_by_admin_id,
 *    flagged_by_moderator_id, flagged_entity_id, flag_type, created_at), and
 *    combinations (multi-filter), validating output strictly matches
 *    expectations.
 * 3. Pagination: Use limit/page type queries to test result slicing (e.g., get
 *    page 2 with a lower limit, check order and total counts).
 * 4. Negative/empty case: Use an illogical filter (e.g. non-existent
 *    flagged_entity_type, id, or actor) and check "data" is an empty list,
 *    total records is 0, etc.
 * 5. Field check: All response records must expose only documented fields, and
 *    values must match what was inserted.
 */
export async function test_api_admin_discussion_board_flaggedContent_test_list_flagged_content_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Preparation: Bulk create flagged content records with variations
  const flaggedRecords: IDiscussionBoardFlaggedContent[] =
    await ArrayUtil.asyncRepeat(10)(async (idx) => {
      const createBody: IDiscussionBoardFlaggedContent.ICreate = {
        flagged_by_admin_id:
          idx % 2 === 0 ? typia.random<string & tags.Format<"uuid">>() : null,
        flagged_by_moderator_id:
          idx % 2 === 1 ? typia.random<string & tags.Format<"uuid">>() : null,
        flagged_entity_id: typia.random<string & tags.Format<"uuid">>(),
        flagged_entity_type:
          idx % 3 === 0 ? "post" : idx % 3 === 1 ? "comment" : "user",
        flag_type: idx % 2 === 0 ? "manual" : "auto",
        reason: idx % 4 === 0 ? "Rule violation" : undefined,
        cleared: idx % 2 === 0,
        created_at: new Date(Date.now() - idx * 1000 * 60 * 60).toISOString(),
      };
      const rec =
        await api.functional.admin.discussion_board.flaggedContent.create(
          connection,
          { body: createBody },
        );
      typia.assert(rec);
      // Ensure what was returned matches what we put in (except id and created_at, which may be generated)
      TestValidator.equals(`flagged_entity_type matches`)(
        rec.flagged_entity_type,
      )(createBody.flagged_entity_type);
      TestValidator.equals(`flag_type matches`)(rec.flag_type)(
        createBody.flag_type,
      );
      TestValidator.equals(`cleared matches`)(rec.cleared)(createBody.cleared);
      TestValidator.equals(`flagged_by_admin_id matches`)(
        rec.flagged_by_admin_id ?? null,
      )(createBody.flagged_by_admin_id ?? null);
      TestValidator.equals(`flagged_by_moderator_id matches`)(
        rec.flagged_by_moderator_id ?? null,
      )(createBody.flagged_by_moderator_id ?? null);
      return rec;
    });

  // Helper: build minimal query body for filter
  const query = async (
    body: Partial<IDiscussionBoardFlaggedContent.IRequest>,
  ): Promise<IPageIDiscussionBoardFlaggedContent> => {
    const result =
      await api.functional.admin.discussion_board.flaggedContent.index(
        connection,
        { body: { ...body } },
      );
    typia.assert(result);
    return result;
  };

  // 2. Filter queries - test each filter field in isolation (flagged_entity_type, cleared, actors, flag_type, entity_id, created_at)
  const testFilters = [
    { key: "flagged_entity_type", value: "post" },
    { key: "flagged_entity_type", value: "comment" },
    { key: "flagged_entity_type", value: "user" },
    { key: "cleared", value: true },
    { key: "cleared", value: false },
    {
      key: "flagged_by_admin_id",
      value: flaggedRecords[0].flagged_by_admin_id,
    },
    {
      key: "flagged_by_moderator_id",
      value: flaggedRecords[1].flagged_by_moderator_id,
    },
    { key: "flag_type", value: "manual" },
    { key: "flag_type", value: "auto" },
    { key: "flagged_entity_id", value: flaggedRecords[2].flagged_entity_id },
    { key: "created_at", value: flaggedRecords[3].created_at },
  ];
  for (const { key, value } of testFilters) {
    if (value === undefined || value === null) continue;
    const body = { [key]: value };
    const res = await query(body);
    for (const rec of res.data)
      TestValidator.equals(`${key} filter matches for ${value}`)(rec[key])(
        value,
      );
  }

  // 3. Multi-filter query
  const multiFilter = {
    flagged_entity_type: "post",
    cleared: true,
    flag_type: "manual",
  };
  const multiRes = await query(multiFilter);
  for (const rec of multiRes.data) {
    TestValidator.equals("multi filter: entity_type")(rec.flagged_entity_type)(
      multiFilter.flagged_entity_type,
    );
    TestValidator.equals("multi filter: cleared")(rec.cleared)(
      multiFilter.cleared,
    );
    TestValidator.equals("multi filter: flag_type")(rec.flag_type)(
      multiFilter.flag_type,
    );
  }

  // 4. Pagination (limit current/total/pages logic)
  const limit = 3;
  const page1 = await query({
    flagged_entity_type: "post",
    cleared: true,
    flag_type: "manual",
  });
  const page2 = await query({
    flagged_entity_type: "post",
    cleared: true,
    flag_type: "manual",
  });
  // Should always return <= limit; (since endpoint lacks explicit limit param, we can only check default pagination)
  TestValidator.predicate("page1 data length <= limit")(
    page1.data.length <= limit,
  );
  TestValidator.equals("pagination consistency")(page1.pagination.records)(
    multiRes.pagination.records,
  );

  // 5. Empty result (no match)
  const empty = await query({ flagged_entity_type: "nonexistent_type_value" });
  TestValidator.equals("empty result for nonsense filter")(empty.data.length)(
    0,
  );
  TestValidator.equals("empty records count")(empty.pagination.records)(0);

  // 6. Field check
  for (const rec of page1.data) {
    typia.assert(rec); // Schema assertion covers fields
    // Additionally, ensure no extra fields
    const keys = Object.keys(rec).sort();
    const allowed = [
      "id",
      "flagged_by_admin_id",
      "flagged_by_moderator_id",
      "flagged_entity_id",
      "flagged_entity_type",
      "flag_type",
      "reason",
      "cleared",
      "created_at",
    ].sort();
    TestValidator.equals("only allowed fields exposed")(keys)(allowed);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";
import type { IPageIDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardNotification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E Test: List authenticated user's notifications with various filters
 *
 * This test verifies the /discussion_board/notifications PATCH endpoint, which
 * allows an authenticated user to fetch their own notifications inbox with
 * support for all documented filters and pagination.
 *
 * Steps:
 *
 * 1. Use an authenticated user (the test context's connection).
 * 2. Validate empty notifications result: expect an empty array when no
 *    notifications exist.
 * 3. Create multiple notifications for this user, with varied:
 *
 *    - Is_read values (some unread, some later marked as read)
 *    - 'type' values (e.g., 'new_reply', 'system_announcement')
 *    - Distinct content patterns (for keyword search)
 *    - Different delivered_at (spread over past/future times for date filters)
 * 4. Mark a subset of notifications as read, confirming both is_read and read_at.
 * 5. Query notifications with multiple filters:
 *
 *    - Is_read (true/false)
 *    - By type
 *    - Keyword in content
 *    - Delivered_at lower boundary
 *    - Read_at lower boundary (for read notifications)
 *    - With small pagination size (e.g., limit = 1)
 * 6. For each filter case, make assertions:
 *
 *    - All notifications in result belong to the test user.
 *    - Count and paging info matches expectations/number of created objects
 *    - Content, type, is_read, delivered_at, read_at all conform to filter
 * 7. Confirm that notifications for other users, if present, never appear (data
 *    isolation).
 * 8. Confirm edge-case: when no notifications at all, result is [] with valid
 *    paging.
 */
export async function test_api_discussion_board_test_list_notifications_for_authenticated_user_with_various_filters(
  connection: api.IConnection,
) {
  // 1. Get the recipient_user_id (current user) from a created notification's result
  // First, verify empty inbox (should be empty array)
  const emptyList = await api.functional.discussion_board.notifications.index(
    connection,
    {
      body: {},
    },
  );
  typia.assert(emptyList);
  TestValidator.equals("empty notification list")(emptyList.data)([]);
  TestValidator.predicate("pagination object exists")(
    typeof emptyList.pagination === "object",
  );

  // 2. Create several notifications with varying properties for this user
  // Use a stable timestamp base for filtering
  const baseTime = new Date();
  const pastTime = new Date(baseTime);
  pastTime.setDate(baseTime.getDate() - 3);
  const recentTime = new Date(baseTime);
  recentTime.setMinutes(baseTime.getMinutes() - 1);

  const notificationTypeA = "new_reply";
  const notificationTypeB = "system_announcement";
  const testContents = [
    "Welcome to the board!",
    "Your question received a reply.",
    "Action required: System update notice",
    "You have been mentioned in a reply.",
  ];

  // Create notifications: 2 unread (typeA and typeB), 2 read (after marking as read)
  const created: api.DiscussionBoard.IDiscussionBoardNotification[] = [];

  for (let i = 0; i < testContents.length; ++i) {
    const notif: api.DiscussionBoard.IDiscussionBoardNotification =
      await api.functional.my.discussion_board.notifications.create(
        connection,
        {
          body: {
            recipient_user_id: typia.random<string & tags.Format<"uuid">>(), // will be replaced by server-side (current user)
            type: i % 2 === 0 ? notificationTypeA : notificationTypeB,
            content: testContents[i],
            is_read: false,
            delivered_at:
              i < 2 ? pastTime.toISOString() : recentTime.toISOString(),
            read_at: null,
          } satisfies api.DiscussionBoard.IDiscussionBoardNotification.ICreate,
        },
      );
    typia.assert(notif);
    created.push(notif);
  }

  // Get current user's id from any returned notification
  const recipient_user_id = created[0].recipient_user_id;

  // Mark two notifications as read (update)
  const toRead = [created[2], created[3]];
  const nowIso = new Date().toISOString();
  for (const notif of toRead) {
    const updated =
      await api.functional.my.discussion_board.notifications.update(
        connection,
        {
          id: notif.id,
          body: { is_read: true, read_at: nowIso },
        },
      );
    typia.assert(updated);
    TestValidator.equals("read status set")(updated.is_read)(true);
    TestValidator.equals("read_at set")(updated.read_at)(nowIso);
  }

  // 3. Now test various filter options

  // a) Filter is_read = false (should return only unread)
  const unreadList = await api.functional.discussion_board.notifications.index(
    connection,
    {
      body: { is_read: false },
    },
  );
  typia.assert(unreadList);
  TestValidator.predicate("all unread")(
    unreadList.data.every((n) => n.is_read === false),
  );

  // b) Filter is_read = true (should return only read)
  const readList = await api.functional.discussion_board.notifications.index(
    connection,
    {
      body: { is_read: true },
    },
  );
  typia.assert(readList);
  TestValidator.predicate("all read")(
    readList.data.every((n) => n.is_read === true),
  );

  // c) Filter by type
  const typeAList = await api.functional.discussion_board.notifications.index(
    connection,
    {
      body: { type: notificationTypeA },
    },
  );
  typia.assert(typeAList);
  TestValidator.predicate("all typeA")(
    typeAList.data.every((n) => n.type === notificationTypeA),
  );

  // d) Filter by keyword (content) - e.g., keyword = 'reply'
  const keyword = "reply";
  const keywordList = await api.functional.discussion_board.notifications.index(
    connection,
    {
      body: { content: keyword },
    },
  );
  typia.assert(keywordList);
  TestValidator.predicate("all contents include keyword")(
    keywordList.data.every((n) => n.content.includes(keyword)),
  );

  // e) delivered_at boundary (should get only notifications delivered recently)
  const deliveredAtList =
    await api.functional.discussion_board.notifications.index(connection, {
      body: { delivered_at: recentTime.toISOString() },
    });
  typia.assert(deliveredAtList);
  TestValidator.predicate("all delivered_at >= filter")(
    deliveredAtList.data.every((n) => new Date(n.delivered_at) >= recentTime),
  );

  // f) read_at boundary (should get only notifications read after a given time)
  const readAtList = await api.functional.discussion_board.notifications.index(
    connection,
    {
      body: { read_at: nowIso },
    },
  );
  typia.assert(readAtList);
  TestValidator.predicate("all read_at >= filter")(
    readAtList.data.every(
      (n) => n.read_at && new Date(n.read_at) >= new Date(nowIso),
    ),
  );

  // g) Pagination: limit 1
  const pagedOne = await api.functional.discussion_board.notifications.index(
    connection,
    {
      body: {},
    },
  );
  typia.assert(pagedOne);
  TestValidator.equals("pagination matches count")(pagedOne.pagination.records)(
    created.length,
  );

  // Confirm that all returned notifications are for the correct user
  for (const resp of [
    unreadList,
    readList,
    typeAList,
    keywordList,
    deliveredAtList,
    readAtList,
    pagedOne,
  ]) {
    TestValidator.predicate("no foreign notifications")(
      resp.data.every((n) => n.recipient_user_id === recipient_user_id),
    );
  }

  // 7. Negative case: Confirm another user's notifications do not appear
  // (if multi-user context is viable; here, simulate by creating notification with another random uuid)
  const otherUserNotif =
    await api.functional.my.discussion_board.notifications.create(connection, {
      body: {
        recipient_user_id: typia.random<string & tags.Format<"uuid">>(),
        type: "test_type",
        content: "Should not appear in current user's inbox",
        is_read: false,
        delivered_at: baseTime.toISOString(),
        read_at: null,
      },
    });
  typia.assert(otherUserNotif);

  const afterForeign =
    await api.functional.discussion_board.notifications.index(connection, {
      body: {},
    });
  typia.assert(afterForeign);
  TestValidator.predicate("still no foreign notifications")(
    afterForeign.data.every((n) => n.recipient_user_id === recipient_user_id),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";

/**
 * E2E test: Creating discussion board notifications for the authenticated user
 *
 * Validates the following business requirements:
 *
 * 1. An authenticated user can create a notification for themselves (with valid
 *    fields: recipient_user_id, type, content, delivered_at, and is_read).
 * 2. The notification appears in the user's inbox after creation (by directly
 *    asserting the returned notification for recipient correctness).
 * 3. If required fields are missing, the API returns a validation error.
 * 4. Users cannot create a notification for a different user (recipient_user_id
 *    must match the authenticated user).
 *
 * Test Steps:
 *
 * 1. Prepare a valid notification creation request, ensuring recipient_user_id
 *    matches authenticated user.
 * 2. Perform creation: should succeed; validate returned notification fields and
 *    recipient ownership.
 * 3. Attempt to create notification with missing required fields (should fail with
 *    error).
 * 4. Attempt to create a notification for another user (recipient_user_id !=
 *    logged-in user). Should fail with error.
 */
export async function test_api_my_test_create_notification_for_authenticated_user(
  connection: api.IConnection,
) {
  // 1. Prepare input for the authenticated user (assuming auth context is set)
  // We need a valid "recipient_user_id" (should match the authenticated user)
  // For E2E, if connection.user?.id exists, use it; otherwise, generate a random UUID
  const myUserId =
    connection.user?.id ?? typia.random<string & tags.Format<"uuid">>();

  // --- Success path: create a notification for self ---
  const createBody: IDiscussionBoardNotification.ICreate = {
    recipient_user_id: myUserId,
    type: "new_reply",
    content: "You have a new reply to your discussion.",
    is_read: false,
    delivered_at: new Date().toISOString() as string & tags.Format<"date-time">,
    read_at: null,
  };
  const notification =
    await api.functional.my.discussion_board.notifications.create(connection, {
      body: createBody,
    });
  typia.assert(notification);
  TestValidator.equals("recipient matches user")(
    notification.recipient_user_id,
  )(myUserId);
  TestValidator.equals("is_read default")(notification.is_read)(false);
  TestValidator.equals("type matches")(notification.type)(createBody.type);
  TestValidator.equals("content matches")(notification.content)(
    createBody.content,
  );

  // --- Error case 1: Missing required fields ---
  // Purposely omitting required fields using 'as any' to trigger runtime validation error.
  await TestValidator.error("missing required fields fail")(async () => {
    await api.functional.my.discussion_board.notifications.create(connection, {
      body: {
        // recipient_user_id and 'type' are intentionally omitted
        content: "Incomplete data - should fail.",
        is_read: false,
        delivered_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
        read_at: null,
      } as any, // Safe for negative test case
    });
  });

  // --- Error case 2: Attempt to create for another user (recipient_user_id not matching authenticated user) ---
  await TestValidator.error("cannot create notification for other user")(
    async () => {
      await api.functional.my.discussion_board.notifications.create(
        connection,
        {
          body: {
            recipient_user_id: typia.random<string & tags.Format<"uuid">>(), // Not myUserId
            type: "new_reply",
            content: "Malicious attempt.",
            is_read: false,
            delivered_at: new Date().toISOString() as string &
              tags.Format<"date-time">,
            read_at: null,
          },
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
