import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";

/**
 * Permanently delete a discussion board notification for the authenticated
 * user.
 *
 * This E2E test verifies that an authenticated user can fully and irreversibly
 * delete their own notification from the system. It confirms that deletion
 * eliminates all access to the record, and verifies correct error handling for
 * attempts to delete already-deleted, nonexistent, or non-owned notifications.
 *
 * Steps:
 *
 * 1. Create a notification as the authenticated user.
 * 2. Delete the notification using the erase API — expect success.
 * 3. Try to delete the same notification again — expect error (not found).
 * 4. Try to delete a random, nonexistent notification ID — expect error.
 * 5. (If API allowed) Try to delete another user's notification — omitted here.
 *
 * When supported, access or deletion of a removed notification should always
 * fail.
 */
export async function test_api_my_discussion_board_notifications_test_delete_notification_for_authenticated_user(
  connection: api.IConnection,
) {
  // 1. Create a notification for self (authenticated user)
  const notification =
    await api.functional.my.discussion_board.notifications.create(connection, {
      body: {
        recipient_user_id: connection.authenticated_user_id,
        type: "new_reply",
        content: "You have a new reply!",
        is_read: false,
        delivered_at: new Date().toISOString(),
        read_at: null,
      } satisfies IDiscussionBoardNotification.ICreate,
    });
  typia.assert(notification);

  // 2. Delete notification — expect success (void)
  await api.functional.my.discussion_board.notifications.erase(connection, {
    id: notification.id,
  });

  // 3. Try to delete again — expect error (not found)
  await TestValidator.error("deleting already-deleted notification")(() =>
    api.functional.my.discussion_board.notifications.erase(connection, {
      id: notification.id,
    }),
  );

  // 4. Try to delete random (nonexistent) notification — expect error (not found)
  const fakeId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("deleting nonexistent notification")(() =>
    api.functional.my.discussion_board.notifications.erase(connection, {
      id: fakeId,
    }),
  );

  // 5. Deleting other user's notification requires cross-user control—omitted (no such API in current E2E scope)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPageIDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for listing/searching discussion board members with filters and
 * pagination.
 *
 * Validates the ability to retrieve a paginated and filtered list of board
 * members. The workflow creates multiple user profiles and assigns them as
 * board members with controlled joined_at times and simulates some as inactive.
 * The test retrieves members using various filters (active only, joined_at date
 * window, specific user_profile_id, pagination) and validates responses for
 * correctness, filtering accuracy, and pagination. Also checks empty result
 * edge case.
 *
 * **Test Steps:**
 *
 * 1. Admin creates multiple user profiles with distinct registration times.
 * 2. Admin assigns user profiles as board members, with 4 left active (left_at
 *    null) and 2 simulated as inactive (left_at set locally for test
 *    assertions, since no API to update this field).
 * 3. Calls /discussion_board/members.index multiple ways: a. No filter (all
 *    members) b. Filter by active status (is_active: true) c. Filter by
 *    joined_at from a specific date/window d. Filter by specific user_profile
 *    id e. Pagination (limit, page) f. Negative search edge case (future join
 *    date, expect empty)
 * 4. For each, asserts result schema, verifies all entries match criteria, checks
 *    pagination and query logic, and covers empty array handling.
 */
export async function test_api_discussion_board_test_list_members_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create user profiles (admin)
  const profiles = await ArrayUtil.asyncRepeat(6)(async (_, i) => {
    const now = new Date();
    const joinedAt = new Date(now.getTime() - 1000 * 3600 * 24 * (i + 1));
    const registered_at = joinedAt.toISOString();
    const p = await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: `member${i + 1}_${typia.random<string & tags.Format<"email">>()}`,
          display_name: RandomGenerator.name(),
          registered_at,
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
    typia.assert(p);
    return { ...p, _joined_at: registered_at };
  });

  // 2. Assign as board members: 4 active, 2 inactive
  const memberObjs = await ArrayUtil.asyncMap(profiles)((p, idx) =>
    api.functional.admin.discussion_board.members.create(connection, {
      body: {
        discussion_board_user_profile_id: p.id,
        joined_at: p._joined_at,
      } satisfies IDiscussionBoardMember.ICreate,
    }),
  );
  // Mark left_at for last 2 for test logic (not in DB, but for assertion context)
  const now = new Date();
  const leftAtTime = new Date(now.getTime() - 1000 * 3600 * 2).toISOString();
  const members = await ArrayUtil.asyncMap(memberObjs)(async (m, i) => {
    if (i >= 4) {
      // Simulate inactivation for assertion (no API for this). Not reflected in DB.
      return { ...m, left_at: leftAtTime };
    }
    return m;
  });

  // 3a. No filter
  const outAll = await api.functional.discussion_board.members.index(
    connection,
    { body: {} },
  );
  typia.assert(outAll);
  TestValidator.equals("should match all members")(outAll.data.length)(
    members.length,
  );

  // 3b. Filter active only
  const outActive = await api.functional.discussion_board.members.index(
    connection,
    {
      body: { is_active: true },
    },
  );
  typia.assert(outActive);
  TestValidator.equals("only entries with left_at null")(
    outActive.data.every((member) => member.left_at == null),
  )(true);
  TestValidator.equals("count active members")(outActive.data.length)(4);

  // 3c. Filter joined_at window
  const windowStart = members[2].joined_at;
  const outWindow = await api.functional.discussion_board.members.index(
    connection,
    {
      body: { joined_at_start: windowStart },
    },
  );
  typia.assert(outWindow);
  TestValidator.predicate("every joined_at >= windowStart")(
    outWindow.data.every((m) => new Date(m.joined_at) >= new Date(windowStart)),
  );

  // 3d. Filter by specific profile id
  const targetProfileId = members[0].discussion_board_user_profile_id;
  const outProfile = await api.functional.discussion_board.members.index(
    connection,
    {
      body: { discussion_board_user_profile_id: targetProfileId },
    },
  );
  typia.assert(outProfile);
  TestValidator.equals("member for profile id")(outProfile.data.length)(1);
  TestValidator.equals("profile id matches")(
    outProfile.data[0].discussion_board_user_profile_id,
  )(targetProfileId);

  // 3e. Pagination: page and limit
  const limit = 2;
  const outPaginate1 = await api.functional.discussion_board.members.index(
    connection,
    {
      body: { limit, page: 1 },
    },
  );
  typia.assert(outPaginate1);
  TestValidator.equals("page 1 count")(outPaginate1.data.length)(2);
  TestValidator.equals("pagination current")(outPaginate1.pagination.current)(
    1,
  );

  const outPaginate2 = await api.functional.discussion_board.members.index(
    connection,
    {
      body: { limit, page: 2 },
    },
  );
  typia.assert(outPaginate2);
  TestValidator.equals("page 2 count")(outPaginate2.data.length)(2);
  TestValidator.equals("pagination current")(outPaginate2.pagination.current)(
    2,
  );

  // 3f. Negative search (future join date, expect empty)
  const futureDate = new Date(Date.now() + 1000 * 3600 * 24).toISOString();
  const outEmpty = await api.functional.discussion_board.members.index(
    connection,
    {
      body: { joined_at_start: futureDate },
    },
  );
  typia.assert(outEmpty);
  TestValidator.equals("no match means empty array")(outEmpty.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IPageDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 게시판 카테고리 목록 (페이지네이션, 검색, 정렬, 활성/비활성 edge) 조회 검증
 *
 * 이 테스트는 discussion_board 카테고리 목록 API가 page/limit, search, sort_field,
 * sort_order 등 모든 주요 파라미터를 정확히 반영하는지, 반환 객체 내 필드가 실제 스키마와 일치하는지, 빈 목록/전체 비활성 같은
 * edge case까지 제대로 지원하는지 검증합니다.
 *
 * 주요 커버리지는 아래와 같습니다.
 *
 * 1. 카테고리 없는 상태에서 조회 - 빈 배열 반환
 * 2. Page/limit 생략(기본값) - 전체 카테고리 조회 및 pagination 정보 타입/값 확인
 * 3. 검색(search) 파라미터 - 일부 name/description 포함 필터 동작
 * 4. 정렬(sorting) 파라미터(sort_field, sort_order) 동작 (sort_order asc 기준 검증)
 * 5. 전체 비활성 상태인 경우 정상 조회 및 is_active===false인 카테고리들만 반환
 * 6. 반환 데이터에 실제 스키마 외 필드 없음 검증(typia.assert)
 *
 * 반환/데이터 유효성은 typia.assert, TestValidator로 step별 점진 검증합니다.
 */
export async function test_api_discussion_board_test_list_categories_with_pagination_and_search(
  connection: api.IConnection,
) {
  // 1. 카테고리 없는 상태에서 조회 (빈 배열 검증)
  const emptyResult = await api.functional.discussion_board.categories.index(
    connection,
    {
      body: {},
    },
  );
  typia.assert(emptyResult);
  TestValidator.equals("empty data array")(emptyResult.data.length)(0);

  // 2. 기본 페이징 조회 (전체)
  const baseResult = await api.functional.discussion_board.categories.index(
    connection,
    {
      body: {},
    },
  );
  typia.assert(baseResult);
  TestValidator.predicate("valid pagination")(
    baseResult.pagination.current >= 1 && baseResult.pagination.pages >= 1,
  );
  TestValidator.predicate("records matches data length")(
    baseResult.pagination.records >= baseResult.data.length,
  );
  // 반환 객체 각 요소 스키마 필드만 포함 검증
  baseResult.data.forEach((cat) => typia.assert(cat));

  // 3. 검색(search) 파라미터
  if (baseResult.data.length > 0) {
    // 일부 name/description 포함 텍스트로 검색
    const searchTerm = baseResult.data[0].name.substring(0, 2);
    const searchResult = await api.functional.discussion_board.categories.index(
      connection,
      {
        body: { search: searchTerm },
      },
    );
    typia.assert(searchResult);
    searchResult.data.forEach((cat) => {
      TestValidator.predicate("검색 결과 name/description 포함 여부")(
        cat.name.includes(searchTerm) ||
          (cat.description && cat.description.includes(searchTerm)),
      );
    });
  }

  // 4. 정렬 파라미터(sorting)
  if (baseResult.data.length >= 2) {
    // sort_field = sort_order, sort_order = asc 기준
    const ascResult = await api.functional.discussion_board.categories.index(
      connection,
      {
        body: { sort_field: "sort_order", sort_order: "asc" },
      },
    );
    typia.assert(ascResult);
    for (let i = 1; i < ascResult.data.length; ++i) {
      TestValidator.predicate("sort_order 오름차순")(
        ascResult.data[i].sort_order >= ascResult.data[i - 1].sort_order,
      );
    }
  }

  // 5. 전체 비활성 케이스 (is_active false만 있는 경우)
  if (
    baseResult.data.length > 0 &&
    baseResult.data.every((cat) => !cat.is_active)
  ) {
    baseResult.data.forEach((cat) =>
      TestValidator.equals("is_active false")(cat.is_active)(false),
    );
  }

  // 6. 반환 객체 내 불필요 필드 미포함 검증(typia.assert에서 이미 검증됨)
  baseResult.data.forEach((cat) => typia.assert(cat));
}

