/**
 * Test paginated, filterable user profile listing in the discussion board.
 *
 * This test validates the discussion_board user profile listing API for correct
 * behavior under pagination, filtering, and searching options. By creating
 * multiple distinct user profiles, we verify that:
 *
 * - Display_name, email, and is_active filters return only relevant user profiles
 * - Pagination (limit and page) is correctly enforced
 * - Empty results appear for impossible filters or out-of-range pages
 *
 * Test steps:
 *
 * 1. Create several user profiles (with different display_name, email, and
 *    is_active combinations)
 * 2. Search by display_name substring and expect only matches
 * 3. Search by unique email and match exactly one
 * 4. Filter by is_active (true/false) and check only correct is_active values
 *    returned
 * 5. Paginate using limit & page, check record count and pagination metadata
 * 6. Search with non-existent display_name, expect an empty list
 * 7. Access an out-of-range page, expect empty results
 */
export async function test_api_discussion_board_test_list_user_profiles_with_pagination_and_search(
  connection: api.IConnection,
) {
  // 1. Create multiple user profiles with distinct attributes
  const profiles = await Promise.all([
    api.functional.admin.discussion_board.userProfiles.create(connection, {
      body: {
        display_name: "Alice Wonderland",
        email: typia.random<string & tags.Format<"email">>(),
        is_active: true,
      },
    }),
    api.functional.admin.discussion_board.userProfiles.create(connection, {
      body: {
        display_name: "Bob Builder",
        email: typia.random<string & tags.Format<"email">>(),
        is_active: false,
      },
    }),
    api.functional.admin.discussion_board.userProfiles.create(connection, {
      body: {
        display_name: "Charlie Chaplin",
        email: typia.random<string & tags.Format<"email">>(),
        is_active: true,
      },
    }),
    api.functional.admin.discussion_board.userProfiles.create(connection, {
      body: {
        display_name: "Alice Springs",
        email: typia.random<string & tags.Format<"email">>(),
        is_active: false,
      },
    }),
  ]);
  profiles.forEach(typia.assert);

  // 2. Search by display_name substring ("Alice")
  const pageAlice = await api.functional.discussion_board.userProfiles.index(
    connection,
    {
      body: {
        display_name: "Alice",
      },
    },
  );
  typia.assert(pageAlice);
  TestValidator.predicate("all results have display_name containing 'Alice'")(
    pageAlice.data.every((p) => p.display_name.includes("Alice")),
  );

  // 3. Search by unique email address
  const target = profiles[2];
  const pageEmail = await api.functional.discussion_board.userProfiles.index(
    connection,
    {
      body: {
        email: target.email,
      },
    },
  );
  typia.assert(pageEmail);
  TestValidator.equals("unique email result count")(pageEmail.data.length)(1);
  TestValidator.equals("email match")(pageEmail.data[0].email)(target.email);

  // 4. Filter all active profiles
  const pageActive = await api.functional.discussion_board.userProfiles.index(
    connection,
    {
      body: {
        is_active: true,
      },
    },
  );
  typia.assert(pageActive);
  TestValidator.predicate("all are active")(
    pageActive.data.every((p) => p.is_active),
  );

  // 5. Filter all inactive profiles
  const pageInactive = await api.functional.discussion_board.userProfiles.index(
    connection,
    {
      body: {
        is_active: false,
      },
    },
  );
  typia.assert(pageInactive);
  TestValidator.predicate("all are inactive")(
    pageInactive.data.every((p) => !p.is_active),
  );

  // 6. Pagination: limit=2, page=1 and page=2
  const page1 = await api.functional.discussion_board.userProfiles.index(
    connection,
    {
      body: { limit: 2, page: 1 },
    },
  );
  typia.assert(page1);
  TestValidator.equals("page 1 data count")(page1.data.length)(2);
  TestValidator.equals("page 1 pagination.current")(page1.pagination.current)(
    1,
  );
  TestValidator.equals("page 1 limit")(page1.pagination.limit)(2);

  const page2 = await api.functional.discussion_board.userProfiles.index(
    connection,
    {
      body: { limit: 2, page: 2 },
    },
  );
  typia.assert(page2);
  TestValidator.equals("page 2 data count")(page2.data.length)(2);
  TestValidator.equals("page 2 pagination.current")(page2.pagination.current)(
    2,
  );

  // 7. Search for a non-existent display_name
  const pageNone = await api.functional.discussion_board.userProfiles.index(
    connection,
    {
      body: {
        display_name: "NO_MATCH_RESULT_EXPECTED",
      },
    },
  );
  typia.assert(pageNone);
  TestValidator.equals("no results on keyword miss")(pageNone.data.length)(0);

  // 8. Request a page number well beyond available data
  const pageTooFar = await api.functional.discussion_board.userProfiles.index(
    connection,
    {
      body: { limit: 1, page: 100 },
    },
  );
  typia.assert(pageTooFar);
  TestValidator.equals("empty result far page")(pageTooFar.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardCategoryPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategoryPermission";

/**
 * Update selected boolean permission fields within a category permission
 * (admin-only) and validate that only those fields are changed.
 *
 * Business context:
 *
 * - Category-based permissions in a discussion board control role-based UI access
 *   and user interaction. Updates to these permissions must be strictly scoped
 *   and auditable to avoid accidental privilege escalation or data leaks.
 * - Explicitly tests that founded permission entries can be updated for specific
 *   boolean fields (e.g., can_reply, can_like) without changing unrelated
 *   fields or unauthorized columns.
 * - Tests the atomicity and auditability of such changes for RBAC safety.
 *
 * **Test steps:**
 *
 * 1. Create a new discussion board category (admin only)
 * 2. Create a category permission entry for role "member" in this category, with
 *    explicit permission booleans
 * 3. Update only can_reply=false and can_like=true via the update endpoint
 * 4. Verify only these fields changed, all other permission attributes remain
 *    identical
 * 5. Check that audit fields (created_at) remain, and updated_at is correct
 * 6. Assert API type safety and business-level invariants throughout
 */
export async function test_api_admin_discussion_board_categoryPermissions_test_update_category_permission_with_valid_fields(
  connection: api.IConnection,
) {
  // 1. Create a discussion board category
  const categoryInput: IDiscussionBoardCategory.ICreate = {
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph()(2),
    description: RandomGenerator.paragraph()(1),
    sort_order: typia.random<number & tags.Type<"int32">>(),
    is_active: true,
  };
  const category =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: categoryInput,
    });
  typia.assert(category);

  // 2. Create a permission for this category as baseline
  const permInput: IDiscussionBoardCategoryPermission.ICreate = {
    category_id: category.id,
    role_name: "member",
    can_view: true,
    can_create_topic: true,
    can_reply: true,
    can_like: false,
    can_report: false,
  };
  const permission =
    await api.functional.admin.discussion_board.categoryPermissions.create(
      connection,
      { body: permInput },
    );
  typia.assert(permission);

  // 3. Update permission: change only can_reply and can_like
  const updateInput: IDiscussionBoardCategoryPermission.IUpdate = {
    can_reply: false,
    can_like: true,
  };
  const updated =
    await api.functional.admin.discussion_board.categoryPermissions.update(
      connection,
      { id: permission.id, body: updateInput },
    );
  typia.assert(updated);

  // 4. Validate atomicity: only selected fields changed
  TestValidator.equals("id unchanged")(updated.id)(permission.id);
  TestValidator.equals("category_id unchanged")(updated.category_id)(
    permission.category_id,
  );
  TestValidator.equals("role_name unchanged")(updated.role_name)(
    permission.role_name,
  );
  TestValidator.equals("can_view unchanged")(updated.can_view)(
    permission.can_view,
  );
  TestValidator.equals("can_create_topic unchanged")(updated.can_create_topic)(
    permission.can_create_topic,
  );
  TestValidator.notEquals("can_reply should change")(updated.can_reply)(
    permission.can_reply,
  );
  TestValidator.notEquals("can_like should change")(updated.can_like)(
    permission.can_like,
  );
  TestValidator.equals("can_report unchanged")(updated.can_report)(
    permission.can_report,
  );
  TestValidator.equals("can_reply updated")(updated.can_reply)(
    updateInput.can_reply,
  );
  TestValidator.equals("can_like updated")(updated.can_like)(
    updateInput.can_like,
  );
  // 5. Confirm audit trail
  TestValidator.equals("created_at is preserved")(updated.created_at)(
    permission.created_at,
  );
  TestValidator.predicate("updated_at >= created_at")(
    new Date(updated.updated_at).getTime() >=
      new Date(updated.created_at).getTime(),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardUserNotificationSettings } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserNotificationSettings";

/**
 * Validate updating a member's notification settings by ID.
 *
 * This test ensures a board member can change notification preferences, such as
 * toggling off email notifications or modifying mute_types. It covers the
 * following workflow:
 *
 * 1. Create a user profile via the admin API with random but valid email and
 *    display name.
 * 2. Make the user a board member.
 * 3. As the member, create initial notification settings (all notifications on, no
 *    mutes).
 * 4. Update the member's notification settings: toggle off email notifications,
 *    enable push, and set one or more mute_types.
 * 5. Assert that the update API call succeeds and returns the modified record.
 * 6. (Optional) If possible, retrieve the updated settings to confirm persistence
 *    and correctness of updated values.
 *
 * Business context: Ensures members have full control over their notification
 * channels and mute-able event types, and changes are persisted and correctly
 * reflected in their settings record.
 */
export async function test_api_my_discussion_board_userNotificationSettings_test_update_notification_settings_success(
  connection: api.IConnection,
) {
  // 1. Admin creates a user profile
  const email = typia.random<string & tags.Format<"email">>();
  const displayName = RandomGenerator.name();
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email,
          display_name: displayName,
          is_active: true,
        } satisfies api.IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(userProfile);

  // 2. Assign member status for notification operations
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userProfile.id,
        joined_at: new Date().toISOString(),
      } satisfies api.IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 3. As the member, create notification settings with all notifications on and no mutes
  const notificationSettings =
    await api.functional.my.discussion_board.userNotificationSettings.create(
      connection,
      {
        body: {
          user_id: member.id,
          receive_email_notifications: true,
          receive_push_notifications: true,
          mute_types: null,
        } satisfies api.IDiscussionBoardUserNotificationSettings.ICreate,
      },
    );
  typia.assert(notificationSettings);

  // 4. Update notification settings: toggle off email notifications, set mute_types
  const update: api.IDiscussionBoardUserNotificationSettings.IUpdate = {
    receive_email_notifications: false,
    receive_push_notifications: true,
    mute_types: "like,moderation",
  };
  const updatedSettings =
    await api.functional.my.discussion_board.userNotificationSettings.update(
      connection,
      {
        id: notificationSettings.id,
        body: update,
      },
    );
  typia.assert(updatedSettings);

  // 5. Assert the updates are correctly reflected
  TestValidator.equals("receive_email_notifications")(
    updatedSettings.receive_email_notifications,
  )(false);
  TestValidator.equals("receive_push_notifications")(
    updatedSettings.receive_push_notifications,
  )(true);
  TestValidator.equals("mute_types")(updatedSettings.mute_types)(
    "like,moderation",
  );

  // 6. Retrieval after update is not necessary as the update call returns new state.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IPageDiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardAdmins";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates listing, pagination, and filtering for admin assignments in the
 * discussion board.
 *
 * This test verifies that the paginated admin assignment listing endpoint
 * properly handles various filter and pagination parameters:
 *
 * - Only active (non-revoked) assignments (revoked_at == null)
 * - By assigned_by_user_profile_id (who performed the assignment)
 * - By assigned_at date range
 * - Pagination (page and limit)
 *
 * Steps:
 *
 * 1. Create multiple user profiles (for assignment as admins and as assigners).
 * 2. Assign multiple admins to these user profiles by different assigners and
 *    assigned_at timestamps.
 * 3. Optionally revoke (set revoked_at) for some admin assignments.
 * 4. Test listing all assignments; validate correct total and record contents.
 * 5. Filter for only active assignments (revoked_at == null).
 * 6. Filter by assigned_by_user_profile_id with pagination.
 * 7. Filter by assigned_at range to only retrieve expected assignments.
 */
export async function test_api_admin_discussion_board_admins_test_list_admin_assignments_with_pagination_and_filters(
  connection: api.IConnection,
) {
  // 1. Create user profiles for assignment (5 profiles)
  const profiles = await Promise.all(
    ArrayUtil.repeat(5)(
      async () =>
        await api.functional.admin.discussion_board.userProfiles.create(
          connection,
          {
            body: {
              email: typia.random<string & tags.Format<"email">>(),
              display_name: RandomGenerator.name(),
              is_active: true,
            } satisfies IDiscussionBoardUserProfile.ICreate,
          },
        ),
    ),
  );
  profiles.forEach(typia.assert);

  // Also create an assigning admin
  const assigner =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(assigner);

  // 2. Assign admins to all profiles, spreading assigned_at timestamps, by same assigner
  const now = new Date();
  const assignments = await Promise.all(
    profiles.map((profile, idx) =>
      api.functional.admin.discussion_board.admins.create(connection, {
        body: {
          discussion_board_user_profile_id: profile.id,
          assigned_by_user_profile_id: assigner.id,
          assigned_at: new Date(
            now.getTime() - (5 - idx) * 60 * 60 * 1000,
          ).toISOString(),
        } satisfies IDiscussionBoardAdmin.ICreate,
      }),
    ),
  );
  assignments.forEach(typia.assert);

  // 3. Revoke some assignments (e.g., even-indexed assignments are active, odds are revoked)
  const revoked_at_value = new Date(
    now.getTime() + 60 * 60 * 1000,
  ).toISOString();
  const updatedAssignments = await Promise.all(
    assignments.map((assignment, idx) =>
      idx % 2 === 1
        ? api.functional.admin.discussion_board.admins.update(connection, {
            id: assignment.id,
            body: {
              discussion_board_user_profile_id:
                assignment.discussion_board_user_profile_id,
              assigned_at: assignment.assigned_at,
              revoked_at: revoked_at_value,
              assigned_by_user_profile_id:
                assignment.assigned_by_user_profile_id,
            } satisfies IDiscussionBoardAdmin.IUpdate,
          })
        : Promise.resolve(assignment),
    ),
  );
  updatedAssignments.forEach(typia.assert);

  // 4. List all admin assignments, page 1, limit large enough
  let page = await api.functional.admin.discussion_board.admins.index(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
      } satisfies IPageDiscussionBoardAdmins.IRequest,
    },
  );
  typia.assert(page);
  TestValidator.equals("returns all assignments")(page.data.length)(
    assignments.length,
  );

  // 5. Filter only active (revoked_at === null)
  page = await api.functional.admin.discussion_board.admins.index(connection, {
    body: {
      page: 1,
      limit: 10,
      revoked_at: null,
    } satisfies IPageDiscussionBoardAdmins.IRequest,
  });
  typia.assert(page);
  TestValidator.predicate("only active assignments")(
    page.data.every((a) => a.revoked_at === null),
  );
  TestValidator.equals("active count matches")(page.data.length)(
    assignments.filter((_, idx) => idx % 2 === 0).length,
  );

  // 6. Filter by assigned_by_user_profile_id with pagination
  page = await api.functional.admin.discussion_board.admins.index(connection, {
    body: {
      assigned_by_user_profile_id: assigner.id,
      page: 1,
      limit: 2,
    } satisfies IPageDiscussionBoardAdmins.IRequest,
  });
  typia.assert(page);
  TestValidator.predicate("all returned have correct assigner")(
    page.data.every((a) => a.assigned_by_user_profile_id === assigner.id),
  );

  // 7. Filter by assigned_at range (narrow to last two assignments)
  const fromDate = assignments[assignments.length - 2].assigned_at;
  const toDate = assignments[assignments.length - 1].assigned_at;
  page = await api.functional.admin.discussion_board.admins.index(connection, {
    body: {
      assigned_at_from: fromDate,
      assigned_at_to: toDate,
      page: 1,
      limit: 10,
    } satisfies IPageDiscussionBoardAdmins.IRequest,
  });
  typia.assert(page);
  TestValidator.equals("range matches")(page.data.length)(2);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAuditTrail } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuditTrail";
import type { IPageIDiscussionBoardAuditTrail } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAuditTrail";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates the audit trail paginated query with filters.
 *
 * This test ensures that the audit trail endpoint returns correctly filtered
 * and paginated results based on actor_id, action_type, target_table, and date
 * filtering. It first creates several audit trail records with controlled actor
 * IDs, action types, target tables, and timestamps. It then submits a filtered
 * query for a subset of those records. The test also checks that when using
 * search filters with no matching results, the API returns an empty page.
 * Pagination is verified by creating sufficient records and requesting a page
 * with a custom limit.
 *
 * Steps:
 *
 * 1. Create multiple audit trail records with varying actor_ids, action_types,
 *    target_tables, and created_at timestamps, including at least two with the
 *    same actor_id, action_type, and target_table and within a date range.
 * 2. Query the audit trail endpoint with filters for actor_id, action_type,
 *    target_table, and a date range containing only the two records above.
 *    Assert only those two are returned.
 * 3. Query with a date range and actor_id/action_type/target_table combination
 *    that matches no records; assert an empty result.
 * 4. Query all records with a limit less than the total; assert that pagination
 *    metadata and results conform to the requested limit.
 */
export async function test_api_admin_discussion_board_auditTrails_test_list_audit_trails_with_date_and_actor_filters(
  connection: api.IConnection,
) {
  // 1. Create multiple audit trail records with known actor_id/action_type/target_table/date
  const known_actor_id = typia.random<string & tags.Format<"uuid">>();
  const unrelated_actor_id = typia.random<string & tags.Format<"uuid">>();
  const action_type = "moderation";
  const target_table = "discussion_board_posts";
  const unrelated_action_type = "delete";
  const unrelated_target_table = "discussion_board_comments";

  // Choose base dates (now, minus 1hr, plus 1hr)
  const now = new Date();
  const date1 = new Date(now.getTime() - 60 * 60 * 1000); // hour ago
  const date2 = new Date(now.getTime() - 30 * 60 * 1000); // 30 min ago
  const date3 = new Date(now.getTime() + 60 * 60 * 1000); // in 1 hr

  // Insert two target records (same actor/action/table in known window)
  const entryA = await api.functional.admin.discussion_board.auditTrails.create(
    connection,
    {
      body: {
        actor_id: known_actor_id,
        action_type,
        target_table,
        target_id: typia.random<string & tags.Format<"uuid">>(),
        details: "entryA-details",
        created_at: date1.toISOString(),
      },
    },
  );
  typia.assert(entryA);

  const entryB = await api.functional.admin.discussion_board.auditTrails.create(
    connection,
    {
      body: {
        actor_id: known_actor_id,
        action_type,
        target_table,
        target_id: typia.random<string & tags.Format<"uuid">>(),
        details: "entryB-details",
        created_at: date2.toISOString(),
      },
    },
  );
  typia.assert(entryB);

  // Insert unrelated records (different actor, type, table, date)
  const unrelated1 =
    await api.functional.admin.discussion_board.auditTrails.create(connection, {
      body: {
        actor_id: unrelated_actor_id,
        action_type: unrelated_action_type,
        target_table: unrelated_target_table,
        target_id: typia.random<string & tags.Format<"uuid">>(),
        details: "unrelated1",
        created_at: date3.toISOString(),
      },
    });
  typia.assert(unrelated1);

  // 2. Filtered query - should return only entryA/entryB
  const from = new Date(date1.getTime() - 1000); // just before date1
  const to = new Date(date2.getTime() + 1000); // just after date2
  const filtered =
    await api.functional.admin.discussion_board.auditTrails.index(connection, {
      body: {
        actor_id: known_actor_id,
        action_type,
        target_table,
        created_at_start: from.toISOString(),
        created_at_end: to.toISOString(),
      },
    });
  typia.assert(filtered);
  // Assert both records are present and only two returned
  TestValidator.equals("filtered count")(filtered.data.length)(2);
  const result_ids = filtered.data.map((r) => r.id).sort();
  const expected_ids = [entryA.id, entryB.id].sort();
  TestValidator.equals("ids match")(result_ids)(expected_ids);
  filtered.data.forEach((rec) => {
    TestValidator.equals("actor_id")(rec.actor_id)(known_actor_id);
    TestValidator.equals("action_type")(rec.action_type)(action_type);
    TestValidator.equals("target_table")(rec.target_table)(target_table);
    const created = new Date(rec.created_at);
    TestValidator.predicate("created_at in window")(
      created >= from && created <= to,
    );
  });

  // 3. Query with non-matching filters (empty expected)
  const emptyRes =
    await api.functional.admin.discussion_board.auditTrails.index(connection, {
      body: {
        actor_id: unrelated_actor_id,
        action_type: "nonsense_action_type",
        target_table: "nonexistent_table",
        created_at_start: now.toISOString(),
        created_at_end: new Date(now.getTime() + 5000).toISOString(),
      },
    });
  typia.assert(emptyRes);
  TestValidator.equals("empty data")(emptyRes.data.length)(0);

  // 4. Pagination: create additional so count > 2
  const pagedEntry =
    await api.functional.admin.discussion_board.auditTrails.create(connection, {
      body: {
        actor_id: typia.random<string & tags.Format<"uuid">>(),
        action_type,
        target_table,
        target_id: typia.random<string & tags.Format<"uuid">>(),
        details: "paged-record",
        created_at: new Date(now.getTime() + 2000).toISOString(),
      },
    });
  typia.assert(pagedEntry);

  // Query first page with limit = 2
  const pageRes = await api.functional.admin.discussion_board.auditTrails.index(
    connection,
    {
      body: {
        action_type,
        target_table,
        created_at_start: date1.toISOString(),
        limit: 2,
      },
    },
  );
  typia.assert(pageRes);
  TestValidator.predicate("pagination meta")(pageRes.pagination.limit === 2);
  TestValidator.predicate("page size matches limit")(pageRes.data.length <= 2);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostAttachment";
import type { IPageDiscussionBoardPostAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardPostAttachment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate filtering/search for discussion board post attachments using file
 * name substring, is_deleted status, and uploader id filters.
 *
 * Business context:
 *
 * - Attachments are associated with posts, and each is uploaded by a member.
 * - Admin creates a user profile and assigns as a member first (dependencies).
 * - We create two posts, then upload several attachments with varied properties
 *   (file_name, mime_type, is_deleted).
 *
 * Steps:
 *
 * 1. Admin creates user profile.
 * 2. Admin assigns user profile as board member.
 * 3. Member creates two distinct posts.
 * 4. Member uploads several attachments across both posts, varying file_name and
 *    mime_type values; simulate a 'deleted' file in-memory for filter testing.
 * 5. Test file_name filtering: Query using file_name__contains substring, validate
 *    only matching attachments in response.
 * 6. Test is_deleted filtering: Query for is_deleted true and false, validate
 *    segregation.
 * 7. Test uploader_member_id filtering: Query by uploader id, expect only
 *    attachments uploaded by this member.
 * 8. Optionally, apply multiple filters in one request (intersection).
 * 9. Validate API returns only correct/expected records for each filter scenario.
 */
export async function test_api_discussion_board_test_list_post_attachments_with_filters(
  connection: api.IConnection,
) {
  // 1. Admin creates user profile
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        },
      },
    );
  typia.assert(userProfile);

  // 2. Admin assigns user as member
  const now = new Date().toISOString();
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userProfile.id,
        joined_at: now,
      },
    },
  );
  typia.assert(member);

  // 3. Member creates two posts under random topic ids
  const topicId1 = typia.random<string & tags.Format<"uuid">>();
  const topicId2 = typia.random<string & tags.Format<"uuid">>();

  const post1 = await api.functional.my.discussion_board.posts.create(
    connection,
    {
      body: {
        discussion_board_topic_id: topicId1,
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      },
    },
  );
  typia.assert(post1);

  const post2 = await api.functional.my.discussion_board.posts.create(
    connection,
    {
      body: {
        discussion_board_topic_id: topicId2,
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      },
    },
  );
  typia.assert(post2);

  // 4. Member uploads attachments with varied file_name and mime_type
  const attachments = [
    // post1, normal attachment ("report1.pdf", application/pdf)
    await api.functional.my.discussion_board.postAttachments.create(
      connection,
      {
        body: {
          discussion_board_post_id: post1.id,
          file_uri: `https://cdn.example.com/files/report1.pdf`,
          file_name: "report1.pdf",
          file_size: 256000,
          mime_type: "application/pdf",
        },
      },
    ),
    // post1, deleted attachment ("to_delete.png", image/png)
    await api.functional.my.discussion_board.postAttachments.create(
      connection,
      {
        body: {
          discussion_board_post_id: post1.id,
          file_uri: `https://cdn.example.com/files/to_delete.png`,
          file_name: "to_delete.png",
          file_size: 400012,
          mime_type: "image/png",
        },
      },
    ),
    // post2, normal docx ("summary.docx", application/vnd.openxmlformats-officedocument.wordprocessingml.document)
    await api.functional.my.discussion_board.postAttachments.create(
      connection,
      {
        body: {
          discussion_board_post_id: post2.id,
          file_uri: `https://cdn.example.com/files/summary.docx`,
          file_name: "summary.docx",
          file_size: 12004,
          mime_type:
            "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        },
      },
    ),
    // post2, normal image ("photo2.png", image/png)
    await api.functional.my.discussion_board.postAttachments.create(
      connection,
      {
        body: {
          discussion_board_post_id: post2.id,
          file_uri: `https://cdn.example.com/files/photo2.png`,
          file_name: "photo2.png",
          file_size: 178900,
          mime_type: "image/png",
        },
      },
    ),
  ];
  attachments.forEach(typia.assert);

  // Simulate soft-deleting the second attachment (cannot call API, so patch the object locally)
  attachments[1].is_deleted = true;

  // 5. Filter: file_name__contains substring ("report"); expect only report1.pdf
  {
    const resp = await api.functional.discussion_board.postAttachments.index(
      connection,
      {
        body: {
          file_name__contains: "report",
        },
      },
    );
    typia.assert(resp);
    TestValidator.equals("filter by file_name__contains")(
      resp.data.length === 1 && resp.data[0].file_name === "report1.pdf",
    )(true);
  }

  // 6. Filter: is_deleted true – should return only "to_delete.png"
  {
    const resp = await api.functional.discussion_board.postAttachments.index(
      connection,
      {
        body: {
          is_deleted: true,
        },
      },
    );
    typia.assert(resp);
    TestValidator.predicate("filter by is_deleted true")(
      resp.data.every((a) => a.is_deleted),
    );
  }
  // 6b. Filter: is_deleted false – should exclude "to_delete.png" (soft-deleted)
  {
    const resp = await api.functional.discussion_board.postAttachments.index(
      connection,
      {
        body: {
          is_deleted: false,
        },
      },
    );
    typia.assert(resp);
    TestValidator.predicate("filter by is_deleted false")(
      resp.data.every((a) => !a.is_deleted),
    );
  }
  // 7. Filter: uploader_member_id – expect all attachments match this member (all uploads by same user)
  {
    const resp = await api.functional.discussion_board.postAttachments.index(
      connection,
      {
        body: {
          uploader_member_id: member.id,
        },
      },
    );
    typia.assert(resp);
    TestValidator.predicate("filter by uploader_member_id")(
      resp.data.every((a) => a.uploader_member_id === member.id),
    );
  }
  // 8. Filter: intersection: post2, image/png
  {
    const resp = await api.functional.discussion_board.postAttachments.index(
      connection,
      {
        body: {
          discussion_board_post_id: post2.id,
          mime_type: "image/png",
        },
      },
    );
    typia.assert(resp);
    TestValidator.equals("intersection filter: post2 & image/png")(
      resp.data.length === 1 && resp.data[0].file_name === "photo2.png",
    )(true);
  }
  // 9. Pagination: limit 2
  {
    const resp = await api.functional.discussion_board.postAttachments.index(
      connection,
      {
        body: {
          limit: 2,
        },
      },
    );
    typia.assert(resp);
    TestValidator.equals("pagination limit 2")(resp.data.length)(2);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostAttachment";

/**
 * Validate that a discussion board member cannot update an attachment uploaded by another member.
 *
 * This test simulates the following scenario:
 * 1. Create two user profiles (User A and User B) as board members.
 * 2. User A uploads an attachment to a post.
 * 3. User B (who is also a member, but not the attachment uploader) attempts to update the attachment's metadata.
 * 4. The API should respond with an authorization error, preventing User B from updating the attachment not uploaded by them.
 *
 * This ensures that only uploaders can modify their own discussion board attachments, enforcing RBAC at the service/controller level.
 */
export async function test_api_my_discussion_board_postAttachments_test_member_cannot_update_others_attachment(
  connection: api.IConnection,
) {
  // 1. Create two distinct user profiles (admin action)
  const userAEmail = typia.random<string & tags.Format<"email">>();
  const userBEmail = typia.random<string & tags.Format<"email">>();
  const userA = await api.functional.admin.discussion_board.userProfiles.create(connection, {
    body: {
      email: userAEmail,
      display_name: RandomGenerator.name(),
      is_active: true,
    } satisfies IDiscussionBoardUserProfile.ICreate,
  });
  typia.assert(userA);
  const userB = await api.functional.admin.discussion_board.userProfiles.create(connection, {
    body: {
      email: userBEmail,
      display_name: RandomGenerator.name(),
      is_active: true,
    } satisfies IDiscussionBoardUserProfile.ICreate,
  });
  typia.assert(userB);

  // 2. Assign both as discussion board members (admin action)
  const joinedAt = new Date().toISOString();
  const memberA = await api.functional.admin.discussion_board.members.create(connection, {
    body: {
      discussion_board_user_profile_id: userA.id,
      joined_at: joinedAt,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberA);
  const memberB = await api.functional.admin.discussion_board.members.create(connection, {
    body: {
      discussion_board_user_profile_id: userB.id,
      joined_at: joinedAt,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberB);

  // 3. User A (as member) creates a post and uploads an attachment
  // -- Simulate User A session: assume User A is now authenticated
  // NOTE: For this test, we assume the testing framework (or connection) supports simulating logins for userA/userB for /my/* requests
  // Create the post (User A)
  (connection.headers ??= {}).["X-Mock-User-Id"] = userA.id; // Session spoof for test runner
  const discussion_board_topic_id = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.my.discussion_board.posts.create(connection, {
