import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopic";
import type { IPageIDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardTopic";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing, searching, and filtering topics with pagination support on the
 * discussion board.
 *
 * This end-to-end test covers the following flow:
 *
 * 1. Create two categories for topic association (admin).
 * 2. Create two user profiles and assign them as discussion board members (admin).
 * 3. As each member, create multiple topics with varying categories, titles,
 *    statuses, and pinned/closed states.
 * 4. Use the /discussion_board/topics endpoint with various filter criteria:
 *
 *    - No filters (default list)
 *    - Keyword search on title/description
 *    - Category filtering
 *    - Status filtering
 *    - Pinned and closed boolean filters
 *    - Pagination controls (limit/page)
 *    - Combined filters
 *    - Filtering to ensure empty result
 *    - Invalid filter scenarios for error handling
 * 5. For each search, validate:
 *
 *    - Returned topics match the filter criteria
 *    - Pagination metadata is correct
 *    - Structure matches DTO (typia.assert)
 *    - There are no extra fields
 *    - Empty array for non-matching filters
 *    - Errors for invalid input parameters
 */
export async function test_api_discussion_board_test_list_topics_with_pagination_and_search_filters(
  connection: api.IConnection,
) {
  // 1. Create two categories
  const category1 =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: `cat${RandomGenerator.alphaNumeric(4)}`,
        name: `CategoryOne`,
        description: "First category for testing",
        sort_order: 1,
        is_active: true,
      },
    });
  typia.assert(category1);
  const category2 =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: `cat${RandomGenerator.alphaNumeric(4)}`,
        name: `CategoryTwo`,
        description: "Second category for testing",
        sort_order: 2,
        is_active: true,
      },
    });
  typia.assert(category2);

  // 2. Create user profiles
  const profile1 =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        },
      },
    );
  typia.assert(profile1);
  const profile2 =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        },
      },
    );
  typia.assert(profile2);

  // 3. Assign members
  const now = new Date().toISOString();
  const member1 = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: profile1.id,
        joined_at: now,
      },
    },
  );
  typia.assert(member1);
  const member2 = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: profile2.id,
        joined_at: now,
      },
    },
  );
  typia.assert(member2);

  // 4. Create multiple topics with varied attributes
  const topicInputs = [
    {
      category: category1,
      title: "Alpha Open",
      desc: "Alpha open topic for category one.",
      status: "open",
      pinned_at: null,
      closed_at: null,
    },
    {
      category: category1,
      title: "Beta Closed",
      desc: "Beta closed topic for category one.",
      status: "closed",
      pinned_at: null,
      closed_at: now,
    },
    {
      category: category2,
      title: "Searchable",
      desc: "A searchable unique string appears here.",
      status: "pinned",
      pinned_at: now,
      closed_at: null,
    },
    {
      category: category2,
      title: "Misc open",
      desc: "Miscellaneous open topic for testing.",
      status: "open",
      pinned_at: null,
      closed_at: null,
    },
  ];

  // Sequentially create topics as different members (simulate login/role context)
  const topics: IDiscussionBoardTopic[] = [];
  for (let i = 0; i < topicInputs.length; ++i) {
    const input = topicInputs[i];
    // Assume runner sets authenticated user/member context before each topic creation
    const topic = await api.functional.my.discussion_board.topics.create(
      connection,
      {
        body: {
          discussion_board_category_id: input.category.id,
          title: input.title,
          description: input.desc,
          status: input.status,
          pinned_at: input.pinned_at,
          closed_at: input.closed_at,
        },
      },
    );
    typia.assert(topic);
    topics.push(topic);
  }

  // 5A. No filters (should include all topics)
  let res = await api.functional.discussion_board.topics.index(connection, {
    body: {},
  });
  typia.assert(res);
  TestValidator.predicate("All topics present")(res.data.length >= 4);

  // 5B. Keyword search (should match at least one topic)
  res = await api.functional.discussion_board.topics.index(connection, {
    body: { keywords: "Searchable" },
  });
  typia.assert(res);
  TestValidator.equals("Keyword filter for title")(res.data.length)(1);

  // 5C. Category filtering
  res = await api.functional.discussion_board.topics.index(connection, {
    body: { discussion_board_category_id: category1.id },
  });
  typia.assert(res);
  TestValidator.predicate("Category1 only")(
    res.data.every((d) => d.discussion_board_category_id === category1.id),
  );

  // 5D. Status filtering
  res = await api.functional.discussion_board.topics.index(connection, {
    body: { status: "open" },
  });
  typia.assert(res);
  TestValidator.predicate("Status=open")(
    res.data.every((d) => d.status === "open"),
  );

  // 5E. Pinned filter
  res = await api.functional.discussion_board.topics.index(connection, {
    body: { pinned: true },
  });
  typia.assert(res);
  TestValidator.predicate("Only pinned topics")(
    res.data.every((d) => d.pinned_at != null),
  );

  // 5F. Closed filter
  res = await api.functional.discussion_board.topics.index(connection, {
    body: { closed: true },
  });
  typia.assert(res);
  TestValidator.predicate("Only closed topics")(
    res.data.every((d) => d.closed_at != null),
  );

  // 5G. Pagination (limit and page)
  res = await api.functional.discussion_board.topics.index(connection, {
    body: { limit: 2, page: 2 },
  });
  typia.assert(res);
  TestValidator.equals("Limit = 2")(res.pagination.limit)(2);
  TestValidator.equals("Page = 2")(res.pagination.current)(2);

  // 5H. Combination filter: keyword + status
  res = await api.functional.discussion_board.topics.index(connection, {
    body: { keywords: "open", status: "open" },
  });
  typia.assert(res);
  TestValidator.predicate("Keyword and status filter")(
    res.data.every((d) => d.status === "open" && d.title.includes("open")),
  );

  // 5I. Filter for empty Data (non-existent category)
  res = await api.functional.discussion_board.topics.index(connection, {
    body: {
      discussion_board_category_id: typia.random<
        string & tags.Format<"uuid">
      >(),
    },
  });
  typia.assert(res);
  TestValidator.equals("Empty when category does not exist")(res.data.length)(
    0,
  );

  // 5J. Error handling for invalid filters
  await TestValidator.error("Invalid page value")(async () => {
    // @ts-expect-error
    await api.functional.discussion_board.topics.index(connection, {
      body: { page: "bad" as any },
    });
  });
  await TestValidator.error("Invalid limit value")(async () => {
    // @ts-expect-error
    await api.functional.discussion_board.topics.index(connection, {
      body: { limit: "bad" as any },
    });
  });
  await TestValidator.error("Nonsense status value")(async () => {
    await api.functional.discussion_board.topics.index(connection, {
      body: { status: "__not_a_status__" },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopic";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";

/**
 * Validate update attempts with invalid data for a discussion board post are
 * rejected and do not alter content.
 *
 * This test ensures that the update endpoint for discussion board posts
 * correctly rejects update requests when provided invalid input, such as
 * supplying only immutable fields, sending unrecognized properties, or omitting
 * all updatable fields. The test checks that a validation error is thrown and
 * the original post data remains unchanged after each failed attempt.
 *
 * Steps:
 *
 * 1. Admin creates a user profile for the member.
 * 2. Admin assigns the profile as a discussion board member.
 * 3. Admin registers a category for the test.
 * 4. The member creates a topic in this category.
 * 5. The member posts a message in this topic.
 * 6. Various invalid updates are attempted on the post using
 *    /my/discussion_board/posts/{id} (PUT):
 *
 *    - A) Input contains only immutable fields (should fail)
 *    - B) Input has unrecognized fields (should fail)
 *    - C) Body is an empty object (should fail) For each, it is verified that a
 *         validation error is thrown, and the state of the post is unchanged.
 */
export async function test_api_my_discussion_board_posts_test_update_post_with_invalid_input(
  connection: api.IConnection,
) {
  // 1. Admin creates a user profile
  const profile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
          // registered_at is optional
        },
      },
    );
  typia.assert(profile);

  // 2. Admin assigns as discussion board member
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: profile.id,
        joined_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(member);

  // 3. Admin creates a category
  const category =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(6),
        name: RandomGenerator.alphabets(8),
        sort_order: 1,
        is_active: true,
        // description can be omitted
      },
    });
  typia.assert(category);

  // 4. Member creates a topic
  const topic = await api.functional.my.discussion_board.topics.create(
    connection,
    {
      body: {
        discussion_board_category_id: category.id,
        title: RandomGenerator.paragraph()(8),
        description: RandomGenerator.content()(2)(2),
        status: "open",
        // pinned_at and closed_at are optional
      },
    },
  );
  typia.assert(topic);

  // 5. Member creates a post
  const post = await api.functional.my.discussion_board.posts.create(
    connection,
    {
      body: {
        discussion_board_topic_id: topic.id,
        title: RandomGenerator.alphabets(12),
        body: RandomGenerator.content()(2)(4),
      },
    },
  );
  typia.assert(post);

  // 6. Attempt update with only immutable fields - should fail
  TestValidator.error("update only immutable fields should fail")(
    async () =>
      await api.functional.my.discussion_board.posts.update(connection, {
        id: post.id,
        // IDiscussionBoardPost.IUpdate: only accepts title/body/is_deleted
        // Supply only immutable fields in body (should be rejected)
        body: {
          // @ts-expect-error: not in schema
          id: post.id,
          // @ts-expect-error: not in schema
          author_member_id: post.author_member_id,
          // @ts-expect-error: not in schema
          discussion_board_topic_id: post.discussion_board_topic_id,
        } as any,
      }),
  );

  // 7. Attempt update with extraneous/unrecognized fields - should fail
  TestValidator.error("update with unknown fields should fail")(
    async () =>
      await api.functional.my.discussion_board.posts.update(connection, {
        id: post.id,
        // Supply recognized + unrecognized fields
        body: {
          // valid field
          title: RandomGenerator.alphabets(6),
          // extraneous unrecognized
          not_a_field: "should_fail",
        } as any,
      }),
  );

  // 8. Attempt update with empty body - should also fail
  TestValidator.error("update with empty body should fail")(
    async () =>
      await api.functional.my.discussion_board.posts.update(connection, {
        id: post.id,
        body: {},
      }),
  );

  // After each failed update, confirm post fields remain unmodified by re-retrieving the post if such endpoint is available
  // (No post read endpoint provided, so cannot re-check via SDK)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopic";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for discussion board posts listing with topic and author filters.
 *
 * This test verifies that the listing endpoint correctly filters posts by both
 * topic ID and author_member_id. The process ensures that only posts created
 * under a specific topic by a specific author are returned.
 *
 * Steps:
 *
 * 1. Create 3 user profiles using the admin endpoint.
 * 2. Assign all user profiles as members using the admin endpoint.
 * 3. Create 2 categories.
 * 4. Each member creates a topic in a category.
 * 5. All members create posts in all topics (generating a uniform post matrix).
 * 6. Add extra posts by one member under one topic for robust filter testing.
 * 7. Call the post list endpoint with discussion_board_topic_id and
 *    author_member_id as filters.
 * 8. Assert that every result has both the filtered topic and author values, and
 *    that only expected posts are present.
 */
export async function test_api_discussion_board_test_list_posts_with_filters_on_topic_id_and_author(
  connection: api.IConnection,
) {
  // 1. Create 3 user profiles
  const profiles = await Promise.all([
    api.functional.admin.discussion_board.userProfiles.create(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        display_name: RandomGenerator.name(),
        is_active: true,
      },
    }),
    api.functional.admin.discussion_board.userProfiles.create(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        display_name: RandomGenerator.name(),
        is_active: true,
      },
    }),
    api.functional.admin.discussion_board.userProfiles.create(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        display_name: RandomGenerator.name(),
        is_active: true,
      },
    }),
  ]);
  profiles.forEach(typia.assert);

  // 2. Assign each profile as board member
  const now = new Date().toISOString();
  const members = await Promise.all(
    profiles.map((profile) =>
      api.functional.admin.discussion_board.members.create(connection, {
        body: {
          discussion_board_user_profile_id: profile.id,
          joined_at: now,
        },
      }),
    ),
  );
  members.forEach(typia.assert);

  // 3. Create 2 board categories
  const categories = await Promise.all([
    api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.paragraph()(2),
        description: RandomGenerator.paragraph()(),
        sort_order: 1,
        is_active: true,
      },
    }),
    api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.paragraph()(2),
        description: RandomGenerator.paragraph()(),
        sort_order: 2,
        is_active: true,
      },
    }),
  ]);
  categories.forEach(typia.assert);

  // 4. Each member creates a topic (round-robin distribute categories)
  const topics = await Promise.all(
    members.map((member, i) =>
      api.functional.my.discussion_board.topics.create(connection, {
        body: {
          discussion_board_category_id: categories[i % categories.length].id,
          title: RandomGenerator.paragraph()(),
          description: RandomGenerator.content()()(),
          status: "open",
        },
      }),
    ),
  );
  topics.forEach(typia.assert);

  // 5. All members create posts in all topics
  const posts: IDiscussionBoardPost[] = [];
  for (const member of members) {
    for (const topic of topics) {
      // (Auth context is not actually switched per member in this test infra)
      const post = await api.functional.my.discussion_board.posts.create(
        connection,
        {
          body: {
            discussion_board_topic_id: topic.id,
            title: RandomGenerator.paragraph()(),
            body: RandomGenerator.content()()(),
          },
        },
      );
      typia.assert(post);
      posts.push(post);
    }
  }

  // 6. For filter test, pick a topic/member & add further posts for robustness
  const targetTopic = topics[0];
  const targetAuthor = members[1];
  const extraPosts: IDiscussionBoardPost[] = [];
  for (let i = 0; i < 2; ++i) {
    const post = await api.functional.my.discussion_board.posts.create(
      connection,
      {
        body: {
          discussion_board_topic_id: targetTopic.id,
          title: RandomGenerator.paragraph()(),
          body: RandomGenerator.content()()(),
        },
      },
    );
    typia.assert(post);
    extraPosts.push(post);
  }
  // Gather expected post IDs for this author & topic
  const expectedPostIDs = posts
    .filter(
      (p) =>
        p.discussion_board_topic_id === targetTopic.id &&
        p.author_member_id === targetAuthor.id,
    )
    .map((p) => p.id)
    .concat(extraPosts.map((p) => p.id));

  // 7. Query the post list endpoint with combined filters
  const output = await api.functional.discussion_board.posts.index(connection, {
    body: {
      discussion_board_topic_id: targetTopic.id,
      author_member_id: targetAuthor.id,
      page: 1,
      limit: 99,
    },
  });
  typia.assert(output);

  // 8. Validate the filtered posts
  for (const post of output.data) {
    TestValidator.equals("topic filtered")(post.discussion_board_topic_id)(
      targetTopic.id,
    );
    TestValidator.equals("author filtered")(post.author_member_id)(
      targetAuthor.id,
    );
    TestValidator.predicate("id in expected set")(
      expectedPostIDs.includes(post.id),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopic";

/**
 * 멤버가 자신의 토픽을 성공적으로 삭제할 수 있는지 검증합니다.
 *
 * [비즈니스 시나리오 및 과정]
 *
 * 1. 관리자가 유저 프로필을 생성합니다.
 * 2. 관리자가 해당 유저 프로필을 멤버로 할당합니다.
 * 3. (멤버로 인증된 상태에서) 해당 멤버가 토픽을 생성합니다.
 * 4. 생성된 토픽을 멤버 본인이 삭제합니다.
 * 5. 삭제된 토픽을 다시 조회하면 Not Found(404) 에러가 발생해야 하며, 삭제가 영구적임을 검증합니다.
 *
 * [테스트 단계]
 *
 * 1. 관리자 권한으로 user profile 생성
 * 2. 관리자 권한으로 member 생성
 * 3. (멤버 context) 토픽 생성
 * 4. 본인 토픽 삭제
 * 5. 삭제된 토픽 재조회 시 에러 발생 확인
 */
export async function test_api_my_discussion_board_topics_test_delete_own_topic_success(
  connection: api.IConnection,
) {
  // 1. 관리자 권한으로 사용자 프로필 생성
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(userProfile);

  // 2. 관리자 권한으로 member 할당
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userProfile.id,
        joined_at: new Date().toISOString(),
      } satisfies IDiscussionBoardMember.ICreate,
    },
