 * 6. (Optional) If possible, retrieve the updated settings to confirm persistence
 *    and correctness of updated values.
 *
 * Business context: Ensures members have full control over their notification
 * channels and mute-able event types, and changes are persisted and correctly
 * reflected in their settings record.
 */
export async function test_api_my_discussion_board_userNotificationSettings_test_update_notification_settings_success(
  connection: api.IConnection,
) {
  // 1. Admin creates a user profile
  const email = typia.random<string & tags.Format<"email">>();
  const displayName = RandomGenerator.name();
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email,
          display_name: displayName,
          is_active: true,
