    await api.functional.my.discussion_board.userNotificationSettings.create(
      connection,
      {
        body: {
          user_id: member.id,
          receive_email_notifications: true,
          receive_push_notifications: true,
          mute_types: null,
        } satisfies api.IDiscussionBoardUserNotificationSettings.ICreate,
      },
    );
  typia.assert(notificationSettings);

  // 4. Update notification settings: toggle off email notifications, set mute_types
  const update: api.IDiscussionBoardUserNotificationSettings.IUpdate = {
    receive_email_notifications: false,
    receive_push_notifications: true,
    mute_types: "like,moderation",
  };
  const updatedSettings =
    await api.functional.my.discussion_board.userNotificationSettings.update(
      connection,
      {
        id: notificationSettings.id,
