import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationLog";
import type { IPageIDiscussionBoardModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardModerationLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for listing discussion board moderation logs with pagination and
 * filtering (admin API)
 *
 * 이 테스트는 /admin/discussion_board/moderationLogs PATCH 엔드포인트의 동작을 검증합니다. 주요 검증
 * 포인트:
 *
 * - 여러 종류의 moderation log 데이터를 준비(의존 API로 기록 생성)
 * - 필터링(log_type, admin_id, report_id 등)과 페이지네이션 동작의 정확성
 * - 반환 필드가 스키마에 정의된 필드만 포함하는지 확인
 * - 조건에 일치하는 log 없음(empty result set)
 * - 복합 필터 조합/advanced search(다중 필드 및 다양한 조건)
 * - 필수 필드 누락 등 검증 오류 발생시 error
 *
 * 주요 절차 (Step-by-step):
 *
 * 1. 다양한 log_type/admin_id/report_id로 moderation log 데이터 복수 생성 (의존성)
 * 2. Admin_id 기준 필터로 리스트 조회 후, 반환 값이 모두 조건에 부합하며 스키마 필드만 포함되는지 검증
 * 3. 존재하지 않는 log_type 조건으로 조회 후 빈 리스트 반환 확인
 * 4. 복합 조건(restore_content 및 report_id) 조회 및 기대값 검증
 * 5. 필수 입력 누락 시 에러 처리 검증
 */
export async function test_api_admin_discussion_board_moderationLogs_test_list_moderation_logs_with_pagination_and_filters(
  connection: api.IConnection,
) {
  // 1. moderation log 테스트 데이터 생성 (의존: 다양한 log_type/admin)
  const admin1_id = typia.random<string & tags.Format<"uuid">>();
  const admin2_id = typia.random<string & tags.Format<"uuid">>();
  const report_id = typia.random<string & tags.Format<"uuid">>();
  const baseDate = new Date().toISOString();

  const logs = [
    await api.functional.admin.discussion_board.moderationLogs.create(
      connection,
      {
        body: {
          log_type: "block_user",
          admin_id: admin1_id,
          moderator_id: null,
          details: "Blocked repeated spam user.",
          report_id: null,
        } satisfies IDiscussionBoardModerationLog.ICreate,
      },
    ),
    await api.functional.admin.discussion_board.moderationLogs.create(
      connection,
      {
        body: {
          log_type: "block_user",
          admin_id: admin1_id,
          moderator_id: null,
          details: "IP block.",
          report_id: null,
        } satisfies IDiscussionBoardModerationLog.ICreate,
      },
    ),
    await api.functional.admin.discussion_board.moderationLogs.create(
      connection,
      {
        body: {
          log_type: "remove_content",
          admin_id: admin2_id,
          moderator_id: null,
          details: "Removed inappropriate post.",
          report_id: null,
        } satisfies IDiscussionBoardModerationLog.ICreate,
      },
    ),
    await api.functional.admin.discussion_board.moderationLogs.create(
      connection,
      {
        body: {
          log_type: "restore_content",
          admin_id: admin1_id,
          moderator_id: null,
          details: "Appeal approved.",
          report_id: report_id,
        } satisfies IDiscussionBoardModerationLog.ICreate,
      },
    ),
  ];
  logs.forEach(typia.assert);

  // 2. admin_id 기준, log_type: block_user로 필터해서 리스트 조회; 모든 필드의 타입/값/스키마 필드 only 검증
  const list_block_user =
    await api.functional.admin.discussion_board.moderationLogs.index(
      connection,
      {
        body: {
          log_type: "block_user",
          admin_id: admin1_id,
          created_at: logs[0].created_at,
        },
      },
    );
  typia.assert(list_block_user);
  TestValidator.predicate("block_user+admin1만 조회됨")(
    list_block_user.data.every(
      (row) => row.log_type === "block_user" && row.admin_id === admin1_id,
    ),
  );
  // 반환되는 모든 row에서 스키마 field만 존재하는지 체크 (Object.keys)
  list_block_user.data.forEach((row) => {
    TestValidator.equals("스키마 필드만 존재")(Object.keys(row).sort())(
      [
        "id",
        "log_type",
        "admin_id",
        "moderator_id",
        "report_id",
        "details",
        "created_at",
      ].sort(),
    );
  });
  // 페이지네이션 객체 shape/type도 검증
  typia.assert(list_block_user.pagination);

  // 3. 존재하지 않는 log_type 조건으로 조회 (빈 결과)
  const empty =
    await api.functional.admin.discussion_board.moderationLogs.index(
      connection,
      {
        body: {
          log_type: "not_exist_type",
          created_at: baseDate,
        },
      },
    );
  typia.assert(empty);
  TestValidator.equals("존재하지 않은 log_type일 경우 empty list")(
    empty.data.length,
  )(0);

  // 4. 복합 필터(restore_content, report_id)
  const restore_page =
    await api.functional.admin.discussion_board.moderationLogs.index(
      connection,
      {
        body: {
          log_type: "restore_content",
          admin_id: admin1_id,
          report_id: report_id,
          created_at: logs[3].created_at,
        },
      },
    );
  typia.assert(restore_page);
  TestValidator.equals(
    "restore_content+report_id rows? 단 1개, report_id 일치",
  )(restore_page.data.length)(1);
  TestValidator.equals("restore_content+report_id row의 report_id 일치")(
    restore_page.data[0].report_id,
  )(report_id);

  // 5. 필수 입력(log_type) 누락 시 에러처리 (TS type level에서 커버되나 런타임 에러도 확인; 설계 불가시 omit)
  await TestValidator.error("log_type이 누락되면 에러 발생")(
    async () =>
      await api.functional.admin.discussion_board.moderationLogs.index(
        connection,
        {
          body: {
            // log_type: intentionally omitted
            admin_id: admin1_id,
            created_at: logs[0].created_at,
          } as any, // 불가피한 경우만 허용
        },
      ),
  );
}

