import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostAttachment";

/**
 * Validate that a discussion board member cannot update an attachment uploaded by another member.
 *
 * This test simulates the following scenario:
 * 1. Create two user profiles (User A and User B) as board members.
 * 2. User A uploads an attachment to a post.
 * 3. User B (who is also a member, but not the attachment uploader) attempts to update the attachment's metadata.
 * 4. The API should respond with an authorization error, preventing User B from updating the attachment not uploaded by them.
 *
 * This ensures that only uploaders can modify their own discussion board attachments, enforcing RBAC at the service/controller level.
 */
export async function test_api_my_discussion_board_postAttachments_test_member_cannot_update_others_attachment(
  connection: api.IConnection,
) {
  // 1. Create two distinct user profiles (admin action)
  const userAEmail = typia.random<string & tags.Format<"email">>();
  const userBEmail = typia.random<string & tags.Format<"email">>();
  const userA = await api.functional.admin.discussion_board.userProfiles.create(connection, {
    body: {
      email: userAEmail,
      display_name: RandomGenerator.name(),
      is_active: true,
    } satisfies IDiscussionBoardUserProfile.ICreate,
  });
  typia.assert(userA);
  const userB = await api.functional.admin.discussion_board.userProfiles.create(connection, {
    body: {
      email: userBEmail,
      display_name: RandomGenerator.name(),
      is_active: true,
    } satisfies IDiscussionBoardUserProfile.ICreate,
  });
  typia.assert(userB);

  // 2. Assign both as discussion board members (admin action)
  const joinedAt = new Date().toISOString();
  const memberA = await api.functional.admin.discussion_board.members.create(connection, {
    body: {
      discussion_board_user_profile_id: userA.id,
      joined_at: joinedAt,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberA);
  const memberB = await api.functional.admin.discussion_board.members.create(connection, {
    body: {
      discussion_board_user_profile_id: userB.id,
      joined_at: joinedAt,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberB);

  // 3. User A (as member) creates a post and uploads an attachment
  // -- Simulate User A session: assume User A is now authenticated
  // NOTE: For this test, we assume the testing framework (or connection) supports simulating logins for userA/userB for /my/* requests
  // Create the post (User A)
  (connection.headers ??= {}).["X-Mock-User-Id"] = userA.id; // Session spoof for test runner
  const discussion_board_topic_id = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.my.discussion_board.posts.create(connection, {
    body: {
      discussion_board_topic_id,
      title: "Sample post for attachment test",
      body: "Body of the initial post",
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);
  // Upload attachment to the post (User A as uploader)
  const attachment = await api.functional.my.discussion_board.postAttachments.create(connection, {
    body: {
      discussion_board_post_id: post.id,
      file_uri: "https://files.example.com/testfile.png",
      file_name: "testfile.png",
      file_size: 1024,
      mime_type: "image/png",
    } satisfies IDiscussionBoardPostAttachment.ICreate,
  });
  typia.assert(attachment);

  // 4. User B tries to update the attachment uploaded by User A
  // -- Simulate User B session: (again, via mock header or test runner user context)
  (connection.headers ??= {}).["X-Mock-User-Id"] = userB.id;
  await TestValidator.error("user B cannot update user A's attachment")(
    async () => {
      await api.functional.my.discussion_board.postAttachments.update(connection, {
        id: attachment.id,
        body: {
          file_name: "updated_by_user_b.txt",
        } satisfies IDiscussionBoardPostAttachment.IUpdate,
      });
    },
  );
}

