import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";

/**
 * Permanently delete a discussion board notification for the authenticated
 * user.
 *
 * This E2E test verifies that an authenticated user can fully and irreversibly
 * delete their own notification from the system. It confirms that deletion
 * eliminates all access to the record, and verifies correct error handling for
 * attempts to delete already-deleted, nonexistent, or non-owned notifications.
 *
 * Steps:
 *
 * 1. Create a notification as the authenticated user.
 * 2. Delete the notification using the erase API — expect success.
 * 3. Try to delete the same notification again — expect error (not found).
 * 4. Try to delete a random, nonexistent notification ID — expect error.
 * 5. (If API allowed) Try to delete another user's notification — omitted here.
 *
 * When supported, access or deletion of a removed notification should always
 * fail.
 */
export async function test_api_my_discussion_board_notifications_test_delete_notification_for_authenticated_user(
  connection: api.IConnection,
) {
  // 1. Create a notification for self (authenticated user)
  const notification =
    await api.functional.my.discussion_board.notifications.create(connection, {
      body: {
        recipient_user_id: connection.authenticated_user_id,
        type: "new_reply",
        content: "You have a new reply!",
        is_read: false,
        delivered_at: new Date().toISOString(),
        read_at: null,
      } satisfies IDiscussionBoardNotification.ICreate,
    });
  typia.assert(notification);

  // 2. Delete notification — expect success (void)
  await api.functional.my.discussion_board.notifications.erase(connection, {
    id: notification.id,
  });

  // 3. Try to delete again — expect error (not found)
  await TestValidator.error("deleting already-deleted notification")(() =>
    api.functional.my.discussion_board.notifications.erase(connection, {
      id: notification.id,
    }),
  );

  // 4. Try to delete random (nonexistent) notification — expect error (not found)
  const fakeId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("deleting nonexistent notification")(() =>
    api.functional.my.discussion_board.notifications.erase(connection, {
      id: fakeId,
    }),
  );

  // 5. Deleting other user's notification requires cross-user control—omitted (no such API in current E2E scope)
}

