import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopic";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for discussion board posts listing with topic and author filters.
 *
 * This test verifies that the listing endpoint correctly filters posts by both
 * topic ID and author_member_id. The process ensures that only posts created
 * under a specific topic by a specific author are returned.
 *
 * Steps:
 *
 * 1. Create 3 user profiles using the admin endpoint.
 * 2. Assign all user profiles as members using the admin endpoint.
 * 3. Create 2 categories.
 * 4. Each member creates a topic in a category.
 * 5. All members create posts in all topics (generating a uniform post matrix).
 * 6. Add extra posts by one member under one topic for robust filter testing.
 * 7. Call the post list endpoint with discussion_board_topic_id and
 *    author_member_id as filters.
 * 8. Assert that every result has both the filtered topic and author values, and
 *    that only expected posts are present.
 */
export async function test_api_discussion_board_test_list_posts_with_filters_on_topic_id_and_author(
  connection: api.IConnection,
) {
  // 1. Create 3 user profiles
  const profiles = await Promise.all([
    api.functional.admin.discussion_board.userProfiles.create(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        display_name: RandomGenerator.name(),
        is_active: true,
      },
    }),
    api.functional.admin.discussion_board.userProfiles.create(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        display_name: RandomGenerator.name(),
        is_active: true,
      },
    }),
    api.functional.admin.discussion_board.userProfiles.create(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        display_name: RandomGenerator.name(),
        is_active: true,
      },
    }),
  ]);
  profiles.forEach(typia.assert);

  // 2. Assign each profile as board member
  const now = new Date().toISOString();
  const members = await Promise.all(
    profiles.map((profile) =>
      api.functional.admin.discussion_board.members.create(connection, {
        body: {
          discussion_board_user_profile_id: profile.id,
          joined_at: now,
        },
      }),
    ),
  );
  members.forEach(typia.assert);

  // 3. Create 2 board categories
  const categories = await Promise.all([
    api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.paragraph()(2),
        description: RandomGenerator.paragraph()(),
        sort_order: 1,
        is_active: true,
      },
    }),
    api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.paragraph()(2),
        description: RandomGenerator.paragraph()(),
        sort_order: 2,
        is_active: true,
      },
    }),
  ]);
  categories.forEach(typia.assert);

  // 4. Each member creates a topic (round-robin distribute categories)
  const topics = await Promise.all(
    members.map((member, i) =>
      api.functional.my.discussion_board.topics.create(connection, {
        body: {
          discussion_board_category_id: categories[i % categories.length].id,
          title: RandomGenerator.paragraph()(),
          description: RandomGenerator.content()()(),
          status: "open",
        },
      }),
    ),
  );
  topics.forEach(typia.assert);

  // 5. All members create posts in all topics
  const posts: IDiscussionBoardPost[] = [];
  for (const member of members) {
    for (const topic of topics) {
      // (Auth context is not actually switched per member in this test infra)
      const post = await api.functional.my.discussion_board.posts.create(
        connection,
        {
          body: {
            discussion_board_topic_id: topic.id,
            title: RandomGenerator.paragraph()(),
            body: RandomGenerator.content()()(),
          },
        },
      );
      typia.assert(post);
      posts.push(post);
    }
  }

  // 6. For filter test, pick a topic/member & add further posts for robustness
  const targetTopic = topics[0];
  const targetAuthor = members[1];
  const extraPosts: IDiscussionBoardPost[] = [];
  for (let i = 0; i < 2; ++i) {
    const post = await api.functional.my.discussion_board.posts.create(
      connection,
      {
        body: {
          discussion_board_topic_id: targetTopic.id,
          title: RandomGenerator.paragraph()(),
          body: RandomGenerator.content()()(),
        },
      },
    );
    typia.assert(post);
    extraPosts.push(post);
  }
  // Gather expected post IDs for this author & topic
  const expectedPostIDs = posts
    .filter(
      (p) =>
        p.discussion_board_topic_id === targetTopic.id &&
        p.author_member_id === targetAuthor.id,
    )
    .map((p) => p.id)
    .concat(extraPosts.map((p) => p.id));

  // 7. Query the post list endpoint with combined filters
  const output = await api.functional.discussion_board.posts.index(connection, {
    body: {
      discussion_board_topic_id: targetTopic.id,
      author_member_id: targetAuthor.id,
      page: 1,
      limit: 99,
    },
  });
  typia.assert(output);

  // 8. Validate the filtered posts
  for (const post of output.data) {
    TestValidator.equals("topic filtered")(post.discussion_board_topic_id)(
      targetTopic.id,
    );
    TestValidator.equals("author filtered")(post.author_member_id)(
      targetAuthor.id,
    );
    TestValidator.predicate("id in expected set")(
      expectedPostIDs.includes(post.id),
    );
  }
}

