import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IPageDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 게시판 카테고리 목록 (페이지네이션, 검색, 정렬, 활성/비활성 edge) 조회 검증
 *
 * 이 테스트는 discussion_board 카테고리 목록 API가 page/limit, search, sort_field,
 * sort_order 등 모든 주요 파라미터를 정확히 반영하는지, 반환 객체 내 필드가 실제 스키마와 일치하는지, 빈 목록/전체 비활성 같은
 * edge case까지 제대로 지원하는지 검증합니다.
 *
 * 주요 커버리지는 아래와 같습니다.
 *
 * 1. 카테고리 없는 상태에서 조회 - 빈 배열 반환
 * 2. Page/limit 생략(기본값) - 전체 카테고리 조회 및 pagination 정보 타입/값 확인
 * 3. 검색(search) 파라미터 - 일부 name/description 포함 필터 동작
 * 4. 정렬(sorting) 파라미터(sort_field, sort_order) 동작 (sort_order asc 기준 검증)
 * 5. 전체 비활성 상태인 경우 정상 조회 및 is_active===false인 카테고리들만 반환
 * 6. 반환 데이터에 실제 스키마 외 필드 없음 검증(typia.assert)
 *
 * 반환/데이터 유효성은 typia.assert, TestValidator로 step별 점진 검증합니다.
 */
export async function test_api_discussion_board_test_list_categories_with_pagination_and_search(
  connection: api.IConnection,
) {
  // 1. 카테고리 없는 상태에서 조회 (빈 배열 검증)
  const emptyResult = await api.functional.discussion_board.categories.index(
    connection,
    {
      body: {},
    },
  );
  typia.assert(emptyResult);
  TestValidator.equals("empty data array")(emptyResult.data.length)(0);

  // 2. 기본 페이징 조회 (전체)
  const baseResult = await api.functional.discussion_board.categories.index(
    connection,
    {
      body: {},
    },
  );
  typia.assert(baseResult);
  TestValidator.predicate("valid pagination")(
    baseResult.pagination.current >= 1 && baseResult.pagination.pages >= 1,
  );
  TestValidator.predicate("records matches data length")(
    baseResult.pagination.records >= baseResult.data.length,
  );
  // 반환 객체 각 요소 스키마 필드만 포함 검증
  baseResult.data.forEach((cat) => typia.assert(cat));

  // 3. 검색(search) 파라미터
  if (baseResult.data.length > 0) {
    // 일부 name/description 포함 텍스트로 검색
    const searchTerm = baseResult.data[0].name.substring(0, 2);
    const searchResult = await api.functional.discussion_board.categories.index(
      connection,
      {
        body: { search: searchTerm },
      },
    );
    typia.assert(searchResult);
    searchResult.data.forEach((cat) => {
      TestValidator.predicate("검색 결과 name/description 포함 여부")(
        cat.name.includes(searchTerm) ||
          (cat.description && cat.description.includes(searchTerm)),
      );
    });
  }

  // 4. 정렬 파라미터(sorting)
  if (baseResult.data.length >= 2) {
    // sort_field = sort_order, sort_order = asc 기준
    const ascResult = await api.functional.discussion_board.categories.index(
      connection,
      {
        body: { sort_field: "sort_order", sort_order: "asc" },
      },
    );
    typia.assert(ascResult);
    for (let i = 1; i < ascResult.data.length; ++i) {
      TestValidator.predicate("sort_order 오름차순")(
        ascResult.data[i].sort_order >= ascResult.data[i - 1].sort_order,
      );
    }
  }

  // 5. 전체 비활성 케이스 (is_active false만 있는 경우)
  if (
    baseResult.data.length > 0 &&
    baseResult.data.every((cat) => !cat.is_active)
  ) {
    baseResult.data.forEach((cat) =>
      TestValidator.equals("is_active false")(cat.is_active)(false),
    );
  }

  // 6. 반환 객체 내 불필요 필드 미포함 검증(typia.assert에서 이미 검증됨)
  baseResult.data.forEach((cat) => typia.assert(cat));
}

