    TestValidator.equals("multi filter: cleared")(rec.cleared)(multiFilter.cleared);
    TestValidator.equals("multi filter: flag_type")(rec.flag_type)(multiFilter.flag_type);
  }

  // 4. Pagination (default limit/page logic) - check result count and pagination consistency
  const page1 = await query({
