    flag_type: "manual",
  });
  // Should always return <= default limit (100)
  TestValidator.predicate("page1 max default limit")(page1.data.length <= 100);
  TestValidator.equals("pagination consistency")(page1.pagination.records)(multiRes.pagination.records);

