  const keyword = "reply";
  const keywordList = await api.functional.discussion_board.notifications.index(
    connection,
    {
      body: { content: keyword },
    },
  );
  typia.assert(keywordList);
  TestValidator.predicate("all contents include keyword")(
    keywordList.data.every((n) => n.content.includes(keyword)),
  );

  // e) delivered_at boundary (should get only notifications delivered recently)
  const deliveredAtList =
    await api.functional.discussion_board.notifications.index(connection, {
      body: { delivered_at: recentTime.toISOString() },
    });
  typia.assert(deliveredAtList);
  TestValidator.predicate("all delivered_at >= filter")(
    deliveredAtList.data.every((n) => new Date(n.delivered_at) >= recentTime),
  );

  // f) read_at boundary (should get only notifications read after a given time)
  const readAtList = await api.functional.discussion_board.notifications.index(
    connection,
    {
      body: { read_at: nowIso },
    },
  );
