    ),
  );

  // g) Pagination: limit 1 (pagination params aren't in schema; skip unless available)
  const pagedAll = await api.functional.discussion_board.notifications.index(
    connection,
    {
      body: {},
    },
  );
  typia.assert(pagedAll);
  TestValidator.equals("pagination matches count")(pagedAll.pagination.records)(
    created.length,
  );

  // Confirm that all returned notifications are for the correct user
  for (const resp of [
    unreadList,
    readList,
    typeAList,
    keywordList,
    deliveredAtList,
    readAtList,
    pagedAll,
  ]) {
    TestValidator.predicate("no foreign notifications")(resp.data.every((n) => n.recipient_user_id === recipient_user_id));
  }

  // 7. Negative case: Confirm another user's notifications do not appear
  // (if multi-user context is viable; here, simulate by creating notification with another random uuid)
  const otherUserNotif =
