import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopic";
import type { IPageIDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardTopic";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing, searching, and filtering topics with pagination support on the
 * discussion board.
 *
 * This end-to-end test covers the following flow:
 *
 * 1. Create two categories for topic association (admin).
 * 2. Create two user profiles and assign them as discussion board members (admin).
 * 3. As each member, create multiple topics with varying categories, titles,
 *    statuses, and pinned/closed states.
 * 4. Use the /discussion_board/topics endpoint with various filter criteria:
 *
 *    - No filters (default list)
 *    - Keyword search on title/description
 *    - Category filtering
 *    - Status filtering
 *    - Pinned and closed boolean filters
 *    - Pagination controls (limit/page)
 *    - Combined filters
 *    - Filtering to ensure empty result
 *    - Invalid filter scenarios for error handling
 * 5. For each search, validate:
 *
 *    - Returned topics match the filter criteria
 *    - Pagination metadata is correct
 *    - Structure matches DTO (typia.assert)
 *    - There are no extra fields
 *    - Empty array for non-matching filters
 *    - Errors for invalid input parameters
 */
export async function test_api_discussion_board_test_list_topics_with_pagination_and_search_filters(
  connection: api.IConnection,
) {
  // 1. Create two categories
  const category1 =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: `cat${RandomGenerator.alphaNumeric(4)}`,
        name: `CategoryOne`,
        description: "First category for testing",
        sort_order: 1,
        is_active: true,
      },
    });
  typia.assert(category1);
  const category2 =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: `cat${RandomGenerator.alphaNumeric(4)}`,
        name: `CategoryTwo`,
        description: "Second category for testing",
        sort_order: 2,
        is_active: true,
      },
    });
  typia.assert(category2);

  // 2. Create user profiles
  const profile1 =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        },
      },
    );
  typia.assert(profile1);
  const profile2 =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        },
      },
    );
  typia.assert(profile2);

  // 3. Assign members
  const now = new Date().toISOString();
  const member1 = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: profile1.id,
        joined_at: now,
      },
    },
  );
  typia.assert(member1);
  const member2 = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: profile2.id,
        joined_at: now,
      },
    },
  );
  typia.assert(member2);

  // 4. Create multiple topics with varied attributes
  const topicInputs = [
    {
      category: category1,
      title: "Alpha Open",
      desc: "Alpha open topic for category one.",
      status: "open",
      pinned_at: null,
      closed_at: null,
    },
    {
      category: category1,
      title: "Beta Closed",
      desc: "Beta closed topic for category one.",
      status: "closed",
      pinned_at: null,
      closed_at: now,
    },
    {
      category: category2,
      title: "Searchable",
      desc: "A searchable unique string appears here.",
      status: "pinned",
      pinned_at: now,
      closed_at: null,
    },
    {
      category: category2,
      title: "Misc open",
      desc: "Miscellaneous open topic for testing.",
      status: "open",
      pinned_at: null,
      closed_at: null,
    },
  ];

  // Sequentially create topics as different members (simulate login/role context)
  const topics: IDiscussionBoardTopic[] = [];
  for (let i = 0; i < topicInputs.length; ++i) {
    const input = topicInputs[i];
    // Assume runner sets authenticated user/member context before each topic creation
    const topic = await api.functional.my.discussion_board.topics.create(
      connection,
      {
        body: {
          discussion_board_category_id: input.category.id,
          title: input.title,
          description: input.desc,
          status: input.status,
          pinned_at: input.pinned_at,
          closed_at: input.closed_at,
        },
      },
    );
    typia.assert(topic);
    topics.push(topic);
  }

  // 5A. No filters (should include all topics)
  let res = await api.functional.discussion_board.topics.index(connection, {
    body: {},
  });
  typia.assert(res);
  TestValidator.predicate("All topics present")(res.data.length >= 4);

  // 5B. Keyword search (should match at least one topic)
  res = await api.functional.discussion_board.topics.index(connection, {
    body: { keywords: "Searchable" },
  });
  typia.assert(res);
  TestValidator.equals("Keyword filter for title")(res.data.length)(1);

  // 5C. Category filtering
  res = await api.functional.discussion_board.topics.index(connection, {
    body: { discussion_board_category_id: category1.id },
  });
  typia.assert(res);
  TestValidator.predicate("Category1 only")(
    res.data.every((d) => d.discussion_board_category_id === category1.id),
  );

  // 5D. Status filtering
  res = await api.functional.discussion_board.topics.index(connection, {
    body: { status: "open" },
  });
  typia.assert(res);
  TestValidator.predicate("Status=open")(
    res.data.every((d) => d.status === "open"),
  );

  // 5E. Pinned filter
  res = await api.functional.discussion_board.topics.index(connection, {
    body: { pinned: true },
  });
  typia.assert(res);
  TestValidator.predicate("Only pinned topics")(
    res.data.every((d) => d.pinned_at != null),
  );

  // 5F. Closed filter
  res = await api.functional.discussion_board.topics.index(connection, {
    body: { closed: true },
  });
  typia.assert(res);
  TestValidator.predicate("Only closed topics")(
    res.data.every((d) => d.closed_at != null),
  );

  // 5G. Pagination (limit and page)
  res = await api.functional.discussion_board.topics.index(connection, {
    body: { limit: 2, page: 2 },
  });
  typia.assert(res);
  TestValidator.equals("Limit = 2")(res.pagination.limit)(2);
  TestValidator.equals("Page = 2")(res.pagination.current)(2);

  // 5H. Combination filter: keyword + status
  res = await api.functional.discussion_board.topics.index(connection, {
    body: { keywords: "open", status: "open" },
  });
  typia.assert(res);
  TestValidator.predicate("Keyword and status filter")(
    res.data.every((d) => d.status === "open" && d.title.includes("open")),
  );

  // 5I. Filter for empty Data (non-existent category)
  res = await api.functional.discussion_board.topics.index(connection, {
    body: {
      discussion_board_category_id: typia.random<
        string & tags.Format<"uuid">
      >(),
    },
  });
  typia.assert(res);
  TestValidator.equals("Empty when category does not exist")(res.data.length)(
    0,
  );

  // 5J. Error handling for invalid filters
  await TestValidator.error("Invalid page value")(async () => {
    // @ts-expect-error
    await api.functional.discussion_board.topics.index(connection, {
      body: { page: "bad" as any },
    });
  });
  await TestValidator.error("Invalid limit value")(async () => {
    // @ts-expect-error
    await api.functional.discussion_board.topics.index(connection, {
      body: { limit: "bad" as any },
    });
  });
  await TestValidator.error("Nonsense status value")(async () => {
    await api.functional.discussion_board.topics.index(connection, {
      body: { status: "__not_a_status__" },
    });
  });
}

