import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPageIDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for listing/searching discussion board members with filters and
 * pagination.
 *
 * Validates the ability to retrieve a paginated and filtered list of board
 * members. The workflow creates multiple user profiles and assigns them as
 * board members with controlled joined_at times and simulates some as inactive.
 * The test retrieves members using various filters (active only, joined_at date
 * window, specific user_profile_id, pagination) and validates responses for
 * correctness, filtering accuracy, and pagination. Also checks empty result
 * edge case.
 *
 * **Test Steps:**
 *
 * 1. Admin creates multiple user profiles with distinct registration times.
 * 2. Admin assigns user profiles as board members, with 4 left active (left_at
 *    null) and 2 simulated as inactive (left_at set locally for test
 *    assertions, since no API to update this field).
 * 3. Calls /discussion_board/members.index multiple ways: a. No filter (all
 *    members) b. Filter by active status (is_active: true) c. Filter by
 *    joined_at from a specific date/window d. Filter by specific user_profile
 *    id e. Pagination (limit, page) f. Negative search edge case (future join
 *    date, expect empty)
 * 4. For each, asserts result schema, verifies all entries match criteria, checks
 *    pagination and query logic, and covers empty array handling.
 */
export async function test_api_discussion_board_test_list_members_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create user profiles (admin)
  const profiles = await ArrayUtil.asyncRepeat(6)(async (_, i) => {
    const now = new Date();
    const joinedAt = new Date(now.getTime() - 1000 * 3600 * 24 * (i + 1));
    const registered_at = joinedAt.toISOString();
    const p = await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: `member${i + 1}_${typia.random<string & tags.Format<"email">>()}`,
          display_name: RandomGenerator.name(),
          registered_at,
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
    typia.assert(p);
    return { ...p, _joined_at: registered_at };
  });

  // 2. Assign as board members: 4 active, 2 inactive
  const memberObjs = await ArrayUtil.asyncMap(profiles)((p, idx) =>
    api.functional.admin.discussion_board.members.create(connection, {
      body: {
        discussion_board_user_profile_id: p.id,
        joined_at: p._joined_at,
      } satisfies IDiscussionBoardMember.ICreate,
    }),
  );
  // Mark left_at for last 2 for test logic (not in DB, but for assertion context)
  const now = new Date();
  const leftAtTime = new Date(now.getTime() - 1000 * 3600 * 2).toISOString();
  const members = await ArrayUtil.asyncMap(memberObjs)(async (m, i) => {
    if (i >= 4) {
      // Simulate inactivation for assertion (no API for this). Not reflected in DB.
      return { ...m, left_at: leftAtTime };
    }
    return m;
  });

  // 3a. No filter
  const outAll = await api.functional.discussion_board.members.index(
    connection,
    { body: {} },
  );
  typia.assert(outAll);
  TestValidator.equals("should match all members")(outAll.data.length)(
    members.length,
  );

  // 3b. Filter active only
  const outActive = await api.functional.discussion_board.members.index(
    connection,
    {
      body: { is_active: true },
    },
  );
  typia.assert(outActive);
  TestValidator.equals("only entries with left_at null")(
    outActive.data.every((member) => member.left_at == null),
  )(true);
  TestValidator.equals("count active members")(outActive.data.length)(4);

  // 3c. Filter joined_at window
  const windowStart = members[2].joined_at;
  const outWindow = await api.functional.discussion_board.members.index(
    connection,
    {
      body: { joined_at_start: windowStart },
    },
  );
  typia.assert(outWindow);
  TestValidator.predicate("every joined_at >= windowStart")(
    outWindow.data.every((m) => new Date(m.joined_at) >= new Date(windowStart)),
  );

  // 3d. Filter by specific profile id
  const targetProfileId = members[0].discussion_board_user_profile_id;
  const outProfile = await api.functional.discussion_board.members.index(
    connection,
    {
      body: { discussion_board_user_profile_id: targetProfileId },
    },
  );
  typia.assert(outProfile);
  TestValidator.equals("member for profile id")(outProfile.data.length)(1);
  TestValidator.equals("profile id matches")(
    outProfile.data[0].discussion_board_user_profile_id,
  )(targetProfileId);

  // 3e. Pagination: page and limit
  const limit = 2;
  const outPaginate1 = await api.functional.discussion_board.members.index(
    connection,
    {
      body: { limit, page: 1 },
    },
  );
  typia.assert(outPaginate1);
  TestValidator.equals("page 1 count")(outPaginate1.data.length)(2);
  TestValidator.equals("pagination current")(outPaginate1.pagination.current)(
    1,
  );

  const outPaginate2 = await api.functional.discussion_board.members.index(
    connection,
    {
      body: { limit, page: 2 },
    },
  );
  typia.assert(outPaginate2);
  TestValidator.equals("page 2 count")(outPaginate2.data.length)(2);
  TestValidator.equals("pagination current")(outPaginate2.pagination.current)(
    2,
  );

  // 3f. Negative search (future join date, expect empty)
  const futureDate = new Date(Date.now() + 1000 * 3600 * 24).toISOString();
  const outEmpty = await api.functional.discussion_board.members.index(
    connection,
    {
      body: { joined_at_start: futureDate },
    },
  );
  typia.assert(outEmpty);
  TestValidator.equals("no match means empty array")(outEmpty.data.length)(0);
}

