import api from "@ORGANIZATION/PROJECT-api";
import type { Idiscussion_board_action_histories } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussion_board_action_histories";

/**
 * Validate admin can fetch a discussion board action history record by ID.
 *
 * This scenario tests the end-to-end admin flow:
 *
 * 1. Create a new action history entry with known data using the admin 'create'
 *    endpoint.
 * 2. Get that newly created entry back via the admin 'get by id' endpoint.
 * 3. Assert that all fields in the response match what was sent on creation
 *    (except those only set server-side, e.g., the generated id).
 * 4. Confirm the response type matches the schema and all necessary fields are
 *    present.
 * 5. Ensure correct access: only admins can perform these operations, and results
 *    reflect only schema-approved fields.
 */
export async function test_api_admin_discussion_board_actionHistories_test_get_action_history_by_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a new action history log as admin with known values
  const createInput: Idiscussion_board_action_histories.ICreate = {
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: "post_created",
    target_table: "discussion_board_posts",
    target_id: typia.random<string & tags.Format<"uuid">>(),
    summary: "Initial post creation event for E2E test.",
    occurred_at: new Date().toISOString(),
  };
  const created: Idiscussion_board_action_histories =
    await api.functional.admin.discussion_board.actionHistories.create(
      connection,
      {
        body: createInput,
      },
    );
  typia.assert(created);

  // 2. Get the same log entry by id
  const fetched: Idiscussion_board_action_histories =
    await api.functional.admin.discussion_board.actionHistories.at(connection, {
      id: created.id,
    });
  typia.assert(fetched);

  // 3. Validate all fields (except id) match what was created
  TestValidator.equals("actor_id")(fetched.actor_id)(createInput.actor_id);
  TestValidator.equals("action_type")(fetched.action_type)(
    createInput.action_type,
  );
  TestValidator.equals("target_table")(fetched.target_table)(
    createInput.target_table,
  );
  TestValidator.equals("target_id")(fetched.target_id)(createInput.target_id);
  TestValidator.equals("summary")(fetched.summary ?? null)(
    createInput.summary ?? null,
  );
  TestValidator.equals("occurred_at")(fetched.occurred_at)(
    createInput.occurred_at,
  );

  // 4. Confirm schema compliance
  typia.assert<Idiscussion_board_action_histories>(fetched);
}

