import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPageIDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for listing/searching discussion board members with filters and
 * pagination.
 *
 * Validates the ability to retrieve a paginated and filtered list of board
 * members. The workflow creates multiple user profiles and assigns them as
 * board members with controlled joined_at times. The test retrieves members
 * using various filters (active only, joined_at date window, specific
 * user_profile_id, pagination) and validates responses for correctness,
 * filtering accuracy, and pagination. Also checks empty result edge case.
 *
 * **Test Steps:**
 *
 * 1. Admin creates multiple user profiles with distinct registration times.
 * 2. Admin assigns user profiles as board members (simulate some as inactive by
 *    test-side filtering only, since left_at cannot be updated via API).
 * 3. Calls /discussion_board/members.index multiple ways: a. No filter (all
 *    members) b. Filter by active status (is_active: true/false) c. Filter by
 *    joined_at from a specific date/window d. Filter by specific user_profile
 *    id e. Pagination (limit, page) f. Negative search edge case (future join
 *    date, expect empty)
 * 4. For each, asserts result schema, verifies all entries match criteria, checks
 *    pagination and query logic, and covers empty array handling.
 */
export async function test_api_discussion_board_test_list_members_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create user profiles (admin)
  const userProfileCount = 6;
  const now = new Date();

  const profiles = await ArrayUtil.asyncRepeat(userProfileCount)(
    async (index: number) => {
      const joinedAt = new Date(
        now.getTime() - 1000 * 3600 * 24 * (index + 1),
      ).toISOString();
      const profile =
        await api.functional.admin.discussion_board.userProfiles.create(
          connection,
          {
            body: {
              email: `member${index + 1}_${typia.random<string & tags.Format<"email">>()}`,
              display_name: RandomGenerator.name(),
              registered_at: joinedAt,
              is_active: true,
            } satisfies IDiscussionBoardUserProfile.ICreate,
          },
        );
      typia.assert(profile);
      return profile;
    },
  );

  // 2. Assign as board members
  const members = await ArrayUtil.asyncMap(profiles)(
    async (profile: IDiscussionBoardUserProfile) => {
      const joinedAt = profile.registered_at;
      const member = await api.functional.admin.discussion_board.members.create(
        connection,
        {
          body: {
            discussion_board_user_profile_id: profile.id,
            joined_at: joinedAt,
          } satisfies IDiscussionBoardMember.ICreate,
        },
      );
      typia.assert(member);
      return member;
    },
  );

  // 3a. No filter (should return all created members)
  const outAll = await api.functional.discussion_board.members.index(
    connection,
    { body: {} },
  );
  typia.assert(outAll);
  TestValidator.predicate("contains all test members")(
    members.every((m) => outAll.data.some((o) => o.id === m.id)),
  );

  // 3b. Filter active only (left_at should be null or undefined)
  const outActive = await api.functional.discussion_board.members.index(
    connection,
    { body: { is_active: true } },
  );
  typia.assert(outActive);
  TestValidator.predicate("all are active (left_at is null)")(
    outActive.data.every((m) => m.left_at === null || m.left_at === undefined),
  );

  // 3c. Filter joined_at window (from middle member's joined_at)
  const windowStart = members[2].joined_at;
  const outWindow = await api.functional.discussion_board.members.index(
    connection,
    { body: { joined_at_start: windowStart } },
  );
  typia.assert(outWindow);
  TestValidator.predicate("every joined_at >= windowStart")(
    outWindow.data.every((m) => new Date(m.joined_at) >= new Date(windowStart)),
  );

  // 3d. Filter by specific profile id
  const targetProfileId = members[0].discussion_board_user_profile_id;
  const outProfile = await api.functional.discussion_board.members.index(
    connection,
    { body: { discussion_board_user_profile_id: targetProfileId } },
  );
  typia.assert(outProfile);
  TestValidator.equals("profile id matches")(
    outProfile.data[0].discussion_board_user_profile_id,
  )(targetProfileId);
  TestValidator.equals("single match")(outProfile.data.length)(1);

  // 3e. Pagination: test two pages (limit = 2)
  const limit = 2;
  const outPaginate1 = await api.functional.discussion_board.members.index(
    connection,
    { body: { limit, page: 1 } },
  );
  typia.assert(outPaginate1);
  TestValidator.equals("page 1 count")(outPaginate1.data.length)(limit);
  TestValidator.equals("pagination current")(outPaginate1.pagination.current)(
    1,
  );

  const outPaginate2 = await api.functional.discussion_board.members.index(
    connection,
    { body: { limit, page: 2 } },
  );
  typia.assert(outPaginate2);
  TestValidator.equals("page 2 count")(outPaginate2.data.length)(limit);
  TestValidator.equals("pagination current")(outPaginate2.pagination.current)(
    2,
  );

  // 3f. Negative search (future join date, expect empty)
  const futureDate = new Date(Date.now() + 1000 * 3600 * 24).toISOString();
  const outEmpty = await api.functional.discussion_board.members.index(
    connection,
    { body: { joined_at_start: futureDate } },
  );
  typia.assert(outEmpty);
  TestValidator.equals("no match means empty array")(outEmpty.data.length)(0);
}

