/**
 * E2E Test: Create a comment with valid data as an authenticated member
 *
 * This test verifies that an authenticated member can create a new comment on
 * an existing discussion board post. It ensures that a valid post exists first,
 * then submits a root-level comment (without a parent), and validates that the
 * comment entity is correctly created and is_deleted defaults to false.
 *
 * Steps:
 *
 * 1. Create a new post (dependency setup) that will be commented on.
 * 2. Create a root comment (no parent_id) for that post.
 * 3. Validate the response's integrity: correct post association, null parent_id,
 *    content match, is_deleted is false, and timestamps set.
 */
export async function test_api_my_test_create_comment_with_valid_data(
  connection: api.IConnection,
) {
  // Step 1: Create a new post that we will comment on
  const postInput: IDiscussionBoardPost.ICreate = {
    discussion_board_topic_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(5),
    body: RandomGenerator.content()()(2),
  };
  const post = await api.functional.my.discussion_board.posts.create(
    connection,
    {
      body: postInput,
    },
  );
