import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * E2E test for updating mutable fields of a discussion board category as admin.
 *
 * Scenario:
 *
 * 1. Create a category (as admin) to obtain a valid category id.
 * 2. Update the category's mutable fields (name, description, sort_order,
 *    is_active), ensuring code is not modified.
 * 3. Verify the response after update reflects the new field values and code
 *    remains unchanged.
 * 4. Confirm that `updated_at` differs from the original and is later than or
 *    equal to `created_at`.
 */
export async function test_api_admin_discussion_board_categories_test_update_category_fields_success(
  connection: api.IConnection,
) {
  // 1. Create a category as the prerequisite for the update.
  const createInput: IDiscussionBoardCategory.ICreate = {
    code: `code_${RandomGenerator.alphaNumeric(6)}`,
    name: `Category ${RandomGenerator.alphabets(6)}`,
    description: RandomGenerator.paragraph()(),
    sort_order: typia.random<number & tags.Type<"int32">>(),
    is_active: true,
  };
  const created = await api.functional.admin.discussion_board.categories.create(
    connection,
    { body: createInput },
  );
  typia.assert(created);

  // 2. Prepare a category update with new values (code is immutable)
  const updateInput: IDiscussionBoardCategory.IUpdate = {
    name: `${created.name} (updated)`,
    description: `${created.description ?? ""} Updated description.`,
    sort_order: created.sort_order + 1,
    is_active: !created.is_active,
  };
  const beforeUpdatedAt = created.updated_at;

  // 3. Update the category by its id
  const updated = await api.functional.admin.discussion_board.categories.update(
    connection,
    {
      id: created.id,
      body: updateInput,
    },
  );
  typia.assert(updated);

  // 4. Validate immutability of code and correctness of updated fields
  TestValidator.equals("id remains the same")(updated.id)(created.id);
  TestValidator.equals("code is immutable")(updated.code)(created.code);
  TestValidator.equals("name updated")(updated.name)(updateInput.name);
  TestValidator.equals("description updated")(updated.description)(
    updateInput.description,
  );
  TestValidator.equals("sort_order updated")(updated.sort_order)(
    updateInput.sort_order,
  );
  TestValidator.equals("is_active updated")(updated.is_active)(
    updateInput.is_active,
  );

  // 5. Validate updated_at changes and is not before created_at
  TestValidator.predicate("updated_at should change")(
    updated.updated_at !== beforeUpdatedAt,
  );
  TestValidator.predicate("updated_at is not before created_at")(
    new Date(updated.updated_at).getTime() >=
      new Date(updated.created_at).getTime(),
  );
}

