/**
 * Validate update of configuration entry (value/description).
 *
 * This test ensures that configuration entries can be updated by their ID—
 * specifically, the 'value' and 'description' fields, as per system rules.
 *
 * Business Context:
 *
 * - Admins can modify existing configurations (value/description) but not the key
 *   or id.
 * - The test provides full coverage for the conventional admin edit scenario.
 *
 * Test Process:
 *
 * 1. Create a configuration entry for testing (save returned id)
 * 2. Update the entry's value and description using its id
 * 3. Verify the update operation succeeds and all changed fields are correct in
 *    response
 */
export async function test_api_admin_discussion_board_configurations_test_update_configuration_value_and_description(
  connection: api.IConnection,
) {
  // Step 1: Create a configuration entry
  const createInput = {
    key: `max_attachment_size_test_${Math.floor(Math.random() * 10000)}`,
    value: "10240",
