    await api.functional.admin.discussion_board.configurations.create(
      connection,
      { body: createInput },
    );
  typia.assert(original);

  // Step 2: Update value and description (simulate a setting change)
  const updateInput = {
    value: (Number(original.value) + 2048).toString(),
    description: "업로드 최대 크기 값을 2048만큼 증가 (테스트수정)",
  } satisfies IDiscussionBoardConfiguration.IUpdate;

