 *
 * Business context:
 *
 * - Moderators may only be assigned by admins to pre-existing user profiles.
 * - Each assignment includes full audit trail fields, with no sensitive data.
 * - Assignment is active upon creation (revoked_at must be null).
 *
 * Workflow:
 *
 * 1. Create a user profile to be the new moderator (admin operation)
 * 2. Create a moderator assignment for that user (admin operation)
 * 3. Retrieve the moderator assignment by its ID
 * 4. Assert that all moderator assignment fields are present and correct
 *    (including state: revoked_at is null)
 */
export async function test_api_admin_discussion_board_moderators_test_get_moderator_by_id_success(
  connection: api.IConnection,
) {
