  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
          // registered_at: optional, default to system
        },
      },
    );
  typia.assert(userProfile);

  // 2. Assign moderator role to the created user profile (assign self as grantor for audit)
  // For test, grantor = recipient (simulate self-assignment, as allowed for E2E convenience)
  const moderatorAssignment =
    await api.functional.admin.discussion_board.moderators.create(connection, {
      body: {
        discussion_board_user_profile_id: userProfile.id,
        assigned_at: new Date().toISOString(),
