  )(userProfile.id);
  TestValidator.equals("assigner matches")(
    fetchedModerator.assigned_by_user_profile_id,
  )(moderatorAssignment.assigned_by_user_profile_id);
  TestValidator.equals("revoked_at is null")(fetchedModerator.revoked_at)(null);
  TestValidator.predicate("all schema fields present")(
    !!fetchedModerator.id &&
      !!fetchedModerator.discussion_board_user_profile_id &&
      !!fetchedModerator.assigned_at &&
      "revoked_at" in fetchedModerator &&
      !!fetchedModerator.assigned_by_user_profile_id,
  );
}

