import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test moderator revocation logic by updating the revoked_at timestamp.
 *
 * This test simulates the following steps:
 *
 * 1. Admin creates a user profile for the moderator target
 * 2. Admin creates a user profile for the assigning admin (auditor)
 * 3. Admin assigns the moderator role to the target user by creating a moderator
 *    entry (active by default)
 * 4. Admin updates the moderator assignment by setting revoked_at to now,
 *    simulating revoking moderator privileges
 * 5. Validate the API response: revoked_at is set, and moderator assignment is
 *    considered revoked, not active
 * 6. Validate that all returned fields align with updates and original assignment
 *    (id, user profile ids, audit fields remain correct)
 */
export async function test_api_admin_discussion_board_moderators_test_update_moderator_revoke_role(
  connection: api.IConnection,
) {
  // 1. Create moderator target user
  const moderatorProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(moderatorProfile);

  // 2. Create assigning admin user
  const assigningAdminProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(assigningAdminProfile);

  // 3. Assign moderator - create moderator assignment (revoked_at should be null)
  const moderatorAssignment =
    await api.functional.admin.discussion_board.moderators.create(connection, {
      body: {
        discussion_board_user_profile_id: moderatorProfile.id,
        assigned_at: new Date().toISOString(),
        assigned_by_user_profile_id: assigningAdminProfile.id,
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderatorAssignment);
  TestValidator.equals("Moderator active before revocation")(
    moderatorAssignment.revoked_at,
  )(null);

  // 4. Update moderator - set revoked_at to now
  const revocationTime = new Date().toISOString();
  const updatedModeratorAssignment =
    await api.functional.admin.discussion_board.moderators.update(connection, {
      id: moderatorAssignment.id,
      body: {
        discussion_board_user_profile_id: moderatorProfile.id,
        assigned_at: moderatorAssignment.assigned_at,
        revoked_at: revocationTime,
        assigned_by_user_profile_id: assigningAdminProfile.id,
      } satisfies IDiscussionBoardModerator.IUpdate,
    });
  typia.assert(updatedModeratorAssignment);

  // 5. Validate revoked_at is set and all audit fields match
  TestValidator.equals("revoked_at is set")(
    updatedModeratorAssignment.revoked_at,
  )(revocationTime);
  TestValidator.equals("user profile id")(
    updatedModeratorAssignment.discussion_board_user_profile_id,
  )(moderatorProfile.id);
  TestValidator.equals("assigned_by")(
    updatedModeratorAssignment.assigned_by_user_profile_id,
  )(assigningAdminProfile.id);

  // 6. Validate assignment is NOT active (revoked)
  TestValidator.predicate("Moderator role considered revoked")(
    !!updatedModeratorAssignment.revoked_at,
  );
}

