import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test successful deletion of a discussion board moderator assignment by its
 * unique ID.
 *
 * This test ensures that a moderator assignment can be deleted using the admin
 * endpoint, fully removing the moderator privileges from the user. It validates
 * that after deletion, the assignment record is no longer retrievable and that
 * the user is no longer considered a moderator.
 *
 * Workflow Steps:
 *
 * 1. Create a user profile for moderator assignment (admin-side user profile
 *    creation).
 * 2. Create another admin user profile to act as the assigning admin.
 * 3. Assign moderator role to the user by creating a moderator assignment entry
 *    (capture the assignment ID).
 * 4. Delete the moderator assignment by ID using the admin erase endpoint.
 * 5. Attempt a redundant deletion of the same moderator assignment and confirm
 *    error is thrown (record is gone).
 * 6. (If a get/list endpoint existed: Optionally, attempt to retrieve the
 *    assignment record or check moderator status to confirm residual removal.
 *    Omit if not implementable.)
 */
export async function test_api_admin_discussion_board_moderators_test_delete_moderator_assignment_success(
  connection: api.IConnection,
) {
  // 1. Admin creates a user profile (future moderator)
  const userEmail: string = typia.random<string & tags.Format<"email">>();
  const user: IDiscussionBoardUserProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: userEmail,
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(user);

  // 2. Admin creates another user profile to act as the assigning admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const admin: IDiscussionBoardUserProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: adminEmail,
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(admin);

  // 3. Create moderator assignment
  const moderatorAssignment: IDiscussionBoardModerator =
    await api.functional.admin.discussion_board.moderators.create(connection, {
      body: {
        discussion_board_user_profile_id: user.id,
        assigned_at: new Date().toISOString(),
        assigned_by_user_profile_id: admin.id,
      } satisfies IDiscussionBoardModerator.ICreate,
    });
  typia.assert(moderatorAssignment);
  TestValidator.equals("moderator assignment links to user profile")(
    moderatorAssignment.discussion_board_user_profile_id,
  )(user.id);
  TestValidator.equals("assigned by correct admin")(
    moderatorAssignment.assigned_by_user_profile_id,
  )(admin.id);
  TestValidator.equals("not yet revoked")(moderatorAssignment.revoked_at)(null);

  // 4. Delete the moderator assignment
  await api.functional.admin.discussion_board.moderators.erase(connection, {
    id: moderatorAssignment.id,
  });

  // 5. Attempt redundant deletion to confirm hard delete
  await TestValidator.error("redundant deletion should fail")(() =>
    api.functional.admin.discussion_board.moderators.erase(connection, {
      id: moderatorAssignment.id,
    }),
  );
}

