import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPageDiscussionBoardUserProfiles } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardUserProfiles";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";

/**
 * Test paginated, filterable user profile listing in the discussion board.
 *
 * This test validates the discussion_board user profile listing API for correct
 * behavior under pagination, filtering, and searching options. By creating
 * multiple distinct user profiles, we verify that:
 *
 * - Display_name, email, and is_active filters return only relevant user profiles
 * - Pagination (limit and page) is correctly enforced
 * - Empty results appear for impossible filters or out-of-range pages
 *
 * Test steps:
 *
 * 1. Create several user profiles (with different display_name, email, and
 *    is_active combinations)
 * 2. Search by display_name substring and expect only matches
 * 3. Search by unique email and match exactly one
 * 4. Filter by is_active (true/false) and check only correct is_active values
 *    returned
 * 5. Paginate using limit & page, check record count and pagination metadata
 * 6. Search with non-existent display_name, expect an empty list
 * 7. Access an out-of-range page, expect empty results
 */
export async function test_api_discussion_board_test_list_user_profiles_with_pagination_and_search(
  connection: api.IConnection,
) {
  // 1. Create multiple user profiles with distinct attributes
  const profiles = await Promise.all([
    api.functional.admin.discussion_board.userProfiles.create(connection, {
      body: {
        display_name: "Alice Wonderland",
        email: typia.random<string & tags.Format<"email">>(),
        is_active: true,
      },
    }),
    api.functional.admin.discussion_board.userProfiles.create(connection, {
      body: {
        display_name: "Bob Builder",
        email: typia.random<string & tags.Format<"email">>(),
        is_active: false,
      },
    }),
    api.functional.admin.discussion_board.userProfiles.create(connection, {
      body: {
        display_name: "Charlie Chaplin",
        email: typia.random<string & tags.Format<"email">>(),
        is_active: true,
      },
    }),
    api.functional.admin.discussion_board.userProfiles.create(connection, {
      body: {
        display_name: "Alice Springs",
        email: typia.random<string & tags.Format<"email">>(),
        is_active: false,
      },
    }),
  ]);
  profiles.forEach((profile) => typia.assert(profile));

  // 2. Search by display_name substring ("Alice")
  const pageAlice = await api.functional.discussion_board.userProfiles.index(
    connection,
    {
      body: {
        display_name: "Alice",
      },
    },
  );
  typia.assert(pageAlice);
  TestValidator.predicate("all results have display_name containing 'Alice'")(
    pageAlice.data.every((p) => p.display_name.includes("Alice")),
  );

  // 3. Search by unique email address
  const target = profiles[2];
  const pageEmail = await api.functional.discussion_board.userProfiles.index(
    connection,
    {
      body: {
        email: target.email,
      },
    },
  );
  typia.assert(pageEmail);
  TestValidator.equals("unique email result count")(pageEmail.data.length)(1);
  TestValidator.equals("email match")(pageEmail.data[0].email)(target.email);

  // 4. Filter all active profiles
  const pageActive = await api.functional.discussion_board.userProfiles.index(
    connection,
    {
      body: {
        is_active: true,
      },
    },
  );
  typia.assert(pageActive);
  TestValidator.predicate("all are active")(
    pageActive.data.every((p) => p.is_active),
  );

  // 5. Filter all inactive profiles
  const pageInactive = await api.functional.discussion_board.userProfiles.index(
    connection,
    {
      body: {
        is_active: false,
      },
    },
  );
  typia.assert(pageInactive);
  TestValidator.predicate("all are inactive")(
    pageInactive.data.every((p) => !p.is_active),
  );

  // 6. Pagination: limit=2, page=1 and page=2
  const page1 = await api.functional.discussion_board.userProfiles.index(
    connection,
    {
      body: { limit: 2, page: 1 },
    },
  );
  typia.assert(page1);
  TestValidator.equals("page 1 data count")(page1.data.length)(2);
  TestValidator.equals("page 1 pagination.current")(page1.pagination.current)(
    1,
  );
  TestValidator.equals("page 1 limit")(page1.pagination.limit)(2);

  const page2 = await api.functional.discussion_board.userProfiles.index(
    connection,
    {
      body: { limit: 2, page: 2 },
    },
  );
  typia.assert(page2);
  TestValidator.equals("page 2 data count")(page2.data.length)(2);
  TestValidator.equals("page 2 pagination.current")(page2.pagination.current)(
    2,
  );

  // 7. Search for a non-existent display_name
  const pageNone = await api.functional.discussion_board.userProfiles.index(
    connection,
    {
      body: {
        display_name: "NO_MATCH_RESULT_EXPECTED",
      },
    },
