import type { IDiscussionBoardCategoryPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategoryPermission";

/**
 * Validate uniqueness constraint for (category_id, role_name) when creating
 * discussion board category permissions.
 *
 * Business context: Only one permission row may exist per category-role
 * combination, and permission assignment is an admin-only operation.
 *
 * Workflow:
 *
 * 1. Create a new discussion board category to obtain a valid category_id.
 * 2. Create a category permission with a fixed role (e.g., "moderator") for that
 *    category—should succeed.
 * 3. Attempt to create another permission with the same (category_id,
 *    role_name)—should fail with uniqueness error.
 * 4. Verify the error response indicates constraint violation, and that only one
 *    permission row exists for the pair.
 */
export async function test_api_admin_discussion_board_categoryPermissions_test_create_category_permission_with_duplicate_category_and_role(
  connection: api.IConnection,
) {
  // 1. Create category
  const categoryInput: IDiscussionBoardCategory.ICreate = {
    code: `cat_${RandomGenerator.alphaNumeric(8)}`,
    name: `Test Category ${RandomGenerator.alphabets(5)}`,
    description: "For duplicate permission test.",
    sort_order: 1,
    is_active: true,
  };
  const category =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: categoryInput,
    });
  typia.assert(category);

  // 2. Create first permission for this category/role
  const permInput: IDiscussionBoardCategoryPermission.ICreate = {
    category_id: category.id,
    role_name: "moderator",
    can_view: true,
    can_create_topic: true,
    can_reply: true,
    can_like: true,
    can_report: true,
  };
  const perm =
    await api.functional.admin.discussion_board.categoryPermissions.create(
      connection,
      { body: permInput },
    );
  typia.assert(perm);

  // 3. Attempt duplicate permission ('moderator' for same category)
  await TestValidator.error("Duplicate permission creation must fail")(
    async () => {
      await api.functional.admin.discussion_board.categoryPermissions.create(
        connection,
        { body: permInput },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardCategoryPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategoryPermission";
import type { IPageDiscussionBoardCategoryPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardCategoryPermission";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing and filtering of category permissions with pagination.
 *
 * This test verifies listing, pagination, and filter logic for discussion board
 * category permissions. It ensures the admin index endpoint returns correct
 * datasets, pagination, and respects filters by category and role.
 *
 * Steps:
 *
 * 1. Create two discussion board categories
 * 2. For each category, create permission sets for all roles
 *    (admin/moderator/member/guest)
 * 3. List all permissions, verify total and content
 * 4. List with pagination (limit=3, multiple pages), verify slicing, total, and
 *    data content
 * 5. Filter by category_id: only permissions for that category are returned
 * 6. Filter by role_name: only entries for that role (across categories) are
 *    returned
 * 7. Filter by both category_id and role_name: single match is returned
 * 8. Edge cases: non-existent category/role filters, and page beyond last page,
 *    always return empty data
 */
export async function test_api_admin_discussion_board_categoryPermissions_test_list_category_permissions_with_pagination_and_filter(
  connection: api.IConnection,
) {
  // Step 1: Create two categories
  const categoryA =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: `catA-${typia.random<string>()}`,
        name: "Category A",
        description: "Test category A",
        sort_order: 1,
        is_active: true,
      } satisfies IDiscussionBoardCategory.ICreate,
    });
  typia.assert(categoryA);

  const categoryB =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: `catB-${typia.random<string>()}`,
        name: "Category B",
        description: "Test category B",
        sort_order: 2,
        is_active: true,
      } satisfies IDiscussionBoardCategory.ICreate,
    });
  typia.assert(categoryB);

  // Step 2: For each category, create permissions for all roles
  const role_names = ["admin", "moderator", "member", "guest"] as const;
  const permissions: IDiscussionBoardCategoryPermission[] = [];
  for (const cat of [categoryA, categoryB]) {
    for (const role of role_names) {
      const perm =
        await api.functional.admin.discussion_board.categoryPermissions.create(
          connection,
          {
            body: {
              category_id: cat.id,
              role_name: role,
              can_view: true,
              can_create_topic: role !== "guest",
              can_reply:
                role === "admin" || role === "moderator" || role === "member",
              can_like: role !== "guest",
              can_report: true,
            } satisfies IDiscussionBoardCategoryPermission.ICreate,
          },
        );
      typia.assert(perm);
      permissions.push(perm);
    }
  }

  // Helper: permission matcher by props
  const findPerms = (
    filter: Partial<
      Pick<IDiscussionBoardCategoryPermission, "category_id" | "role_name">
    >,
  ) =>
    permissions.filter(
      (p) =>
        (!filter.category_id || p.category_id === filter.category_id) &&
        (!filter.role_name || p.role_name === filter.role_name),
    );

  // Step 3: List all permissions with no filters
  const allPage =
    await api.functional.admin.discussion_board.categoryPermissions.index(
      connection,
      {
        body: {},
      },
    );
  typia.assert(allPage);
  TestValidator.equals("all count")(allPage.pagination.records)(
    permissions.length,
  );
  TestValidator.equals("all as array")(allPage.data.length)(permissions.length);
  // Content check: All permissions created are in data (by id)
  for (const perm of permissions)
    TestValidator.predicate(`permission id exists: ${perm.id}`)(
      allPage.data.some((d) => d.id === perm.id),
    );

  // Step 4: Pagination test (limit=3, page=1/2)
  const limit = 3;
  const total = permissions.length;
  const totalPages = Math.ceil(total / limit);
  for (let page = 1; page <= totalPages; ++page) {
    const { pagination, data } =
      await api.functional.admin.discussion_board.categoryPermissions.index(
        connection,
        {
          body: {
            page,
            limit,
          } satisfies IDiscussionBoardCategoryPermission.IRequest,
        },
      );
    typia.assert({ pagination, data });
    TestValidator.equals("pagination records")(pagination.records)(total);
    TestValidator.equals("current page")(pagination.current)(page);
    TestValidator.equals("limit")(pagination.limit)(limit);
    TestValidator.equals("pages")(pagination.pages)(totalPages);
    // Check slice matches expected
    const expected = permissions
      .slice((page - 1) * limit, page * limit)
      .map((p) => p.id)
      .sort();
    const found = data.map((p) => p.id).sort();
    TestValidator.equals(`entries page=${page}`)(found)(expected);
  }

  // Page beyond last: data empty
  const overPage = totalPages + 1;
  const over =
    await api.functional.admin.discussion_board.categoryPermissions.index(
      connection,
      {
        body: {
          page: overPage,
          limit,
        } satisfies IDiscussionBoardCategoryPermission.IRequest,
      },
    );
  typia.assert(over);
  TestValidator.equals("page beyond last, data empty")(over.data.length)(0);

  // Step 5: Filter by category_id
  const byCatA =
    await api.functional.admin.discussion_board.categoryPermissions.index(
      connection,
      {
        body: {
          category_id: categoryA.id,
        } satisfies IDiscussionBoardCategoryPermission.IRequest,
      },
    );
  typia.assert(byCatA);
  const expA = findPerms({ category_id: categoryA.id });
  TestValidator.equals("catA count")(byCatA.pagination.records)(expA.length);
  for (const perm of expA)
    TestValidator.predicate(`catA perm in result: ${perm.id}`)(
      byCatA.data.some((d) => d.id === perm.id),
    );

  // Step 6: Filter by role_name
  for (const role of role_names) {
    const byRole =
      await api.functional.admin.discussion_board.categoryPermissions.index(
        connection,
        {
          body: {
            role_name: role,
          } satisfies IDiscussionBoardCategoryPermission.IRequest,
        },
      );
    typia.assert(byRole);
    const expRole = findPerms({ role_name: role });
    TestValidator.equals(`${role} count`)(byRole.pagination.records)(
      expRole.length,
    );
    for (const perm of expRole)
      TestValidator.predicate(`${role} perm in result: ${perm.id}`)(
        byRole.data.some((d) => d.id === perm.id),
      );
  }

  // Step 7: Filter by both category_id and role_name
  for (const cat of [categoryA, categoryB]) {
    for (const role of role_names) {
      const both =
        await api.functional.admin.discussion_board.categoryPermissions.index(
          connection,
          {
            body: {
              category_id: cat.id,
              role_name: role,
            } satisfies IDiscussionBoardCategoryPermission.IRequest,
          },
        );
      typia.assert(both);
      const exp = findPerms({ category_id: cat.id, role_name: role });
      TestValidator.equals(`cat:${cat.id} role:${role} count`)(
        both.pagination.records,
      )(exp.length);
      for (const perm of exp)
        TestValidator.predicate(
          `cat:${cat.id} role:${role} perm in result: ${perm.id}`,
        )(both.data.some((d) => d.id === perm.id));
    }
  }

  // Step 8: Edge cases - non-existent category/role filters return empty
  {
    const noCat =
      await api.functional.admin.discussion_board.categoryPermissions.index(
        connection,
        {
          body: {
            category_id: typia.random<string & tags.Format<"uuid">>(),
          } satisfies IDiscussionBoardCategoryPermission.IRequest,
        },
      );
    typia.assert(noCat);
    TestValidator.equals("invalid category returns none")(
      noCat.pagination.records,
    )(0);
    TestValidator.equals("invalid category data empty")(noCat.data.length)(0);
  }
  {
    const noRole =
      await api.functional.admin.discussion_board.categoryPermissions.index(
        connection,
        {
          body: {
            role_name: "nonexistent-role",
          } satisfies IDiscussionBoardCategoryPermission.IRequest,
        },
      );
    typia.assert(noRole);
    TestValidator.equals("invalid role returns none")(
      noRole.pagination.records,
    )(0);
    TestValidator.equals("invalid role data empty")(noRole.data.length)(0);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardCategoryPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategoryPermission";

/**
 * 카테고리 권한 레코드를 id로 조회하는 기능의 정상 동작 검증
 *
 * 이 테스트는 특정 카테고리에 대한 권한 설정(롤별 접근 및 행동권한 등)을 추가한 뒤, 해당 권한 레코드를 id로 조회했을 때 각
 * 필드(category_id, role_name, 각 권한 여부, created_at 등)가 정확히 반환되는지 검증합니다. 비즈니스적으로는
 * 권한 관리/감사의 핵심 API의 정상 동작 유효성을 확보하기 위함입니다.
 *
 * 단계별 과정:
 *
 * 1. 임의 값으로 카테고리를 생성해 유효 category_id를 획득
 * 2. 해당 카테고리 id로 권한(ICreate)을 생성
 * 3. 생성된 권한의 id로 API를 통해 단건 조회
 * 4. 응답값의 각 필드 존재와, 생성 시 입력값과의 정보 일치 여부를 검증
 */
export async function test_api_admin_discussion_board_categoryPermissions_test_retrieve_existing_category_permission_by_id(
  connection: api.IConnection,
) {
  // 1. 카테고리 생성 (테스트 전용 임의 값)
  const categoryBody: IDiscussionBoardCategory.ICreate = {
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph()(1),
    description: RandomGenerator.content()(1)(1),
    sort_order: typia.random<number & tags.Type<"int32">>(),
    is_active: true,
  };
  const category =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: categoryBody,
    });
  typia.assert(category);
  TestValidator.equals("카테고리 코드 일치")(category.code)(categoryBody.code);

  // 2. 권한 레코드 생성 (위 카테고리 id, 임의 롤/권한값)
  const permissionBody: IDiscussionBoardCategoryPermission.ICreate = {
    category_id: category.id,
    role_name: RandomGenerator.pick(["admin", "moderator", "member", "guest"]),
    can_view: true,
    can_create_topic: false,
    can_reply: true,
    can_like: false,
    can_report: true,
  };
  const permission =
    await api.functional.admin.discussion_board.categoryPermissions.create(
      connection,
      { body: permissionBody },
    );
  typia.assert(permission);
  TestValidator.equals("category_id 일치")(permission.category_id)(category.id);
  TestValidator.equals("role_name 일치")(permission.role_name)(
    permissionBody.role_name,
  );
  TestValidator.equals("can_view 일치")(permission.can_view)(
    permissionBody.can_view,
  );
  TestValidator.equals("can_create_topic 일치")(permission.can_create_topic)(
    permissionBody.can_create_topic,
  );
  TestValidator.equals("can_reply 일치")(permission.can_reply)(
    permissionBody.can_reply,
  );
  TestValidator.equals("can_like 일치")(permission.can_like)(
    permissionBody.can_like,
  );
  TestValidator.equals("can_report 일치")(permission.can_report)(
    permissionBody.can_report,
  );

  // 3. 생성된 권한 id로 단건 조회
  const result =
    await api.functional.admin.discussion_board.categoryPermissions.at(
      connection,
      { id: permission.id },
    );
  typia.assert(result);

  // 4. 각 필드 존재/일치 여부 최종 검증
  TestValidator.equals("category_id 일치")(result.category_id)(category.id);
  TestValidator.equals("role_name 일치")(result.role_name)(
    permissionBody.role_name,
  );
  TestValidator.equals("can_view 일치")(result.can_view)(
    permissionBody.can_view,
  );
  TestValidator.equals("can_create_topic 일치")(result.can_create_topic)(
    permissionBody.can_create_topic,
  );
  TestValidator.equals("can_reply 일치")(result.can_reply)(
    permissionBody.can_reply,
  );
  TestValidator.equals("can_like 일치")(result.can_like)(
    permissionBody.can_like,
  );
  TestValidator.equals("can_report 일치")(result.can_report)(
    permissionBody.can_report,
  );
  TestValidator.predicate("created_at 필드 존재 및 문자열 확인")(
    typeof result.created_at === "string" && result.created_at.length > 0,
  );
}

