import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardCategoryPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategoryPermission";

/**
 * Permanently delete a discussion board category permission by ID and verify
 * removal.
 *
 * This E2E test ensures that when an admin deletes a category permission by its
 * valid ID, the record is irreversibly erased. It creates a category, assigns a
 * permission row, deletes it, then checks that further deletion attempts throw
 * a not-found error. If a get/read API for category permissions existed, we
 * would call it to verify hard delete, but as it is not present, we validate by
 * attempting a repeated delete (should error).
 *
 * Steps:
 *
 * 1. Create a discussion board category (for permission assignment).
 * 2. Create a category permission with role 'moderator'.
 * 3. Permanently delete the permission row using its ID.
