 *
 * 1. Create a report reason via the admin API.
 * 2. As an authenticated member, submit a new report referencing this reason. For
 *    the sake of generic E2E coverage, use a random valid UUID for the reported
 *    entity, and set reported_entity_type to 'post' (as a plausible value),
 *    with an optional description.
 * 3. Attempt to delete the report reason using the admin erase API with its ID.
 * 4. Confirm that an integrity error is thrown and the report reason is NOT
 *    deleted (error/exception).
 *
 * This test ensures referential integrity is enforced and the backend correctly
 * blocks destructive delete when foreign key dependencies exist. If the
 * operation succeeds (which would be a bug), the test will fail. No clean-up is
 * needed, as deletion is intentionally prevented.
 */
export async function test_api_admin_discussion_board_reportReasons_test_delete_report_reason_in_use_by_reports(
  connection: api.IConnection,
) {
  // 1. Admin creates a report reason
  const reportReason =
    await api.functional.admin.discussion_board.reportReasons.create(
      connection,
      {
        body: {
          reason_text: RandomGenerator.alphabets(15),
          active: true,
        },
      },
    );
  typia.assert(reportReason);

  // 2. Member submits a report referencing the above report reason
  const report = await api.functional.my.discussion_board.reports.create(
    connection,
    {
      body: {
        reason_id: reportReason.id,
        reported_entity_id: typia.random<string & tags.Format<"uuid">>(),
        reported_entity_type: "post",
        description: RandomGenerator.paragraph()(),
      },
    },
  );
  typia.assert(report);

  // 3. Attempt to hard-delete the report reason (while still referenced by the report)
  await TestValidator.error(
    "should throw referential integrity error on delete when referenced",
  )(async () => {
    await api.functional.admin.discussion_board.reportReasons.erase(
      connection,
      { id: reportReason.id },
    );
  });
}

