 *
 * 이 테스트는 다음의 시나리오를 통해 API와 비즈니스 흐름의 일치, 데이터 연계, 타입 강제, 응답 포맷을 모두 검증합니다.
 *
 * 1. 멤버(일반 사용자)로서 신고(Report)를 생성해 유효한 report_id를 확보한다.
 * 2. 어드민 권한으로 reportActions API를 호출하여, 해당 report_id에 리포트 액션을 남긴다. (action_type,
 *    admin_id, action_notes 등을 명시)
 * 3. 응답 데이터가 입력과 논리적으로 동일한지, 관계와 포맷이 올바른지 세부 검증한다.
 *
 * 검증 포인트:
 *
 * - 생성된 리포트 액션의 report_id가 최초 신고의 id와 일치해야 합니다.
 * - Admin_id 등 입력 필드가 응답에 정확히 반영되어야 합니다.
 * - 필수 포맷(UUID, date-time 등)도 테스트합니다.
 */
export async function test_api_admin_discussion_board_reportActions_test_create_report_action_with_admin_role(
  connection: api.IConnection,
) {
  // 1. 멤버 권한으로 신고(Report) 생성
  const reportInput: IDiscussionBoardReport.ICreate = {
    reason_id: typia.random<string & tags.Format<"uuid">>(),
    reported_entity_id: typia.random<string & tags.Format<"uuid">>(),
    reported_entity_type: "post",
    description: "테스트 신고 - 어드민 리포트 액션 생성용",
  };
  const report = await api.functional.my.discussion_board.reports.create(
    connection,
    { body: reportInput },
  );
  typia.assert(report);

  // 2. 어드민으로 리포트 액션 생성
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const actionInput: IDiscussionBoardReportAction.ICreate = {
    report_id: report.id,
    admin_id: adminId,
    action_type: "close_report",
    action_notes: "어드민이 리포트 처리를 완료하였습니다.",
  };
  const action =
    await api.functional.admin.discussion_board.reportActions.create(
      connection,
      { body: actionInput },
    );
  typia.assert(action);

  // 3. 응답 필드와 관계 검증
  TestValidator.equals("report_id 일치")(action.report_id)(report.id);
  TestValidator.equals("admin_id 일치")(action.admin_id)(adminId);
  TestValidator.equals("action_type 일치")(action.action_type)(
    actionInput.action_type,
  );
  TestValidator.equals("action_notes 일치")(action.action_notes)(
    actionInput.action_notes,
  );
  TestValidator.predicate("응답 id는 uuid이어야 함")(
    typeof action.id === "string" && action.id.length > 0,
  );
  TestValidator.predicate("created_at은 date-time 문자열이어야 함")(
    typeof action.created_at === "string" && action.created_at.includes("T"),
  );
}

