/**
 * Test the successful retrieval (GET) of a report action with a valid ID.
 *
 * This test simulates the end-to-end workflow where an admin logs a moderation
 * action (such as closing a report) against a flagged discussion board report.
 * The test verifies that after creating a new report action record, fetching by
 * ID returns the correct data.
 *
 * Steps:
 *
 * 1. Create a report action (admin-only: valid report_id, admin_id, action_type,
 *    action_notes; moderator_id set to null)
 * 2. Retrieve the report action by its 'id'
 * 3. Assert that all expected fields match between the created and fetched records
 *    (apart from server-assigned fields)
 */
export async function test_api_admin_discussion_board_reportActions_test_get_report_action_with_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a report action as admin (moderator_id: null)
  const createInput = {
    report_id: typia.random<string & tags.Format<"uuid">>(),
    admin_id: typia.random<string & tags.Format<"uuid">>(),
    moderator_id: null,
    action_type: "close_report",
    action_notes: "Closing as invalid after review.",
  } satisfies IDiscussionBoardReportAction.ICreate;

  const created =
    await api.functional.admin.discussion_board.reportActions.create(
      connection,
      { body: createInput },
    );
  typia.assert(created);

  // 2. Retrieve just-created report action
  const fetched = await api.functional.admin.discussion_board.reportActions.at(
    connection,
    { id: created.id },
