import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IPageDiscussionBoardAdmins } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardAdmins";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates listing, pagination, and filtering for admin assignments in the
 * discussion board.
 *
 * This test verifies that the paginated admin assignment listing endpoint
 * properly handles various filter and pagination parameters:
 *
 * - Only active (non-revoked) assignments (revoked_at omitted)
 * - By assigned_by_user_profile_id (who performed the assignment)
 * - By assigned_at date range
 * - Pagination (page and limit)
 *
 * Steps:
 *
 * 1. Create multiple user profiles (for assignment as admins and as assigners).
 * 2. Assign multiple admins to these user profiles by different assigners and
 *    assigned_at timestamps.
 * 3. Optionally revoke (set revoked_at) for some admin assignments.
 * 4. Test listing all assignments; validate correct total and record contents.
 * 5. Filter for only active assignments (revoked_at omitted).
 * 6. Filter by assigned_by_user_profile_id with pagination.
 * 7. Filter by assigned_at range to only retrieve expected assignments.
 */
export async function test_api_admin_discussion_board_admins_test_list_admin_assignments_with_pagination_and_filters(
  connection: api.IConnection,
) {
  // 1. Create user profiles for assignment (5 profiles)
  const profiles = await Promise.all(
    ArrayUtil.repeat(5)(
      async () =>
        await api.functional.admin.discussion_board.userProfiles.create(
          connection,
          {
            body: {
              email: typia.random<string & tags.Format<"email">>(),
              display_name: RandomGenerator.name(),
              is_active: true,
            } satisfies IDiscussionBoardUserProfile.ICreate,
          },
        ),
    ),
  );
  profiles.forEach((profile) => typia.assert(profile));

  // Also create an assigning admin
  const assigner =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(assigner);

  // 2. Assign admins to all profiles, spreading assigned_at timestamps, by same assigner
  const now = new Date();
  const assignments = await Promise.all(
    profiles.map((profile, idx) =>
      api.functional.admin.discussion_board.admins.create(connection, {
        body: {
          discussion_board_user_profile_id: profile.id,
          assigned_by_user_profile_id: assigner.id,
          assigned_at: new Date(
            now.getTime() - (5 - idx) * 60 * 60 * 1000,
          ).toISOString(),
        } satisfies IDiscussionBoardAdmin.ICreate,
      }),
    ),
  );
  assignments.forEach((a) => typia.assert(a));

  // 3. Revoke some assignments (e.g., even-indexed assignments are active, odds are revoked)
  const revoked_at_value = new Date(
    now.getTime() + 60 * 60 * 1000,
  ).toISOString();
  const updatedAssignments = await Promise.all(
    assignments.map((assignment, idx) =>
      idx % 2 === 1
        ? api.functional.admin.discussion_board.admins.update(connection, {
            id: assignment.id,
            body: {
              discussion_board_user_profile_id:
                assignment.discussion_board_user_profile_id,
              assigned_at: assignment.assigned_at,
              revoked_at: revoked_at_value,
              assigned_by_user_profile_id:
                assignment.assigned_by_user_profile_id,
            } satisfies IDiscussionBoardAdmin.IUpdate,
          })
        : Promise.resolve(assignment),
    ),
  );
  updatedAssignments.forEach((a) => typia.assert(a));

  // 4. List all admin assignments, page 1, limit large enough
  let page = await api.functional.admin.discussion_board.admins.index(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
      } satisfies IPageDiscussionBoardAdmins.IRequest,
    },
  );
  typia.assert(page);
  TestValidator.equals("returns all assignments")(page.data.length)(
    assignments.length,
  );

  // 5. Filter only active (revoked_at omitted)
  page = await api.functional.admin.discussion_board.admins.index(connection, {
    body: {
      page: 1,
      limit: 10,
    } satisfies IPageDiscussionBoardAdmins.IRequest,
  });
  typia.assert(page);
  TestValidator.predicate("only active assignments")(
    page.data.every((a) => a.revoked_at == null),
  );
  TestValidator.equals("active count matches")(page.data.length)(
    assignments.filter((_, idx) => idx % 2 === 0).length,
  );

  // 6. Filter by assigned_by_user_profile_id with pagination
  page = await api.functional.admin.discussion_board.admins.index(connection, {
    body: {
      assigned_by_user_profile_id: assigner.id,
      page: 1,
      limit: 2,
    } satisfies IPageDiscussionBoardAdmins.IRequest,
  });
  typia.assert(page);
  TestValidator.predicate("all returned have correct assigner")(
    page.data.every((a) => a.assigned_by_user_profile_id === assigner.id),
  );

  // 7. Filter by assigned_at range (narrow to last two assignments)
  const fromDate = assignments[assignments.length - 2].assigned_at;
  const toDate = assignments[assignments.length - 1].assigned_at;
  page = await api.functional.admin.discussion_board.admins.index(connection, {
    body: {
      assigned_at_from: fromDate,
      assigned_at_to: toDate,
      page: 1,
      limit: 10,
    } satisfies IPageDiscussionBoardAdmins.IRequest,
  });
  typia.assert(page);
  TestValidator.equals("range matches")(page.data.length)(2);
}

