/**
 * E2E test for listing and searching action history records using various
 * filters.
 *
 * This function tests the action history admin search endpoint for:
 *
 * - Filtering by actor_id, action_type, target_table, target_id, summary
 *   substring, and occurred_at date range
 * - Pagination controls and response integrity
 *
 * Steps:
 *
 * 1. Create 5 unique test action histories, each with distinct actor_id,
 *    action_type, target_table, target_id, summary, and occurred_at values
 * 2. For each filterable property, perform a filtered search and ensure all
 *    returned records match the requested filter
 * 3. Test summary substring filter (full text search)
 * 4. Verify date range filtering (occurred_at_start, occurred_at_end)
 * 5. Perform a paginated fetch and assert the pagination and data length are in
 *    sync
 */
export async function test_api_admin_discussion_board_actionHistories_test_list_action_histories_with_various_filters(
  connection: api.IConnection,
) {
  // 1. Create 5 distinct action histories for the test
  const testHistories: Idiscussion_board_action_histories[] = [];
  for (let i = 0; i < 5; ++i) {
    const actor_id = typia.random<string & tags.Format<"uuid">>();
    const target_id = typia.random<string & tags.Format<"uuid">>();
    const action_type = `action_type_${i}`;
    const target_table = `table_${i % 2}`;
    const summary = `Test history ${i}`;
    const occurred_at = new Date(Date.now() - i * 60 * 60 * 1000).toISOString();
    const history: Idiscussion_board_action_histories =
      await api.functional.admin.discussion_board.actionHistories.create(
        connection,
        {
          body: {
            actor_id,
            action_type,
            target_table,
            target_id,
            summary,
            occurred_at,
          } satisfies Idiscussion_board_action_histories.ICreate,
        },
      );
    typia.assert(history);
    testHistories.push(history);
  }

  // 2. Filter by actor_id
  const actorIdToTest = testHistories[0].actor_id;
  const actorFiltered =
    await api.functional.admin.discussion_board.actionHistories.index(
      connection,
      { body: { actor_id: actorIdToTest } },
    );
  typia.assert(actorFiltered);
  TestValidator.predicate("All actor_id match")(
    actorFiltered.data.every((rec) => rec.actor_id === actorIdToTest),
  );

  // 3. Filter by action_type
  const actionTypeToTest = testHistories[1].action_type;
  const actionTypeFiltered =
    await api.functional.admin.discussion_board.actionHistories.index(
      connection,
      { body: { action_type: actionTypeToTest } },
    );
  typia.assert(actionTypeFiltered);
  TestValidator.predicate("All action_type match")(
    actionTypeFiltered.data.every(
      (rec) => rec.action_type === actionTypeToTest,
    ),
  );

  // 4. Filter by target_table
  const targetTableToTest = testHistories[2].target_table;
  const targetTableFiltered =
    await api.functional.admin.discussion_board.actionHistories.index(
      connection,
      { body: { target_table: targetTableToTest } },
    );
  typia.assert(targetTableFiltered);
  TestValidator.predicate("All target_table match")(
    targetTableFiltered.data.every(
      (rec) => rec.target_table === targetTableToTest,
    ),
  );

  // 5. Filter by target_id
  const targetIdToTest = testHistories[3].target_id;
  const targetIdFiltered =
    await api.functional.admin.discussion_board.actionHistories.index(
      connection,
      { body: { target_id: targetIdToTest } },
    );
  typia.assert(targetIdFiltered);
  TestValidator.predicate("All target_id match")(
    targetIdFiltered.data.every((rec) => rec.target_id === targetIdToTest),
  );

  // 6. Filter by summary substring
  const summarySubstr = testHistories[4].summary?.slice(0, 5) ?? "Test";
  const summaryFiltered =
    await api.functional.admin.discussion_board.actionHistories.index(
      connection,
      { body: { summary: summarySubstr } },
    );
  typia.assert(summaryFiltered);
  TestValidator.predicate("Summary substring match exists")(
    summaryFiltered.data.some((rec) =>
      (rec.summary ?? "").includes(summarySubstr),
    ),
  );

  // 7. Filter by occurred_at range
  // Pick a range between history[2] and history[4]
  const start = testHistories[2].occurred_at;
  const end = testHistories[4].occurred_at;
  const occurredAtFiltered =
    await api.functional.admin.discussion_board.actionHistories.index(
      connection,
      {
        body: {
          occurred_at_start: start,
          occurred_at_end: end,
        },
      },
    );
  typia.assert(occurredAtFiltered);
  TestValidator.predicate("All dates within range")(
    occurredAtFiltered.data.every(
      (rec) => rec.occurred_at >= start && rec.occurred_at <= end,
    ),
  );

  // 8. Pagination controls (basic: data.length <= limit)
  const paginated =
    await api.functional.admin.discussion_board.actionHistories.index(
      connection,
      { body: {} },
    );
  typia.assert(paginated);
  TestValidator.predicate("Pagination meta present")(!!paginated.pagination);
  TestValidator.predicate("Data length <= limit")(
    paginated.data.length <= paginated.pagination.limit,
  );
}

