import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardReportReason } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportReason";
import type { IPageIDiscussionBoardReportReason } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardReportReason";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test successful listing, searching, and paginating report reasons for
 * reporting UI.
 *
 * This test ensures that the listing API for report reasons supports filtering
 * by substring, active status, and correct pagination, as required for a
 * moderator/admin interface. The admin creates multiple reasons with distinct
 * reason_texts and active/inactive status. Listing endpoint is then tested
 * for:
 *
 * - Seeing all items
 * - Performing text filter
 * - Filtering by status
 * - Respecting pagination parameters
 * - Returning empty sets for non-matching filters
 *
 * Steps:
 *
 * 1. Insert several report reasons (covering both status and diverse texts)
 * 2. Fetch without filter, ensuring all are listed
 * 3. Filter by substring (reason_text)
 * 4. Filter by active only
 * 5. Filter by inactive only
 * 6. Test pagination (page, limit)
 * 7. Test empty result for unmatched filter
 */
export async function test_api_discussion_board_test_list_report_reasons_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Insert multiple reasons with a mix of text and status
  const reasons: IDiscussionBoardReportReason.ICreate[] = [
    { reason_text: "Spam Content", active: true },
    { reason_text: "Harassment/Abuse", active: true },
    { reason_text: "Off-topic Boring", active: false },
    { reason_text: "Illegal Promotion", active: false },
    { reason_text: "Duplicate", active: true },
  ];
  const created: IDiscussionBoardReportReason[] = [];
  for (const r of reasons) {
    const rec =
      await api.functional.admin.discussion_board.reportReasons.create(
        connection,
        {
          body: r,
        },
      );
    typia.assert(rec);
    created.push(rec);
  }

  // 2. No filter: get all
  let out = await api.functional.discussion_board.reportReasons.index(
    connection,
    {
      body: {},
    },
  );
  typia.assert(out);
  for (const rec of created) {
    TestValidator.predicate(`reason present: ${rec.reason_text}`)(
      out.data.some((o) => o.id === rec.id),
    );
  }

  // 3. Substring filter (reason_text: "Spam")
  out = await api.functional.discussion_board.reportReasons.index(connection, {
    body: { reason_text: "Spam" },
  });
  typia.assert(out);
  // Only reasons containing "Spam" (should be one in this dataset)
  TestValidator.equals("reason_text partial count")(out.data.length)(1);
  TestValidator.predicate("reason_text contains Spam")(
    out.data[0].reason_text.includes("Spam"),
  );

  // 4. Active filter
  out = await api.functional.discussion_board.reportReasons.index(connection, {
    body: { active: true },
  });
  typia.assert(out);
  for (const rec of out.data) {
    TestValidator.equals("active=true")(rec.active)(true);
  }

  // 5. Inactive filter
  out = await api.functional.discussion_board.reportReasons.index(connection, {
    body: { active: false },
  });
  typia.assert(out);
  for (const rec of out.data) {
    TestValidator.equals("active=false")(rec.active)(false);
  }

  // 6. Pagination (limit 2, page 2)
  out = await api.functional.discussion_board.reportReasons.index(connection, {
    body: { limit: 2, page: 2 },
  });
  typia.assert(out);
  TestValidator.equals("pagination.limit")(out.pagination.limit)(2);
  TestValidator.equals("pagination.current")(out.pagination.current)(2);
  TestValidator.predicate("pagination page data length")(out.data.length <= 2);

  // 7. Edge case: non-matching text with active=false
  out = await api.functional.discussion_board.reportReasons.index(connection, {
    body: { active: false, reason_text: "zzz" },
  });
  typia.assert(out);
  TestValidator.equals("empty result")(out.data.length)(0);
}

