 * 3. User1 creates a comment on that post.
 * 4. User2 'logs in' by session emulation (header), attempts to delete user1's
 *    comment.
 * 5. The delete operation must fail, raising an authorization error.
 */
export async function test_api_discussion_board_test_delete_comment_by_non_author_fails(
  connection: api.IConnection,
) {
  // 1. Create two user profiles (user1 and user2) and assign both as board members
  const now: string = new Date().toISOString();

  // Create user1 profile
