  typia.assert(member);

  // 3. Member creates two posts under random topic ids
  const topicId1 = typia.random<string & tags.Format<"uuid">>();
  const topicId2 = typia.random<string & tags.Format<"uuid">>();

  const post1 = await api.functional.my.discussion_board.posts.create(
