 * 2. Admin grants member status to the user profile with a join date.
 * 3. The member creates a post (requires an existing topic id).
 * 4. The member uploads an attachment to that post.
 * 5. The member updates the file_name and mime_type metadata fields of their own
 *    attachment.
 * 6. The response is checked to confirm that file_name and mime_type are updated
 *    as expected; other fields must remain unchanged.
 *
 * Edge case: Uses all real data dependencies; ensures update is scoped only to
 * allowed fields and user may not change immutable fields.
 */
export async function test_api_my_discussion_board_postAttachments_test_update_own_post_attachment_metadata_success(
  connection: api.IConnection,
) {
  // 1. Admin creates a user profile (for the member/attachment owner)
