  // 5. Member updates file_name and mime_type of their own attachment
  const updateInput = {
    file_name: "testfile-v1-renamed.docx",
    mime_type:
      "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  } satisfies IDiscussionBoardPostAttachment.IUpdate;
  const updatedAttachment =
    await api.functional.my.discussion_board.postAttachments.update(
      connection,
      { id: attachment.id, body: updateInput },
    );
  typia.assert(updatedAttachment);

  // 6. Check that file_name and mime_type were updated and all other fields match original
