  await api.functional.my.discussion_board.postAttachments.erase(connection, {
    id: attachment.id,
  });
  // 6. 첨부파일 직접조회 API가 없으므로, 논리적으로 이전 응답 값 기준으로 soft delete 되었음만 검증
  // 별도 확인 API 생기면, is_deleted true 및 나머지 메타 동일함을 추가 검증하면 됨
}

