 * 5. Fetch the like/dislike by its ID.
 * 6. Assert that all fields (id, post ID, author member ID, is_like, created_at)
 *    match the record that was created.
 *
 * This tests correct PK retrieval and field integrity for post likes/dislikes.
 */
export async function test_api_discussion_board_test_fetch_post_like_by_id_success(
  connection: api.IConnection,
) {
