  TestValidator.equals("discussion_board_post_id")(
    fetched.discussion_board_post_id,
  )(postLike.discussion_board_post_id);
  TestValidator.equals("author_member_id")(fetched.author_member_id)(
    postLike.author_member_id,
  );
  TestValidator.equals("is_like")(fetched.is_like)(postLike.is_like);
  TestValidator.equals("created_at")(fetched.created_at)(postLike.created_at);
