import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostLike";

/**
 * Verify that a member can create a dislike (is_like=false) for a post they
 * have not interacted with yet.
 *
 * This test ensures that a fresh member (user who is newly registered and
 * assigned as a member) can submit a `dislike` (is_like=false) entry for a post
 * for which they have not previously given a like/dislike. It simulates all
 * necessary preparations:
 *
 * 1. Create a new user profile using admin privileges.
 * 2. Assign this user profile as a new board member (capturing their member id).
 * 3. Create another separate user + member and use them to write a fresh post
 *    (which the main test member will interact with for the first time).
 * 4. (Assumed) Set connection context as if logged in as the test member. (In a
 *    real E2E, ensure proper member login context.)
 * 5. Have this test member submit a dislike (is_like=false) for the post.
 *
 * The test then:
 *
 * - Asserts a response entity is returned (type validation).
 * - Confirms that the returned like/dislike entry is associated with the correct
 *   post and author.
 * - Ensures is_like is stored as false (dislike), not true.
 * - Validates all returned PK/foreign keys match the expected ones.
 * - Guarantees this member/post combination was not previously used for
 *   like/dislike (first time interaction).
 */
export async function test_api_my_discussion_board_postLikes_test_create_post_dislike_success(
  connection: api.IConnection,
) {
  // 1. Create a new user profile (as the future author of the dislike)
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(userProfile);

  // 2. Assign that user as a member
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userProfile.id,
        joined_at: new Date().toISOString(),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 3. Create a fresh post authored by a different (auxiliary) member
  const auxProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(auxProfile);
  const auxMember = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: auxProfile.id,
        joined_at: new Date().toISOString(),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(auxMember);

  // For the post to be realistic it needs a topic id (simulate unique topic)
  const topicId = typia.random<string & tags.Format<"uuid">>();

  // Simulate the post creation (by auxiliary member)
  const post = await api.functional.my.discussion_board.posts.create(
    connection,
    {
      body: {
        discussion_board_topic_id: topicId,
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 4. (Assumption): context is switched, API infra would ensure
  //    connection now uses the test member authentication

  // 5. Test member (original) dislikes the post for the first time
  const dislike = await api.functional.my.discussion_board.postLikes.create(
    connection,
    {
      body: {
        discussion_board_post_id: post.id,
        is_like: false,
      } satisfies IDiscussionBoardPostLike.ICreate,
    },
  );
  typia.assert(dislike);

  // Assert returned record matches expectations
  TestValidator.equals("dislike: post id matches")(
    dislike.discussion_board_post_id,
  )(post.id);
  TestValidator.equals("dislike: author id matches")(dislike.author_member_id)(
    member.id,
  );
  TestValidator.equals("dislike: is_like value is false")(dislike.is_like)(
    false,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostLike";

/**
 * Validates that a user cannot like (or dislike) the same discussion board post
 * more than once.
 *
 * This test simulates a user's attempt to create duplicate like/dislike
 * (reaction) entries for the same post and ensures the system correctly
 * enforces the member/post unique constraint.
 *
 * Business context: The backend must prevent a user (i.e. member) from
 * submitting duplicate reactions (like/dislike) to one post. Such action should
 * fail with a clear error, enforcing data integrity and preventing skewed vote
 * counts. Only one like/dislike per user per post is allowed.
 *
 * Steps:
 *
 * 1. Admin creates a user profile (by email) representing the member who will
 *    react to posts.
 * 2. Admin assigns the user profile as a board member.
 * 3. The member creates a new post on the discussion board (requires a topic id).
 * 4. The member likes (or dislikes) the created post (first reaction, should
 *    succeed).
 * 5. The member attempts to like/dislike the same post a second time (should fail
 *    - error expected).
 */
export async function test_api_my_discussion_board_postLikes_test_create_duplicate_post_like_fails(
  connection: api.IConnection,
) {
  // 1. Admin creates user profile
  const email = typia.random<string & tags.Format<"email">>();
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email,
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(userProfile);

  // 2. Admin assigns userProfile as member
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userProfile.id,
        joined_at: new Date().toISOString(),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 3. Member creates a post (requires a topic id)
  const topicId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.my.discussion_board.posts.create(
    connection,
    {
      body: {
        discussion_board_topic_id: topicId,
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);
  TestValidator.equals("created post belongs to topic")(
    post.discussion_board_topic_id,
  )(topicId);

  // 4. Member creates a like on the post (should succeed)
  const likeInput = {
    discussion_board_post_id: post.id,
    is_like: true,
  } satisfies IDiscussionBoardPostLike.ICreate;
  const like = await api.functional.my.discussion_board.postLikes.create(
    connection,
    {
      body: likeInput,
    },
  );
  typia.assert(like);
  TestValidator.equals("reaction on correct post")(
    like.discussion_board_post_id,
  )(post.id);
  TestValidator.equals("reaction type matches")(like.is_like)(true);

  // 5. Attempt to like the same post a second time - should fail
  await TestValidator.error("duplicate like on same post fails")(() =>
    api.functional.my.discussion_board.postLikes.create(connection, {
      body: likeInput,
    }),
  );
}

