import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostLike";

/**
 * Validate that a member can change their reaction from a like to a dislike on
 * a post.
 *
 * This test covers the full workflow and core business logic:
 *
 * 1. Admin creates a user profile for a test user.
 * 2. Admin assigns that user as a discussion board member.
 * 3. The member creates a post in the discussion board.
 * 4. The member likes the post (is_like=true).
 * 5. The member updates their like to a dislike (is_like=false) using the update
 *    endpoint.
 * 6. Confirms the API response reflects this change and all relevant audit and
 *    schema constraints hold.
 *
 * Steps in detail:
 *
 * 1. Create user profile using the admin endpoint.
 * 2. Assign this user as a member using the admin endpoint.
 * 3. Create a new post as the member.
 * 4. Like the post (is_like=true).
 * 5. Update the like to a dislike (is_like=false) using
 *    my/discussion_board/postLikes/:id PUT.
 * 6. Confirm the updated object shows is_like=false but other record invariants
 *    hold (id, author, post, created_at).
 */
export async function test_api_discussion_board_postLikes_test_update_post_like_to_dislike_success(
  connection: api.IConnection,
) {
  // 1. Create user profile (admin)
  const userProfileInput = {
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    is_active: true,
  } satisfies IDiscussionBoardUserProfile.ICreate;

  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: userProfileInput,
      },
    );
  typia.assert(userProfile);

  // 2. Assign as member (admin)
  const memberInput = {
    discussion_board_user_profile_id: userProfile.id,
    joined_at: new Date().toISOString(),
  } satisfies IDiscussionBoardMember.ICreate;

  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: memberInput,
    },
  );
  typia.assert(member);

  // 3. Member creates a post
  const postInput = {
    discussion_board_topic_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
  } satisfies IDiscussionBoardPost.ICreate;

  const post = await api.functional.my.discussion_board.posts.create(
    connection,
    {
      body: postInput,
    },
  );
  typia.assert(post);

  // 4. Member likes the post
  const likeInput = {
    discussion_board_post_id: post.id,
    is_like: true,
  } satisfies IDiscussionBoardPostLike.ICreate;

  const like = await api.functional.my.discussion_board.postLikes.create(
    connection,
    {
      body: likeInput,
    },
  );
  typia.assert(like);
  TestValidator.equals("is_like initial true")(like.is_like)(true);
  TestValidator.equals("like belongs to post")(like.discussion_board_post_id)(
    post.id,
  );
  TestValidator.equals("like author is member")(like.author_member_id)(
    member.id,
  );

  // 5. Member updates like to dislike
  const updateLikeInput = {
    is_like: false,
  } satisfies IDiscussionBoardPostLike.IUpdate;

  const updatedLike = await api.functional.my.discussion_board.postLikes.update(
    connection,
    {
      id: like.id,
      body: updateLikeInput,
    },
  );
  typia.assert(updatedLike);

  // 6. Confirm updated state
  TestValidator.equals("is_like updated to false")(updatedLike.is_like)(false);
  TestValidator.equals("id remains stable")(updatedLike.id)(like.id);
  TestValidator.equals("post link stable")(
    updatedLike.discussion_board_post_id,
  )(post.id);
  TestValidator.equals("author stable")(updatedLike.author_member_id)(
    member.id,
  );
  TestValidator.equals("created_at unchanged")(updatedLike.created_at)(
    like.created_at,
  );
}

