 * This test verifies that a post like/dislike record can only be modified by
 * its owner. Two members are created; one creates a like, and the other
 * attempts to update it. The API must reject such modification attempts,
 * confirming correct RBAC policies.
 *
 * Steps:
 *
 * 1. Create user profiles for userA and userB.
 * 2. Assign both as discussion board members.
 * 3. As userA, create a post and like it (generates like record).
 * 4. As userB, attempt to update the like record from userA.
 * 5. Confirm that the API rejects the operation for userB, enforcing ownership.
 */
export async function test_api_my_discussion_board_postLikes_test_update_post_like_of_other_member_fails(
  connection: api.IConnection,
) {
  // 1. Create user profiles for userA and userB
  const userAProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
          registered_at: new Date().toISOString(),
        },
      },
    );
  typia.assert(userAProfile);

  const userBProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
          registered_at: new Date().toISOString(),
        },
      },
    );
  typia.assert(userBProfile);

  // 2. Assign both users as board members
  const memberA = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userAProfile.id,
        joined_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(memberA);

  const memberB = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userBProfile.id,
        joined_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(memberB);

  // 3. As userA: Create a topic (user-created posts require topic id)
  const topicId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.my.discussion_board.posts.create(
    connection,
    {
      body: {
        discussion_board_topic_id: topicId,
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      },
    },
  );
  typia.assert(post);

  // 4. As userA: create a like for the post
  const postLike = await api.functional.my.discussion_board.postLikes.create(
    connection,
    {
      body: {
        discussion_board_post_id: post.id,
        is_like: true,
      },
    },
  );
  typia.assert(postLike);

  // 5. Simulate user context switch: as userB, attempt to update the like (RBAC: should be denied)
  await TestValidator.error("ownership: only creator can update like")(
    async () => {
      await api.functional.my.discussion_board.postLikes.update(connection, {
        id: postLike.id,
        body: { is_like: false },
      });
    },
  );
}

