import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardRoleChange } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardRoleChange";
import type { IPageIDiscussionBoardRoleChange } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardRoleChange";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 관리자가 역할 변경 (role_change) 이벤트 목록을 페이징/필터링해 조회(inquiry)할 수 있는지 검증합니다.
 *
 * 이 테스트는 관리자만 접근 가능한 API에 다양한 필터 조건/페이징 파라미터를 조합해 요청할 때:
 *
 * - 조건에 맞는 데이터만 올바르게 반환하는지
 * - Page, limit, 전체 records 등 페이징 정보가 정확한지
 * - 오직 명세상 필드만(data[].id, target_user_profile_id, performed_by_user_profile_id,
 *   role_type, action_type, timestamp) 포함되는지
 * - 빈 조건, 불가능한 조건, 권한 없이/잘못된 enum 등 에러 상황에 robust하게 동작하는지 전방위적으로 검증합니다.
 *
 * Step-by-step:
 *
 * 1. 다양한 role_type/action_type/timestamp/유저 조합으로 여러 이벤트를 생성
 * 2. 각 필터별 단건/복합 쿼리 → 실제로 조건에 부합하는 데이터만 반환되는지 체크
 * 3. Page, limit 조율로 페이징 정상 동작 확인 (두 page 이상 구성)
 * 4. 빈 필터(전체 조회) 및 매칭 데이터 없는 조건 조합으로 결과가 정상 반환되는지
 * 5. 반환 객체 모든 data[].field가 명세와 strict하게 일치하는지 검증
 * 6. Admin 아닌 연결(토큰 無) 접근 시 반드시 에러가 발생하는지
 * 7. 존재하지 않는 enum값 등 invalid parameter 전달 시 에러가 발생하는지
 */
export async function test_api_admin_discussion_board_roleChanges_test_list_role_change_events_with_pagination_and_filtering(
  connection: api.IConnection,
) {
  // [1] 테스트 데이터 준비: 4건 이상 role change 생성 (각기 다른 role_type/action_type/user/timestamp)
  const now = new Date();
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const users = ArrayUtil.repeat(3)(() =>
    typia.random<string & tags.Format<"uuid">>(),
  );
  const timestamps = [
    new Date(now.getTime() - 1000 * 60 * 60 * 24 * 3).toISOString(), // 3일 전
    new Date(now.getTime() - 1000 * 60 * 60 * 24 * 2).toISOString(), // 2일 전
    new Date(now.getTime() - 1000 * 60 * 60 * 24).toISOString(), // 1일 전
    now.toISOString(),
  ];
  const ALL_ROLE_TYPES = ["admin", "moderator", "member", "guest"] as const;
  const ALL_ACTION_TYPES = ["assigned", "revoked"] as const;

  // 다양하게 섞어서 4건 이상 이벤트 생성 (role, action, 타겟유저, performer)
  const roleEvents: IDiscussionBoardRoleChange[] = [];
  for (let i = 0; i < 4; ++i) {
    const event =
      await api.functional.admin.discussion_board.roleChanges.create(
        connection,
        {
          body: {
            target_user_profile_id: users[i % users.length],
            performed_by_user_profile_id: adminId,
            role_type: ALL_ROLE_TYPES[i % ALL_ROLE_TYPES.length],
            action_type: ALL_ACTION_TYPES[i % ALL_ACTION_TYPES.length],
            timestamp: timestamps[i % timestamps.length],
          } satisfies IDiscussionBoardRoleChange.ICreate,
        },
      );
    typia.assert(event);
    roleEvents.push(event);
  }

  // [2] 각종 필터 조합 및 페이징 파라미터로 정상 데이터 쿼리 및 결과 검증

  // 2-1. role_type 필터 (예: moderator)
  const filterRole = roleEvents[1].role_type;
  const respByRole =
    await api.functional.admin.discussion_board.roleChanges.index(connection, {
      body: {
        role_type: filterRole,
      } satisfies IDiscussionBoardRoleChange.IRequest,
    });
  typia.assert(respByRole);
  for (const row of respByRole.data) {
    TestValidator.equals("role_type filter")(row.role_type)(filterRole);
  }

  // 2-2. action_type 필터 (예: assigned)
  const filterAction = roleEvents[2].action_type;
  const respByAction =
    await api.functional.admin.discussion_board.roleChanges.index(connection, {
      body: {
        action_type: filterAction,
      } satisfies IDiscussionBoardRoleChange.IRequest,
    });
  typia.assert(respByAction);
  for (const row of respByAction.data) {
    TestValidator.equals("action_type filter")(row.action_type)(filterAction);
  }

  // 2-3. performed_by_user_profile_id 필터
  const respByPerformer =
    await api.functional.admin.discussion_board.roleChanges.index(connection, {
      body: {
        performed_by_user_profile_id: adminId,
      } satisfies IDiscussionBoardRoleChange.IRequest,
    });
  typia.assert(respByPerformer);
  for (const row of respByPerformer.data) {
    TestValidator.equals("performed_by_user_profile_id filter")(
      row.performed_by_user_profile_id,
    )(adminId);
  }

  // 2-4. 복합 조건+타겟 & timestamp 범위
  const respByTargetAndTime =
    await api.functional.admin.discussion_board.roleChanges.index(connection, {
      body: {
        target_user_profile_id: roleEvents[3].target_user_profile_id,
        timestamp_from: timestamps[0],
        timestamp_to: timestamps[3],
      } satisfies IDiscussionBoardRoleChange.IRequest,
    });
  typia.assert(respByTargetAndTime);
  for (const row of respByTargetAndTime.data) {
    TestValidator.equals("target_user_profile_id filter")(
      row.target_user_profile_id,
    )(roleEvents[3].target_user_profile_id);
    // 날짜 범위
    TestValidator.predicate("timestamp_from filter")(
      new Date(row.timestamp).getTime() >= new Date(timestamps[0]).getTime(),
    );
    TestValidator.predicate("timestamp_to filter")(
      new Date(row.timestamp).getTime() <= new Date(timestamps[3]).getTime(),
    );
  }

  // 2-5. 페이징 정상 동작(2 page 구성: limit=2)
  const paging1 = await api.functional.admin.discussion_board.roleChanges.index(
    connection,
    {
      body: {
        limit: 2,
        page: 1,
      } satisfies IDiscussionBoardRoleChange.IRequest,
    },
  );
  typia.assert(paging1);
  TestValidator.equals("limit 반영")(paging1.pagination.limit)(2);
  TestValidator.equals("page 1")(paging1.pagination.current)(1);
  TestValidator.predicate("최소 2건 data")(paging1.data.length >= 1);

  const paging2 = await api.functional.admin.discussion_board.roleChanges.index(
    connection,
    {
      body: {
        limit: 2,
        page: 2,
      } satisfies IDiscussionBoardRoleChange.IRequest,
    },
  );
  typia.assert(paging2);
  TestValidator.equals("limit 반영")(paging2.pagination.limit)(2);
  TestValidator.equals("page 2")(paging2.pagination.current)(2);
  // 두번째 데이터셋이 첫번째와 달라야 의미 있음. (완전히 일치할 필요까지 없음)
  TestValidator.notEquals("페이지 데이터 다름")(paging1.data)(paging2.data);

  // [3] 반환 data 스키마 strict 검증 (불필요한 필드 등 금지)
  for (const page of [
    respByRole,
    respByAction,
    respByPerformer,
    respByTargetAndTime,
    paging1,
    paging2,
  ]) {
    for (const row of page.data) {
      const actualKeys = Object.keys(row).sort();
      const expectedKeys = [
        "id",
        "target_user_profile_id",
        "performed_by_user_profile_id",
        "role_type",
        "action_type",
        "timestamp",
      ].sort();
      TestValidator.equals("명세상 필드만 존재")(actualKeys)(expectedKeys);
    }
  }

  // [4] 빈 필터 – 전체 데이터 반환
  const respAll = await api.functional.admin.discussion_board.roleChanges.index(
    connection,
    {
      body: {} satisfies IDiscussionBoardRoleChange.IRequest,
    },
  );
  typia.assert(respAll);
  TestValidator.predicate("전체 개수=생성된 갯수 이상")(
    respAll.data.length >= roleEvents.length,
  );

  // [5] 존재하지 않는 조합(임의 UUID, impossible filter 등) → 빈 배열
  const impossibleFilter =
    await api.functional.admin.discussion_board.roleChanges.index(connection, {
      body: {
        target_user_profile_id: typia.random<string & tags.Format<"uuid">>(),
        role_type: "admin",
        action_type: "revoked",
        timestamp_from: new Date(
          now.getTime() + 1000 * 60 * 60 * 24,
        ).toISOString(), // 미래
      } satisfies IDiscussionBoardRoleChange.IRequest,
    });
  typia.assert(impossibleFilter);
  TestValidator.equals("불가능한 filter시 결과 없음")(
    impossibleFilter.data.length,
  )(0);

  // [6] 인증 없이 접근 시 반드시 에러 발생
  const unauthenticatedConn = { ...connection, headers: {} };
  await TestValidator.error("admin 인증없음 오류")(() =>
    api.functional.admin.discussion_board.roleChanges.index(
      unauthenticatedConn,
      {
        body: {} satisfies IDiscussionBoardRoleChange.IRequest,
      },
    ),
  );

  // [7] 존재하지 않는 enum 등 invalid parameter 전달 시 에러 발생
  await TestValidator.error("role_type 잘못된 enum")(async () =>
    api.functional.admin.discussion_board.roleChanges.index(connection, {
      // @ts-expect-error: 테스트 의도 (타입 침범 금지하지만 실제 런타임 검증)
      body: { role_type: "not_real_enum" },
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardRoleChange } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardRoleChange";

/**
 * Validate fetching a role change event by id as admin.
 *
 * Ensures audit and compliance traceability by confirming that:
 *
 * 1. An admin can create a new role change event with valid input.
 * 2. The role change event can be fetched by id and all fields match the original
 *    creation payload.
 * 3. Non-admin access to the same endpoint is denied (RBAC enforced).
 *
 * Steps:
 *
 * 1. Generate a role change event payload using valid random values.
 * 2. Create the event via admin endpoint.
 * 3. Fetch the newly created event by its id as admin and validate all response
 *    fields.
 * 4. Attempt fetch as non-admin and confirm access rejection.
 */
export async function test_api_admin_discussion_board_roleChanges_test_retrieve_role_change_event_by_valid_id(
  connection: api.IConnection,
) {
  // 1. Generate a valid new role change event input
  const eventCreateInput: IDiscussionBoardRoleChange.ICreate = {
    target_user_profile_id: typia.random<string & tags.Format<"uuid">>(),
