 *
 * This test verifies that a topic cannot be created under a category where
 * is_active is false.
 *
 * Steps:
 *
 * 1. Using admin APIs, create a new discussion board category with is_active: true
 * 2. Create a user profile and assign it as a board member.
 * 3. Use the admin API to update the category's is_active: false.
 * 4. Attempt to create a topic in this now-inactive category as the board member
 *    (via my/discussion_board/topics)
 * 5. Validate that the operation fails with proper error response/exception.
 *
 * The purpose is to ensure business rule: ONLY active categories can have new
 * topic creation.
 */
export async function test_api_my_discussion_board_topics_test_create_topic_with_inactive_category_fails(
  connection: api.IConnection,
) {
  // 1. Create a new category (active=true initially)
  const category =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: {
