/**
 * Validate that topic creation fails when required fields are missing (as
 * allowed by type safety).
 *
 * Ensures the topic creation endpoint does NOT allow creation with invalid or
 * obviously unacceptable values for required fields. By business rules,
 * required string fields may be empty (valid TypeScript, but should be rejected
 * at runtime), so we test such cases.
 *
 * Steps:
 *
 * 1. Create discussion board category (admin)
 * 2. Create user profile (admin)
 * 3. Assign user as a member (admin)
 * 4. Attempt to create a topic as the member with empty strings for required
 *    fields and expect validation errors
 * 5. Confirm error is thrown (runtime validation error) in all cases
 */
export async function test_api_my_test_create_topic_missing_required_fields_fails(
  connection: api.IConnection,
) {
  // 1. Create discussion board category as admin
  const category =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.paragraph()(1),
        description: RandomGenerator.paragraph()(1),
        sort_order: 1,
        is_active: true,
      } satisfies IDiscussionBoardCategory.ICreate,
    });
  typia.assert(category);

  // 2. Create user profile as admin
  const profile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
