      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 4. Test topic creation with empty required values
  // (Cannot omit required keys at type level, but can test invalid empty values)
  const base: IDiscussionBoardTopic.ICreate = {
    discussion_board_category_id: category.id,
    title: RandomGenerator.paragraph()(1),
    description: RandomGenerator.content()()(),
