import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostLike";

/**
 * Test authorized deletion of a user's own post like/dislike entry by ID.
 *
 * This test ensures that a member (user profile) can delete a like/dislike
 * record they created on any post, and that this action properly removes the
 * record from the system. It also checks that subsequent attempts to access the
 * deleted entry fail as expected. The end-to-end flow covers full setup,
 * action, verification, and deletion validation.
 *
 * 1. Admin creates a user profile
 * 2. Admin assigns user profile as a discussion board member
 * 3. Member creates a post
 * 4. Member likes/dislikes their own post
 * 5. Verify the like/dislike entry exists
 * 6. Member deletes their own like/dislike via API
 * 7. Attempt to delete again or fetch entry to confirm removal (should error)
 */
export async function test_api_discussion_board_postLikes_test_delete_own_post_like_with_valid_id(
  connection: api.IConnection,
) {
  // 1. Admin creates a user profile
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(userProfile);

  // 2. Admin assigns user profile as a discussion board member
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userProfile.id,
        joined_at: new Date().toISOString(),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 3. Member creates a post (using their member context)
  // We assume any topic id will suffice for test; generate one
  const topicId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.my.discussion_board.posts.create(
    connection,
    {
      body: {
        discussion_board_topic_id: topicId,
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 4. Member likes their own post
  const postLike = await api.functional.my.discussion_board.postLikes.create(
    connection,
    {
      body: {
        discussion_board_post_id: post.id,
        is_like: true,
      } satisfies IDiscussionBoardPostLike.ICreate,
    },
  );
  typia.assert(postLike);

  // 5. Verify the like/dislike entry exists (already done by previous step: postLike)
  TestValidator.equals("Like record post id matches")(
    postLike.discussion_board_post_id,
  )(post.id);
  TestValidator.equals("Like record author matches")(postLike.author_member_id)(
    member.id,
  );

  // 6. Member deletes their own like/dislike
  await api.functional.my.discussion_board.postLikes.erase(connection, {
    id: postLike.id,
  });

  // 7. Attempt to delete again or fetch entry to confirm removal (should error)
  await TestValidator.error("deleting again fails")(() =>
    api.functional.my.discussion_board.postLikes.erase(connection, {
      id: postLike.id,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
