import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostLike";

/**
 * 검증: 다른 사용자가 생성한 게시글 좋아요/싫어요 레코드를 삭제할 수 없는지 확인하는 시나리오.
 *
 * 이 테스트는 두 명의 사용자와 두 개의 멤버십을 만들어, 첫 번째 사용자가 게시글을 작성 ▶ 좋아요를 누름 ▶ 두 번째 사용자가 그 좋아요
 * 레코드 삭제 시도 ▶ 실제로는 권한 오류 (Forbidden 등)가 발생해야 함을 검증합니다.
 *
 * 실제 환경에서는 인증 컨텍스트(로그인/세션 전환) API가 필요하나, 본 테스트에서는 인증 전환을 주석과 가정으로 처리합니다.
 *
 * **테스트 시나리오:**
 *
 * 1. 관리자 권한으로 두 개의 사용자 프로필 생성
 * 2. 두 사용자 모두 멤버로 지정
 * 3. 첫 번째 사용자가(컨텍스트) 게시글 작성
 * 4. 첫 번째 사용자가 게시글에 좋아요 남김
 * 5. 두 번째 사용자가(컨텍스트) 첫번째 사용자의 좋아요 삭제 시도(권한 에러 발생해야 함)
 */
export async function test_api_discussion_board_postLikes_test_delete_post_like_not_owned_by_user(
  connection: api.IConnection,
) {
  // 1. 관리자 권한으로 두 명의 사용자 프로필 생성
  const user1Profile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(user1Profile);

  const user2Profile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(user2Profile);

  // 2. 두 사용자 모두를 멤버로 지정
  const now = new Date().toISOString();
  const user1Member =
    await api.functional.admin.discussion_board.members.create(connection, {
      body: {
        discussion_board_user_profile_id: user1Profile.id,
        joined_at: now,
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(user1Member);
  const user2Member =
    await api.functional.admin.discussion_board.members.create(connection, {
      body: {
        discussion_board_user_profile_id: user2Profile.id,
        joined_at: now,
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(user2Member);

  // 3. user1으로 인증된 상태에서 게시글 작성 (컨텍스트 전환 주석 처리)
  // (실제 구현에서는 user1 인증 세션 사용 필요)
  const topicId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.my.discussion_board.posts.create(
    connection,
    {
      body: {
        discussion_board_topic_id: topicId,
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 4. user1이 해당 게시글에 좋아요 남김
  const like = await api.functional.my.discussion_board.postLikes.create(
    connection,
    {
      body: {
        discussion_board_post_id: post.id,
        is_like: true,
      } satisfies IDiscussionBoardPostLike.ICreate,
    },
  );
  typia.assert(like);

  // 5. user2로 인증된 상태에서 첫 번째 사용자의 좋아요 삭제 시도 (컨텍스트 전환 주석 처리)
  // 실제 환경에서는 user2 인증 세션 필요
  await TestValidator.error("타인이 남긴 좋아요/싫어요 삭제 차단됨")(
    async () => {
      await api.functional.my.discussion_board.postLikes.erase(connection, {
        id: like.id,
      });
    },
  );
}

