import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopic";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";

/**
 * 게시글 ID로 게시글 상세 조회 기능을 검증한다.
 *
 * 1. 관리자 권한으로 새로운 사용자 프로필을 생성한다.
 * 2. 방금 생성한 사용자에게 멤버 권한을 부여한다.
 * 3. 토픽을 등록할 카테고리를 생성한다.
 * 4. 회원 권한(생성한 멤버)으로 해당 카테고리에 토픽을 생성한다.
 * 5. 회원 권한으로 생성한 토픽에 게시글(Post)을 작성한다.
 * 6. 게시글의 고유 ID로 상세 조회 API를 호출한다.
 * 7. 반환된 게시글 객체의 모든 스키마 필드가 게시글 생성 시점 정보와 일치하는지 검증한다.
 */
export async function test_api_discussion_board_posts_test_get_post_by_id_with_valid_post(
  connection: api.IConnection,
) {
  // 1. 관리자 권한으로 새로운 사용자 프로필 생성
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
          registered_at: new Date().toISOString(),
        },
      },
    );
  typia.assert(userProfile);

  // 2. 방금 생성한 사용자에게 멤버 권한 부여
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userProfile.id,
        joined_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(member);

  // 3. 토픽을 등록할 카테고리 생성
  const category =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.paragraph()(2),
        description: RandomGenerator.content()()(),
        sort_order: typia.random<number & tags.Type<"int32">>(),
        is_active: true,
      },
    });
  typia.assert(category);

  // 4. 회원 권한(생성한 멤버)으로 해당 카테고리에 토픽 생성
  // 실제 인증처리 관련 추가로 필요시 별도 구현 필요(스펙 미공개 시 생략)
  const topic = await api.functional.my.discussion_board.topics.create(
    connection,
    {
      body: {
        discussion_board_category_id: category.id,
        title: RandomGenerator.paragraph()(1),
        description: RandomGenerator.content()()(),
        status: "open",
        pinned_at: null,
        closed_at: null,
      },
    },
  );
  typia.assert(topic);

  // 5. 회원 권한으로 생성한 토픽에 게시글(Post) 작성
  const postCreateBody = {
    discussion_board_topic_id: topic.id,
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()(),
  } satisfies IDiscussionBoardPost.ICreate;
  const createdPost = await api.functional.my.discussion_board.posts.create(
    connection,
    {
      body: postCreateBody,
    },
  );
  typia.assert(createdPost);

  // 6. 게시글의 고유 ID로 상세조회 API 호출
  const fetchedPost = await api.functional.discussion_board.posts.at(
    connection,
    {
      id: createdPost.id,
    },
  );
  typia.assert(fetchedPost);

  // 7. 반환된 게시글의 모든 주요스키마 필드가 일치하는지 검증
  TestValidator.equals("id")(fetchedPost.id)(createdPost.id);
  TestValidator.equals("discussion_board_topic_id")(
    fetchedPost.discussion_board_topic_id,
  )(createdPost.discussion_board_topic_id);
  TestValidator.equals("author_member_id")(fetchedPost.author_member_id)(
    createdPost.author_member_id,
  );
  TestValidator.equals("title")(fetchedPost.title)(createdPost.title);
  TestValidator.equals("body")(fetchedPost.body)(createdPost.body);
  TestValidator.equals("is_deleted")(fetchedPost.is_deleted)(
    createdPost.is_deleted,
  );
  TestValidator.equals("created_at")(fetchedPost.created_at)(
    createdPost.created_at,
  );
  TestValidator.equals("updated_at")(fetchedPost.updated_at)(
    createdPost.updated_at,
  );
}

