import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopic";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";

/**
 * Validate API rejects post creation with missing required fields.
 *
 * This test ensures the discussion board post creation endpoint enforces
 * required schema fields—specifically, topic ID and post body—by verifying
 * that:
 *
 * - Attempts to create a post without the required `discussion_board_topic_id` or
 *   `body` properties fail with validation errors, and no resource is created.
 *
 * Preparation steps:
 *
 * 1. Create a user profile via admin API (representing the post author).
 * 2. Assign that user profile as a board member via admin API.
 * 3. Create a category as admin for the topic to belong to.
 * 4. Create a topic under the created category, establishing a valid topic context
 *    and member session.
 *
 * Test procedure:
 *
 * - Attempt to create a post omitting the required topic ID field (should fail
 *   validation).
 * - Attempt to create a post omitting the required body field (should fail
 *   validation).
 * - In both negative cases, confirm the API returns a validation error and does
 *   not create a post resource.
 *
 * Note: These negative validation checks require bypassing TypeScript type
 * safety in the test payload with `as any`, as it's not possible to
 * intentionally omit required properties using standard DTO interfaces. This is
 * only done to simulate API input errors that would arise at runtime.
 */
export async function test_api_discussion_board_test_create_post_with_missing_required_fields(
  connection: api.IConnection,
) {
  // 1. Admin creates a user profile
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(userProfile);

  // 2. Admin assigns the user as a board member
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userProfile.id,
        joined_at: new Date().toISOString(),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 3. Admin creates a category
  const category =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: RandomGenerator.alphabets(8),
        name: RandomGenerator.name(),
        sort_order: 1,
        is_active: true,
      } satisfies IDiscussionBoardCategory.ICreate,
    });
  typia.assert(category);

  // 4. Member creates a topic under the category
  const topic = await api.functional.my.discussion_board.topics.create(
    connection,
    {
      body: {
        discussion_board_category_id: category.id,
        title: RandomGenerator.paragraph()(),
        description: RandomGenerator.content()()(),
        status: "open",
      } satisfies IDiscussionBoardTopic.ICreate,
    },
  );
  typia.assert(topic);

  // Negative validation test 1: Omit discussion_board_topic_id
  await TestValidator.error("missing required topic ID fails")(async () => {
    await api.functional.my.discussion_board.posts.create(connection, {
      body: {
        body: "Test body content.",
      } as any, // Intentionally omit discussion_board_topic_id
    });
  });

  // Negative validation test 2: Omit body
  await TestValidator.error("missing required body fails")(async () => {
    await api.functional.my.discussion_board.posts.create(connection, {
      body: {
        discussion_board_topic_id: topic.id,
      } as any, // Intentionally omit body
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
