import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";

/**
 * 검증: 보드 멤버로 할당되지 않은 사용자는 게시글 생성 권한이 없다.
 *
 * 이 테스트는 논의 게시판 시스템에서 멤버로 등록되지 않은 사용자가 게시글 생성
 * API(`/my/discussion_board/posts`)를 호출할 경우 허가 오류로 인해 거부되는지 확인한다.
 *
 * 시나리오:
 *
 * 1. (어드민) 사용자 프로필을 생성한다.
 * 2. (어드민) 논의 카테고리를 생성한다.
 * 3. (비멤버 사용자로 인증) 해당 카테고리 하위에 토픽을 생성한다.
 * 4. (비멤버 사용자로 인증) 생성한 토픽에 게시글(포스트) 작성 시도를 한다 — API는 권한 오류/거부로 실패해야 한다.
 *
 * 기대결과:
 *
 * - 4단계에서 실제로 포스트가 생성되지 않고, 권한(permisson) 관련 오류가 발생해야 한다.
 */
export async function test_api_discussion_board_test_create_post_as_non_member_permission_denied(
  connection: api.IConnection,
) {
  // 1. 어드민에서 사용자 프로필 생성
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(userProfile);

  // 2. 어드민에서 논의 카테고리 생성
  const category =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.paragraph()(3),
        sort_order: typia.random<number & tags.Type<"int32">>(),
        is_active: true,
        description: RandomGenerator.paragraph()(2),
      } satisfies IDiscussionBoardCategory.ICreate,
    });
  typia.assert(category);

  // 3. (비멤버 사용자로 인증) 해당 카테고리에서 토픽 생성
  const topic = await api.functional.my.discussion_board.topics.create(
    connection,
    {
      body: {
        discussion_board_category_id: category.id,
        title: RandomGenerator.paragraph()(2),
        description: RandomGenerator.content()()(),
        status: "open",
      } satisfies IDiscussionBoardTopic.ICreate,
    },
  );
  typia.assert(topic);

  // 4. (비멤버 사용자로 인증) 생성한 토픽에 게시글(포스트) 작성 시도 — 권한 오류/거부여야 함
  await TestValidator.error("비멤버로 게시글 생성 불가(권한 거부)")(() =>
    api.functional.my.discussion_board.posts.create(connection, {
      body: {
        discussion_board_topic_id: topic.id,
        body: RandomGenerator.content()()(),
        title: RandomGenerator.paragraph()(1),
      } satisfies IDiscussionBoardPost.ICreate,
    }),
  );
}

