import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopic";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";

/**
 * Test successful updating of a member's own discussion board post.
 *
 * This test validates the ability for a board member to update their own post's
 * title and body. It covers the complete workflow: create user profile, assign
 * as board member, create a category, create a topic (as the member), create a
 * post under that topic, and then update the post with new title and body.
 * Finally, confirms the updated post's fields are persisted.
 *
 * Steps:
 *
 * 1. Create a user profile (admin).
 * 2. Assign user profile as a board member (admin).
 * 3. Create a discussion board category (admin).
 * 4. Create a topic as the board member under that category.
 * 5. Create a post as the board member in the topic.
 * 6. Update the post's title and body using the update endpoint as the same
 *    member.
 * 7. Assert all changes persist and are correctly returned from the API.
 */
export async function test_api_my_discussion_board_posts_test_update_own_post_successfully(
  connection: api.IConnection,
) {
  // 1. Create user profile (admin)
  const email = typia.random<string & tags.Format<"email">>();
  const displayName = RandomGenerator.name();
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email,
          display_name: displayName,
          is_active: true,
          registered_at: new Date().toISOString(),
        },
      },
    );
  typia.assert(userProfile);

  // 2. Assign user profile as board member (admin)
  const joinTime = new Date().toISOString();
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userProfile.id,
        joined_at: joinTime,
      },
    },
  );
  typia.assert(member);

  // 3. Create a discussion board category (admin)
  const categoryCode = RandomGenerator.alphaNumeric(8);
  const categoryName = RandomGenerator.paragraph()(1, 3);
  const category =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: categoryCode,
        name: categoryName,
        sort_order: 1,
        is_active: true,
        description: RandomGenerator.paragraph()(),
      },
    });
  typia.assert(category);

  // 4. Create a topic as the board member under the new category
  const topic = await api.functional.my.discussion_board.topics.create(
    connection,
    {
      body: {
        discussion_board_category_id: category.id,
        title: RandomGenerator.paragraph()(1, 2),
        description: RandomGenerator.content()()(),
        status: "open",
        pinned_at: null,
        closed_at: null,
      },
    },
  );
  typia.assert(topic);

  // 5. Create a post as the member in the topic
  const initialTitle = RandomGenerator.paragraph()(1, 1);
  const initialBody = RandomGenerator.content()()();
  const post = await api.functional.my.discussion_board.posts.create(
    connection,
    {
      body: {
        discussion_board_topic_id: topic.id,
        title: initialTitle,
        body: initialBody,
      },
    },
  );
  typia.assert(post);

  // 6. Update the post's title and body as the same member
  const updatedTitle = RandomGenerator.paragraph()(1, 1);
  const updatedBody = RandomGenerator.content()()();
  const updatedPost = await api.functional.my.discussion_board.posts.update(
    connection,
    {
      id: post.id,
      body: {
        title: updatedTitle,
        body: updatedBody,
      },
    },
  );
  typia.assert(updatedPost);

  // 7. Assert the changes persisted and are reflected in the updated post
  TestValidator.equals("title changed")(updatedPost.title)(updatedTitle);
  TestValidator.equals("body changed")(updatedPost.body)(updatedBody);
  TestValidator.equals("post id unchanged")(updatedPost.id)(post.id);
  TestValidator.equals("topic id unchanged")(
    updatedPost.discussion_board_topic_id,
  )(post.discussion_board_topic_id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopic";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";

/**
 * Validate that a member cannot update a post authored by another member.
 *
 * This test covers the following scenario:
 *
 * 1. Admin creates two distinct user profiles (Member A and Member B).
 * 2. Admin assigns both user profiles as board members.
 * 3. Admin creates a category for discussion topics.
 * 4. Member A creates a topic in the category.
 * 5. Member A creates a post in the topic.
 * 6. Member B attempts to update Member A's post via the update API.
 * 7. The update should fail with a permission error, and the post should remain
 *    unchanged.
 *
 * Steps:
 *
 * 1. Create two user profiles and assign as members (admin functions).
 * 2. Create a category (admin function).
 * 3. As Member A, create a topic in the new category.
 * 4. As Member A, create a post in the topic.
 * 5. As Member B (using their connection), attempt to update Member A's post;
 *    expect error.
 * 6. Optionally, fetch the post and assert its data is unchanged after the failed
 *    update.
 */
export async function test_api_my_discussion_board_posts_test_update_post_not_owned_permission_denied(
  connection: api.IConnection,
) {
  // 1. Create two user profiles as admin (simulate Member A and Member B)
  const userAProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(userAProfile);

  const userBProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(userBProfile);

  // 2. Assign both user profiles as board members
  const memberA = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userAProfile.id,
        joined_at: new Date().toISOString(),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(memberA);

  const memberB = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userBProfile.id,
        joined_at: new Date().toISOString(),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(memberB);

  // 3. Create a category
  const category =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.name(),
        description: RandomGenerator.paragraph()(),
        sort_order: 1,
        is_active: true,
      } satisfies IDiscussionBoardCategory.ICreate,
    });
  typia.assert(category);

  // 4. Member A creates a topic in the category
  // In a real system, you would switch context to Member A. Here, we use a single connection for illustration.
  const topic = await api.functional.my.discussion_board.topics.create(
    connection,
    {
      body: {
        discussion_board_category_id: category.id,
        title: RandomGenerator.paragraph()(),
        description: RandomGenerator.content()()(),
        status: "open",
      } satisfies IDiscussionBoardTopic.ICreate,
    },
  );
  typia.assert(topic);

  // 5. Member A creates a post in the topic
  const post = await api.functional.my.discussion_board.posts.create(
    connection,
    {
      body: {
        discussion_board_topic_id: topic.id,
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 6. Member B attempts to update Member A's post (should fail)
  // (In a real system, switch context to Member B)
  await TestValidator.error("Permission denied for non-owner update")(
    async () => {
      await api.functional.my.discussion_board.posts.update(connection, {
        id: post.id,
        body: {
          title: "Malicious Edit Attempt",
          body: "This edit should not succeed.",
        } satisfies IDiscussionBoardPost.IUpdate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopic";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";

/**
 * Validate update attempts with invalid data for a discussion board post are
 * rejected and do not alter content.
 *
 * This test ensures that the update endpoint for discussion board posts
 * correctly rejects update requests when provided invalid input, such as
 * supplying only immutable fields, sending unrecognized properties, or omitting
 * all updatable fields. The test checks that a validation error is thrown and
 * the original post data remains unchanged after each failed attempt.
 *
 * Steps:
 *
 * 1. Admin creates a user profile for the member.
 * 2. Admin assigns the profile as a discussion board member.
 * 3. Admin registers a category for the test.
 * 4. The member creates a topic in this category.
 * 5. The member posts a message in this topic.
 * 6. Various invalid updates are attempted on the post using
 *    /my/discussion_board/posts/{id} (PUT):
 *
 *    - A) Input contains only immutable fields (should fail)
 *    - B) Input has unrecognized fields (should fail)
 *    - C) Body is an empty object (should fail) For each, it is verified that a
 *         validation error is thrown, and the state of the post is unchanged.
 */
export async function test_api_my_discussion_board_posts_test_update_post_with_invalid_input(
  connection: api.IConnection,
) {
  // 1. Admin creates a user profile
  const profile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
          // registered_at is optional
        },
      },
    );
  typia.assert(profile);

  // 2. Admin assigns as discussion board member
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: profile.id,
        joined_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(member);

  // 3. Admin creates a category
  const category =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(6),
        name: RandomGenerator.alphabets(8),
        sort_order: 1,
        is_active: true,
        // description can be omitted
      },
    });
  typia.assert(category);

  // 4. Member creates a topic
  const topic = await api.functional.my.discussion_board.topics.create(
    connection,
    {
      body: {
        discussion_board_category_id: category.id,
        title: RandomGenerator.paragraph()(8),
        description: RandomGenerator.content()(2)(2),
        status: "open",
        // pinned_at and closed_at are optional
      },
    },
  );
  typia.assert(topic);

  // 5. Member creates a post
  const post = await api.functional.my.discussion_board.posts.create(
    connection,
    {
      body: {
        discussion_board_topic_id: topic.id,
        title: RandomGenerator.alphabets(12),
        body: RandomGenerator.content()(2)(4),
      },
    },
  );
  typia.assert(post);

