 * 5. UserA then creates a post in the topic.
 * 6. UserB signs in (profile switch) and attempts to soft-delete UserA's post.
 *
 *    - This should result in a permission error.
 * 7. (Optional) Attempting to verify is_deleted status requires a get-by-id which
 *    is not present in provided APIs, so omitted.
 */
export async function test_api_my_discussion_board_posts_test_soft_delete_post_not_owned_permission_denied(
  connection: api.IConnection,
) {
  // 1. Admin creates user profile for UserA
  const userAProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
