/**
 * 게시글 편집 이력(스냅샷) 조회 및 페이징 검증 시나리오
 *
 * 본 테스트는 다음을 모두 검증합니다:
 *
 * - 게시글 ID별로 edit 스냅샷 목록이 정상 생성/조회되는가
 * - 여러 차례 수정, soft-delete를 거친 이력 전체가 페이징에 맞게 올바르게 조회되는가
 * - 반환 데이터는 타입 안정성이 보장되고, 정렬 순서(최신순)의 일관성이 유지되는가
 * - 페이지네이션 meta(현재 페이지/limit/전체 수)가 기대대로 동작하는가
 *
 * 절차:
 *
 * 1. 관리자가 유저 프로필을 생성
 * 2. 해당 유저를 게시판 멤버로 등록
 * 3. 카테고리를 생성
 * 4. 멤버가 토픽 생성
 * 5. 멤버가 게시글 작성
 * 6. 멤버가 동일 게시글 2회 연속 수정
 * 7. 멤버가 게시글을 soft delete (is_deleted)
 * 8. Post_id로 스냅샷 목록을 페이지 단위로 2페이지 이상 조회
 * 9. 각 페이지 결과의 갯수, 정렬, pagination 메타, 데이터 적합성 일괄 검증
 */
export async function test_api_discussion_board_test_list_post_snapshots_by_post_id_paginated(
  connection: api.IConnection,
) {
  // 1. 관리자 - 테스트 유저 생성
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
          registered_at: new Date().toISOString(),
        },
      },
