import type { IDiscussionBoardTopicSubscription } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopicSubscription";

/**
 * Test subscribing to a discussion topic as an authenticated member using a
 * valid topic ID.
 *
 * Business context: To subscribe a member to a topic, first an admin creates a
 * user profile, assigns the profile as a board member, registers a new
 * category, and the member (profile) creates a topic. Only then can the member
 * subscribe to a topic for notifications. This workflow validates not just
 * endpoint success, but also that all dependency user and topic creations are
 * enforced.
 *
 * Step-by-step process:
 *
 * 1. Admin creates a user profile with unique email and display name.
 * 2. Admin assigns the user profile as a discussion board member, specifying join
 *    time.
 * 3. Admin creates a new discussion board category for topic association.
 * 4. The member creates a new topic in the created category (using
 *    /my/discussion_board/topics).
 * 5. The authenticated member/subscriber calls
 *    /my/discussion_board/topicSubscriptions with the created topic's ID.
 * 6. Validate the returned subscription object: correct topic reference, correct
 *    member, subscribed_at uses a valid ISO string (now or soon after),
 *    unsubscribed_at is null, and all expected fields are present.
 */
export async function test_api_discussion_board_test_create_topic_subscription_with_valid_topic_id(
  connection: api.IConnection,
) {
  // 1. Admin creates a user profile
  const email = typia.random<string & tags.Format<"email">>();
  const displayName = RandomGenerator.name();
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: email,
          display_name: displayName,
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(userProfile);

  // 2. Admin assigns the user profile as a discussion board member
  const joinedAt = new Date().toISOString();
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userProfile.id,
        joined_at: joinedAt,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 3. Admin creates a discussion board category
  const category =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(12),
        name: RandomGenerator.paragraph()(1),
        description: RandomGenerator.content()()(),
        sort_order: 1,
        is_active: true,
      } satisfies IDiscussionBoardCategory.ICreate,
    });
  typia.assert(category);

  // 4. Member creates a new topic within the category (simulate as the member; likely via auth context on /my API)
  // For the test we assume that performing the POST below utilizes the member role generated previously.
  const topic = await api.functional.my.discussion_board.topics.create(
    connection,
    {
      body: {
        discussion_board_category_id: category.id,
        title: RandomGenerator.paragraph()(1),
        description: RandomGenerator.content()()(),
        status: "open",
      } satisfies IDiscussionBoardTopic.ICreate,
    },
  );
  typia.assert(topic);

  // 5. The member subscribes to the topic
  const subscription =
    await api.functional.my.discussion_board.topicSubscriptions.create(
      connection,
      {
        body: {
          discussion_board_topic_id: topic.id,
        } satisfies IDiscussionBoardTopicSubscription.ICreate,
      },
    );
  typia.assert(subscription);

  // 6. Validate the result
  TestValidator.equals("topic id in subscription")(
    subscription.discussion_board_topic_id,
  )(topic.id);
  TestValidator.equals("member id matches")(subscription.member_id)(member.id);
  TestValidator.equals("subscribed_at is ISO string")(
    typeof subscription.subscribed_at === "string",
  )(true);
  TestValidator.equals("unsubscribed_at is null")(subscription.unsubscribed_at)(
    null,
  );
  TestValidator.predicate("id is uuid")(
    typeof subscription.id === "string" &&
      /^[0-9a-f\-]{36}$/i.test(subscription.id),
  );
}

