/**
 * Validate that listing posts when no posts exist returns an empty array.
 *
 * This test checks the edge case where the database contains no posts. The
 * posts listing endpoint should return an empty data array and correct
 * pagination metadata.
 *
 * Steps:
 *
 * 1. Without creating any posts, call the posts listing endpoint with an empty
 *    filter.
 * 2. Assert that the returned data array is empty.
 * 3. Check that the pagination metadata reflects zero records and only one page.
 */
export async function test_api_discussion_board_test_list_posts_when_no_posts_exist(
  connection: api.IConnection,
) {
  // 1. Call the posts list endpoint with no filters (empty DB assumed)
  const output = await api.functional.discussion_board.posts.index(connection, {
    body: {},
  });
  typia.assert(output);

  // 2. Data array must be empty
  TestValidator.equals("empty posts array")(output.data)([]);
