 *
 * 각 경우별로 TestValidator.error로 시스템 응답이 정상적으로 오류를 반환하는지만 검증합니다. 시스템이 크래시되거나 무응답하지
 * 않고 예상대로 동작하는지 확인합니다.
 */
export async function test_api_discussion_board_posts_index_with_invalid_pagination_parameters(
  connection: api.IConnection,
) {
  // 1. page 값이 유효 범위 미만일 때 오류 검증 (page: 0)
  await TestValidator.error("page가 0일 때 오류 반환")(() =>
    api.functional.discussion_board.posts.index(connection, {
      body: {
        page: 0,
        limit: 10,
      },
    }),
  );

  // 2. page 값이 음수일 때 오류 검증 (page: -1)
  await TestValidator.error("page가 음수일 때 오류 반환")(() =>
    api.functional.discussion_board.posts.index(connection, {
      body: {
        page: -1,
        limit: 10,
      },
    }),
  );

  // 3. limit 값이 유효 범위 미만일 때 오류 검증 (limit: 0)
  await TestValidator.error("limit이 0일 때 오류 반환")(() =>
    api.functional.discussion_board.posts.index(connection, {
      body: {
        page: 1,
        limit: 0,
      },
    }),
  );

  // 4. limit 값이 음수일 때 오류 검증 (limit: -5)
  await TestValidator.error("limit이 음수일 때 오류 반환")(() =>
    api.functional.discussion_board.posts.index(connection, {
      body: {
        page: 1,
        limit: -5,
      },
    }),
  );
}

