import type { IDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopic";

/**
 * Validate that a member can update their own topic with valid data.
 *
 * This comprehensive test simulates a real workflow in which:
 *
 * 1. An admin creates a user profile (simulating user onboarding).
 * 2. The user is assigned as a discussion board member (admin action).
 * 3. The member creates a new topic under their account.
 * 4. The member updates the topic's title and description fields.
 *
 * This test validates:
 *
 * - That the user profile and member assignment processes complete successfully.
 * - Topic creation as the member is properly attributed to them.
 * - Topic update with allowed fields (title, description) is accepted and
 *   reflected in the returned data.
 * - The last_edited_by_member_id field is set after editing.
 * - Only permitted fields (title, description) are changed; immutable fields
 *   remain unchanged.
 * - All data conforms to DTO types and business rules.
 *
 * Steps:
 *
 * 1. Create user profile via admin API (userProfile).
 * 2. Assign user profile as member (member).
 * 3. (Assumed: switch to member context.)
 * 4. Member creates a topic (topic).
 * 5. Member updates topic's title/description (updated).
 * 6. Assert updates took effect, last_edited_by_member_id present, immutable
 *    fields unchanged.
 */
export async function test_api_my_discussion_board_topics_test_update_own_topic_with_valid_data(
  connection: api.IConnection,
) {
