import type { IPageIDiscussionBoardTopicSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardTopicSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 토픽 스냅샷 목록 조회 API의 잘못된 조건 검증 테스트
 *
 * 이 테스트는 /discussion_board/topicSnapshots PATCH 엔드포인트에 다양한 잘못된 입력(포맷 오류, 타입 오류,
 * 논리적으로 존재하지 않는 값 등)을 전달하여 서버가 입력값 유효성 검증에 실패할 때 적절한 오류(예: 400) 또는 빈 배열 반환을 바르게
 * 처리하는지 검사합니다.
 *
 * - 잘못된 discussion_board_topic_id/edited_by_member_id에 포맷 오류(비UUID) 입력
 * - 올바른 UUID 포맷이나 존재하지 않는 id 입력(빈 배열 검증)
 * - Page/limit에 1 미만 숫자, 문자열 등 타입 오류 입력
 * - Created_from/created_to에 잘못된 날짜형/숫자 입력
 *
 * 각 상황별로 TestValidator.error(오류 발생) 또는 빈 결과(data: [])임을 assert로 검증합니다.
 */
export async function test_api_discussion_board_test_list_topic_snapshots_with_invalid_filter(
  connection: api.IConnection,
) {
  // 1. discussion_board_topic_id에 UUID 포맷이 아닌 임의 문자열 전송 → 오류
  await TestValidator.error("discussion_board_topic_id 잘못된 포맷")(
    async () => {
      await api.functional.discussion_board.topicSnapshots.index(connection, {
        body: { discussion_board_topic_id: "NOT_UUID" },
      });
    },
  );

  // 2. edited_by_member_id에 UUID 포맷이 아닌 임의 문자열 전송 → 오류
  await TestValidator.error("edited_by_member_id 잘못된 포맷")(async () => {
    await api.functional.discussion_board.topicSnapshots.index(connection, {
      body: { edited_by_member_id: "INVALID-UUID-STRING!" },
    });
  });

  // 3. 포맷은 맞으나 DB에 존재하지 않는 discussion_board_topic_id 요청 → 빈 배열(data)
  const fakeUUID = typia.random<string & tags.Format<"uuid">>();
  const result = await api.functional.discussion_board.topicSnapshots.index(
    connection,
    {
      body: { discussion_board_topic_id: fakeUUID },
    },
  );
  typia.assert(result);
  TestValidator.equals("존재하지 않는 id이므로 빈 스냅샷 배열")(result.data)(
    [],
  );

  // 4. page/limit에 잘못된 값(0/-1/문자열 등) → 오류
  for (const value of [0, -1, "not_a_number"]) {
    await TestValidator.error("page의 타입 또는 범위 오류")(async () => {
      await api.functional.discussion_board.topicSnapshots.index(connection, {
        body: { page: value as any },
      });
    });
    await TestValidator.error("limit의 타입 또는 범위 오류")(async () => {
      await api.functional.discussion_board.topicSnapshots.index(connection, {
        body: { limit: value as any },
      });
    });
  }

  // 5. created_from/created_to에 잘못된 날짜 포맷, 숫자 등 입력 → 오류
  for (const key of ["created_from", "created_to"]) {
    for (const bad of ["NOT_A_DATE", 20240728]) {
      await TestValidator.error(`${key} 잘못된 값 입력`)(async () => {
        await api.functional.discussion_board.topicSnapshots.index(connection, {
          body: { [key]: bad as any },
        });
      });
    }
  }
}

