import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";

/**
 * Validate updating a report as admin with no actual field changes.
 *
 * This test ensures that when an admin attempts to update an existing report
 * (discussion_board_reports) with the same resolved status and description as
 * already stored (a no-op update), the record remains unchanged and the API
 * response matches the pre-update state as expected.
 *
 * Steps:
 *
 * 1. Member creates a new report (ensures there is something to update)
 * 2. As admin, perform an update on the report using the exact same 'resolved' and
 *    'description' fields as the current values (no actual change)
 * 3. Validate that the returned record matches the previous state (no unintended
 *    changes)
 */
export async function test_api_admin_discussion_board_reports_test_admin_update_report_with_no_changes(
  connection: api.IConnection,
) {
  // 1. Create new report as a member
  const createInput: IDiscussionBoardReport.ICreate = {
    reason_id: typia.random<string & tags.Format<"uuid">>(),
    reported_entity_id: typia.random<string & tags.Format<"uuid">>(),
    reported_entity_type: "post",
    description: "No-op update test",
  };
  const original: IDiscussionBoardReport =
    await api.functional.my.discussion_board.reports.create(connection, {
      body: createInput,
    });
  typia.assert(original);

  // 2. As admin, update with identical values (no changes)
  const updateInput: IDiscussionBoardReport.IUpdate = {
    resolved: original.resolved,
    description: original.description ?? null,
  };
  const updated: IDiscussionBoardReport =
    await api.functional.admin.discussion_board.reports.update(connection, {
      id: original.id,
      body: updateInput,
    });
  typia.assert(updated);

  // 3. Validate that the updated record matches the original
  TestValidator.equals("no-op update returns unchanged report")(updated)(
    original,
  );
}
